// ============================================================
// PLAYER FEEDBACK SYSTEM - Live chat simulation
// ============================================================
class PlayerFeedbackSystem {
private:
    std::vector<std::string> usernames = {
        "PixelNomad", "RealityGlitcher", "SandboxKing99", "Chronos_Shift", 
        "ModderV", "Builder_Bot", "LoreSeeker", "TimelineSurfer"
    };

    std::vector<std::string> featureRequests = {
        "Devs, when are we getting the reality shift mechanics??",
        "I'm tired of static maps. We need actions that actually change the timeline.",
        "Can we please get interlocking AI systems? I want factions to react to my builds.",
        "Plz add reality shifts. I want to see the lore change when I defeat a boss.",
        "Are we getting deep C++ modding access anytime soon? I have ideas.",
        "Survival is too easy now. We need dynamic alternate histories!",
        "If my actions don't permanently alter the environment, I'm out.",
        "We need an orchestral soundtrack that changes based on what timeline we trigger!"
    };

    int GetRandomIndex(int maxRange) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_int_distribution<> distr(0, maxRange - 1);
        return distr(gen);
    }

public:
    std::string GenerateFeedback() {
        std::string user = usernames[GetRandomIndex(usernames.size())];
        std::string request = featureRequests[GetRandomIndex(featureRequests.size())];
        return "[" + user + "]: " + request;
    }

    void RunSimulatedFeed(int numberOfMessages, int delayMilliseconds) {
        std::cout << "--- LIVE PLAYER FEEDBACK STARTING ---\n\n";
        
        for (int i = 0; i < numberOfMessages; ++i) {
            std::cout << GenerateFeedback() << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(delayMilliseconds));
        }
        
        std::cout << "\n--- FEED DISCONNECTED ---\n";
    }
};

// ============================================================
// VECTOR STRUCTS
// ============================================================
struct Vec2 {
    float x {0.0f};
    float y {0.0f};
};

static const float kPi = 3.14159265358979323846f;

static void enableTextureMipmapsTrilinear(Texture2D& tex) {
    if (tex.id == 0) {
        return;
    }
    GenTextureMipmaps(&tex);
    SetTextureFilter(tex, TEXTURE_FILTER_TRILINEAR);
}

struct Vec3 {
    float x {0.0f};
    float y {0.0f};
    float z {0.0f};

    Vec3() = default;
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3& operator+=(const Vec3& o) {
        x += o.x;
        y += o.y;
        z += o.z;
        return *this;
    }

    float length() const { return std::sqrt(x * x + y * y + z * z); }
    Vec3 normalized() const {
        const float len = length();
        if (len <= 0.00001f) {
            return {};
        }
        return {x / len, y / len, z / len};
    }

    float dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3 cross(const Vec3& o) const {
        return {
            y * o.z - z * o.y,
            z * o.x - x * o.z,
            x * o.y - y * o.x,
        };
    }
};

struct GameColor {
    int r {255};
    int g {255};
    int b {255};
    int a {255};

    static GameColor rgb(int rr, int gg, int bb, int aa = 255) {
        GameColor c {};
        c.r = std::max(0, std::min(rr, 255));
        c.g = std::max(0, std::min(gg, 255));
        c.b = std::max(0, std::min(bb, 255));
        c.a = std::max(0, std::min(aa, 255));
        return c;
    }
};

static float lerpFloat(float a, float b, float t) { return a + (b - a) * t; }
static Vec3 lerpVec3(const Vec3& a, const Vec3& b, float t) { return a + (b - a) * t; }
static GameColor lerpColor(const GameColor& a, const GameColor& b, float t) {
    return GameColor::rgb(
        static_cast<int>(lerpFloat(static_cast<float>(a.r), static_cast<float>(b.r), t)),
        static_cast<int>(lerpFloat(static_cast<float>(a.g), static_cast<float>(b.g), t)),
        static_cast<int>(lerpFloat(static_cast<float>(a.b), static_cast<float>(b.b), t)),
        static_cast<int>(lerpFloat(static_cast<float>(a.a), static_cast<float>(b.a), t))
    );
}

static ::Color mixColor(const ::Color& a, const ::Color& b, float t);

struct GameMesh {
    std::vector<Vec3> vertices {};
    std::vector<int> triangles {};
    std::vector<Vec3> normals {};
    std::vector<Vec2> uvs {};
    std::vector<GameColor> colors {};
};

struct Entity {
    GameMesh model {};
    Vec3 position {};
    Vec3 rotation {};
    Vec3 scale {1.0f, 1.0f, 1.0f};
    GameColor color {GameColor::rgb(255, 255, 255)};
    bool enabled {true};
    bool unlit {false};
    float alpha {1.0f};
    Vec3 velocity {};
};

struct ChunkKey {
    int x {0};
    int z {0};
    bool operator==(const ChunkKey& o) const { return x == o.x && z == o.z; }
};

struct ChunkHash {
    std::size_t operator()(const ChunkKey& key) const noexcept {
        const std::uint64_t a = static_cast<std::uint64_t>(static_cast<std::uint32_t>(key.x));
        const std::uint64_t b = static_cast<std::uint64_t>(static_cast<std::uint32_t>(key.z));
        return static_cast<std::size_t>((a << 32U) ^ b);
    }
};

class RNG {
public:
    RNG() : eng(static_cast<unsigned int>(std::time(nullptr))) {}
    float uniform(float lo, float hi) {
        std::uniform_real_distribution<float> dist(lo, hi);
        return dist(eng);
    }
    int uniformInt(int lo, int hi) {
        std::uniform_int_distribution<int> dist(lo, hi);
        return dist(eng);
    }

private:
    std::mt19937 eng;
};

static GameMesh createProceduralBoxMesh(float width = 1.0f, float height = 1.0f, float depth = 1.0f) {
    const float w = width / 2.0f;
    const float h = height / 2.0f;
    const float d = depth / 2.0f;

    GameMesh mesh {};
    mesh.vertices = {
        {-w, -h, d}, {w, -h, d}, {w, h, d}, {-w, h, d},
        {-w, -h, -d}, {-w, h, -d}, {w, h, -d}, {w, -h, -d},
        {-w, h, -d}, {-w, h, d}, {w, h, d}, {w, h, -d},
        {-w, -h, -d}, {w, -h, -d}, {w, -h, d}, {-w, -h, d},
        {w, -h, -d}, {w, h, -d}, {w, h, d}, {w, -h, d},
        {-w, -h, -d}, {-w, -h, d}, {-w, h, d}, {-w, h, -d}
    };
    mesh.triangles = {
        0, 1, 2, 0, 2, 3,
        4, 5, 6, 4, 6, 7,
        8, 9, 10, 8, 10, 11,
        12, 13, 14, 12, 14, 15,
        16, 17, 18, 16, 18, 19,
        20, 21, 22, 20, 22, 23
    };
    return mesh;
}

static GameMesh createProceduralSphereMesh(float radius = 1.0f, int segments = 16, int rings = 12) {
    GameMesh mesh {};

    for (int ring = 0; ring <= rings; ++ring) {
        const float ringAngle = (static_cast<float>(ring) / static_cast<float>(rings)) * kPi;
        const float ringRadius = std::sin(ringAngle) * radius;
        const float ringY = std::cos(ringAngle) * radius;

        for (int seg = 0; seg < segments; ++seg) {
            const float segAngle = (static_cast<float>(seg) / static_cast<float>(segments)) * 2.0f * kPi;
            mesh.vertices.push_back({std::cos(segAngle) * ringRadius, ringY, std::sin(segAngle) * ringRadius});
        }
    }

    for (int ring = 0; ring < rings; ++ring) {
        for (int seg = 0; seg < segments; ++seg) {
            const int current = ring * segments + seg;
            const int nextSeg = ring * segments + ((seg + 1) % segments);
            const int upper = (ring + 1) * segments + seg;
            const int upperNext = (ring + 1) * segments + ((seg + 1) % segments);
            mesh.triangles.insert(mesh.triangles.end(), {current, upper, nextSeg, nextSeg, upper, upperNext});
        }
    }

    return mesh;
}

class AfricanTerrain {
public:
    AfricanTerrain() {
        loadTerrainImage();
        setupTerrainMaterial();
    }

    virtual ~AfricanTerrain() = default;

    void loadTerrainImage() {
        // TODO: Read African Terrarian image and fill imageHeightData/imageColorData.
        terrainImageLoaded = false;
    }

    void setupTerrainMaterial() {
        // TODO: Hook engine shader selection.
    }

    Entity generateChunk(int chunkX, int chunkZ) {
        const ChunkKey key {chunkX, chunkZ};
        const auto it = chunks.find(key);
        if (it != chunks.end()) {
            return it->second;
        }

        Entity terrainEntity {};
        terrainEntity.position = Vec3(static_cast<float>(chunkX * chunkSize), 0.0f, static_cast<float>(chunkZ * chunkSize));

        const int resolution = 64;
        GameMesh mesh {};
        for (int z = 0; z <= resolution; ++z) {
            for (int x = 0; x <= resolution; ++x) {
                const float worldX = static_cast<float>(chunkX * chunkSize) + (static_cast<float>(x) / static_cast<float>(resolution)) * static_cast<float>(chunkSize);
                const float worldZ = static_cast<float>(chunkZ * chunkSize) + (static_cast<float>(z) / static_cast<float>(resolution)) * static_cast<float>(chunkSize);
                const float height = getHeight(worldX, worldZ);

                mesh.vertices.push_back({worldX, height, worldZ});
                mesh.uvs.push_back({static_cast<float>(x) / static_cast<float>(resolution), static_cast<float>(z) / static_cast<float>(resolution)});
                mesh.colors.push_back(getTerrainColor(worldX, worldZ, height));
            }
        }

        for (int z = 0; z < resolution; ++z) {
            for (int x = 0; x < resolution; ++x) {
                const int i = z * (resolution + 1) + x;
                mesh.triangles.insert(mesh.triangles.end(), {
                    i, i + 1, i + resolution + 1,
                    i + 1, i + resolution + 2, i + resolution + 1
                });
            }
        }

        mesh.normals = calculateNormals(mesh.vertices, mesh.triangles);
        terrainEntity.model = std::move(mesh);

        chunks.emplace(key, terrainEntity);
        return terrainEntity;
    }

    /** Minecraft-style: keep a sliding window of chunks around the player; drop far ones. */
    void streamChunksAround(float worldX, float worldZ, int keepRadius = 4) {
        const int cx = static_cast<int>(std::floor(worldX / static_cast<float>(chunkSize)));
        const int cz = static_cast<int>(std::floor(worldZ / static_cast<float>(chunkSize)));
        for (int dz = -keepRadius; dz <= keepRadius; ++dz) {
            for (int dx = -keepRadius; dx <= keepRadius; ++dx) {
                generateChunk(cx + dx, cz + dz); 
            }
        }
        const int drop = keepRadius + 2;
        for (auto it = chunks.begin(); it != chunks.end();) {
            if (std::abs(it->first.x - cx) > drop || std::abs(it->first.z - cz) > drop) {
                it = chunks.erase(it);
            } else {
                ++it;
            }
        }
    }

    /**
     * Infinite seeded height — continuous for every (x,z), no wrap, no map edge.
     * Multi-octave fbm like Minecraft continental noise (gentle savanna bias).
     */
    virtual float getHeight(float x, float z) const {
        const float nx = x * 0.00115f;
        const float nz = z * 0.00115f;
        float h = 0.0f;
        // Slightly fewer octaves than before — same silhouette, much cheaper per sample
        // (terrain LOD / grass / trees call this thousands of times a frame).
        h += terrainFbm(nx, nz, 4, worldSeed) * 22.0f;
        h += terrainFbm(nx * 2.7f + 11.0f, nz * 2.7f - 7.0f, 3, worldSeed + 17) * 7.5f;
        h += terrainFbm(nx * 9.0f, nz * 9.0f, 2, worldSeed + 41) * 1.6f;
        // Soft plains / valley mask so most of the world stays walkable savanna
        const float plains = terrainFbm(nx * 0.35f + 3.1f, nz * 0.35f + 1.7f, 2, worldSeed + 3);
        h *= 0.28f + 0.72f * plains;

        // Watering holes — the summed noise above almost never dips under the
        // waterline (~1.0), so without this the world has NO water at all.
        // One shallow pond per 640 m cell, carved below the waterline; the
        // Gold Mine water surface + the trailer's Watering Hole shot find it.
        {
            constexpr float kPondCell = 640.0f;
            constexpr float kPondR = 24.0f;
            const auto pondHash = [](int hx, int hz) {
                std::uint32_t n = static_cast<std::uint32_t>(hx) * 374761393u
                                + static_cast<std::uint32_t>(hz) * 668265263u;
                n = (n ^ (n >> 13U)) * 1274126177u;
                n ^= (n >> 16U);
                return static_cast<float>(n & 0xFFFFu) / 65535.0f;
            };
            const int pcx = static_cast<int>(std::floor(x / kPondCell));
            const int pcz = static_cast<int>(std::floor(z / kPondCell));
            const float pondX = (static_cast<float>(pcx) + 0.5f) * kPondCell
                              + (pondHash(pcx * 3 + 7, pcz * 5 + 1) - 0.5f) * 160.0f;
            const float pondZ = (static_cast<float>(pcz) + 0.5f) * kPondCell
                              + (pondHash(pcx * 9 + 4, pcz * 7 + 6) - 0.5f) * 160.0f;
            const float pdx = x - pondX;
            const float pdz = z - pondZ;
            const float pd2 = pdx * pdx + pdz * pdz;
            if (pd2 < kPondR * kPondR) {
                const float t = 1.0f - std::sqrt(pd2) / kPondR;
                const float bowl = t * t * (3.0f - 2.0f * t);  // smoothstep rim
                h = h * (1.0f - bowl) + 0.2f * bowl;           // floor ~0.2 m
            }
        }
        return std::max(0.0f, h);
    }

    GameColor getTerrainColor(float /*x*/, float /*z*/, float height) const {
        if (height < 2.0f) {
            return GameColor::rgb(50, 100, 30);
        }
        if (height < 8.0f) {
            return GameColor::rgb(80, 60, 40);
        }
        return GameColor::rgb(60, 50, 40);
    }

    static std::vector<Vec3> calculateNormals(const std::vector<Vec3>& vertices, const std::vector<int>& triangles) {
        std::vector<Vec3> normals(vertices.size(), {0.0f, 1.0f, 0.0f});
        for (std::size_t i = 0; i + 2 < triangles.size(); i += 3) {
            const Vec3& v0 = vertices[static_cast<std::size_t>(triangles[i])];
            const Vec3& v1 = vertices[static_cast<std::size_t>(triangles[i + 1])];
            const Vec3& v2 = vertices[static_cast<std::size_t>(triangles[i + 2])];
            const Vec3 face = (v1 - v0).cross(v2 - v0).normalized();
            normals[static_cast<std::size_t>(triangles[i])] += face;
            normals[static_cast<std::size_t>(triangles[i + 1])] += face;
            normals[static_cast<std::size_t>(triangles[i + 2])] += face;
        }
        for (Vec3& n : normals) {
            n = n.normalized();
        }
        return normals;
    }

    std::size_t chunkCount() const { return chunks.size(); }

    int chunkSize {64};          // meters per streamed chunk
    float terrainScale {20.0f};
    int worldSeed {20260810};    // reproducible infinite world

protected:
    static float terrainHash(int x, int z, int seed) {
        std::uint32_t n = static_cast<std::uint32_t>(x) * 374761393u
                        + static_cast<std::uint32_t>(z) * 668265263u
                        + static_cast<std::uint32_t>(seed) * 144665137u;
        n = (n ^ (n >> 13U)) * 1274126177u;
        n ^= (n >> 16U);
        return static_cast<float>(n & 0xFFFFu) / 65535.0f;
    }

    static float terrainVNoise(float x, float y, int seed) {
        const int xi = static_cast<int>(std::floor(x));
        const int yi = static_cast<int>(std::floor(y));
        const float xf = x - static_cast<float>(xi);
        const float yf = y - static_cast<float>(yi);
        const float u = xf * xf * (3.0f - 2.0f * xf);
        const float v = yf * yf * (3.0f - 2.0f * yf);
        const float a = terrainHash(xi, yi, seed);
        const float b = terrainHash(xi + 1, yi, seed);
        const float c = terrainHash(xi, yi + 1, seed);
        const float d = terrainHash(xi + 1, yi + 1, seed);
        return (a * (1.0f - u) + b * u) * (1.0f - v) + (c * (1.0f - u) + d * u) * v;
    }

    static float terrainFbm(float x, float y, int oct, int seed) {
        float s = 0.0f, amp = 0.5f, f = 1.0f;
        for (int i = 0; i < oct; ++i) {
            s += terrainVNoise(x * f, y * f, seed + i * 71) * amp;
            amp *= 0.5f;
            f *= 2.0f;
        }
        return s;
    }

    bool terrainImageLoaded {false};
    std::unordered_map<ChunkKey, Entity, ChunkHash> chunks {};
};

class EnhancedAfricanTerrain : public AfricanTerrain {
public:
    EnhancedAfricanTerrain() { tryLoadGaeaHeightAsset(); }

    // Natural (undug) height — dig brush subtracts from this.
    float naturalHeight(float x, float z) const {
        return AfricanTerrain::getHeight(x, z);
    }

    float getHeight(float x, float z) const override {
        // Always infinite seeded terrain (Minecraft-style). Finite Gaea heightfields
        // used to wrap and tile — that breaks open-world travel.
        return std::max(0.0f, naturalHeight(x, z) - digDeltaAt(x, z));
    }

    // Valheim-style hoe dig: soft bowl, ~3 blocks (metres) deep per click.
    // Returns how many Pile of Soil items to grant (0 if already at max depth).
    int digAt(float x, float z) {
        const float radius = kDigRadius;
        const float depth = kDigDepthPerClick;
        float applied = 0.0f;
        const int rCells = static_cast<int>(std::ceil(radius / kEditCell)) + 1;
        const int ix0 = static_cast<int>(std::floor(x / kEditCell));
        const int iz0 = static_cast<int>(std::floor(z / kEditCell));
        for (int iz = iz0 - rCells; iz <= iz0 + rCells; ++iz) {
            for (int ix = ix0 - rCells; ix <= ix0 + rCells; ++ix) {
                const float cx = (static_cast<float>(ix) + 0.5f) * kEditCell;
                const float cz = (static_cast<float>(iz) + 0.5f) * kEditCell;
                const float dx = cx - x;
                const float dz = cz - z;
                const float d2 = dx * dx + dz * dz;
                if (d2 > radius * radius) continue;
                const float t = 1.0f - std::sqrt(d2) / radius;
                const float falloff = t * t; // deeper in the centre, like Valheim
                const float want = depth * (0.40f + 0.60f * falloff);
                const long long key = editKey(ix, iz);
                float& cur = digCells[key];
                const float room = kMaxDigDepth - cur;
                if (room <= 0.001f) continue;
                const float add = std::min(want, room);
                cur += add;
                applied += add;
            }
        }
        if (applied < 0.08f) return 0;
        digPits.push_back({x, z, radius, kFoliageClear});
        // One click ≈ three blocks of earth into the satchel.
        return 3;
    }

    float digDeltaAt(float x, float z) const {
        if (digCells.empty()) return 0.0f;
        const float inv = 1.0f / kEditCell;
        const float fx = x * inv;
        const float fz = z * inv;
        const int x0 = static_cast<int>(std::floor(fx));
        const int z0 = static_cast<int>(std::floor(fz));
        const float tx = fx - static_cast<float>(x0);
        const float tz = fz - static_cast<float>(z0);
        const float a = digSample(x0, z0);
        const float b = digSample(x0 + 1, z0);
        const float c = digSample(x0, z0 + 1);
        const float d = digSample(x0 + 1, z0 + 1);
        const float ab = a + (b - a) * tx;
        const float cd = c + (d - c) * tx;
        return ab + (cd - ab) * tz;
    }

    // True if this world point sits inside any dig brush (grass/ground must not draw here).
    bool isExcavated(float x, float z, float margin = 0.0f) const {
        if (digDeltaAt(x, z) > 0.01f) return true;
        for (const DigPit& p : digPits) {
            const float dx = x - p.x;
            const float dz = z - p.z;
            const float r = p.radius + 1.25f + margin;
            if (dx * dx + dz * dz <= r * r) return true;
        }
        return false;
    }

    // Skip grass only inside real dig bowls — not a huge foliageClear disc
    // (that was wiping the whole carpet after a few digs).
    bool foliageBlocked(float x, float z, float visualRadius) const {
        if (digDeltaAt(x, z) > 0.25f) return true;
        for (const DigPit& p : digPits) {
            const float dx = x - p.x;
            const float dz = z - p.z;
            const float r = p.radius + 1.4f + visualRadius * 0.2f;
            if (dx * dx + dz * dz <= r * r) return true;
        }
        return false;
    }

    // True if a ground tile footprint overlaps a dig (tiles are large — center-only tests fail).
    bool isExcavatedNear(float x, float z, float footprintRadius) const {
        if (digDeltaAt(x, z) > 0.01f) return true;
        if (naturalHeight(x, z) - getHeight(x, z) > 0.2f) return true;
        for (const DigPit& p : digPits) {
            const float dx = x - p.x;
            const float dz = z - p.z;
            const float r = p.radius + 1.5f + footprintRadius * 0.55f;
            if (dx * dx + dz * dz <= r * r) return true;
        }
        // Sample ring so large tiles still punch a hole when the dig is off-centre.
        constexpr int kRing = 8;
        for (int i = 0; i < kRing; ++i) {
            const float a = (static_cast<float>(i) / static_cast<float>(kRing)) * 6.2831853f;
            const float sx = x + std::cos(a) * footprintRadius * 0.85f;
            const float sz = z + std::sin(a) * footprintRadius * 0.85f;
            if (digDeltaAt(sx, sz) > 0.01f) return true;
            for (const DigPit& p : digPits) {
                const float ddx = sx - p.x;
                const float ddz = sz - p.z;
                const float rr = p.radius + 1.5f;
                if (ddx * ddx + ddz * ddz <= rr * rr) return true;
            }
        }
        return false;
    }

    static constexpr float kDigRadius = 2.6f;
    static constexpr float kDigDepthPerClick = 9.0f; // three "blocks" down
    static constexpr float kMaxDigDepth = 32.0f;       // three full digs
    static constexpr float kEditCell = 0.75f;
    static constexpr float kFoliageClear = 4.5f;     // natural tufts — smaller clear than pancake era

    struct DigPit {
        float x {0.0f};
        float z {0.0f};
        float radius {2.6f};
        float foliageClear {10.0f};
    };

    Vec2 recommendedSpawnXZ() const {
        return {0.0f, 0.0f};
    }

    bool usesGaea500ftPreview() const { return usingGaeaPreviewHeightfield; }
    float gaeaHeightRangeMeters() const { return hfVerticalScale; }

    GameMesh createOrganicCylinder(float radius = 0.5f, float height = 1.0f, int segments = 8) {
        GameMesh mesh {};
        const float bottomY = -height / 2.0f;
        const float topY = height / 2.0f;

        mesh.vertices.push_back({0.0f, bottomY, 0.0f});
        mesh.vertices.push_back({0.0f, topY, 0.0f});

        for (int i = 0; i < segments; ++i) {
            const float angle = (static_cast<float>(i) / static_cast<float>(segments)) * 2.0f * kPi;
            const float bv = rng.uniform(0.8f, 1.2f);
            const float tv = rng.uniform(0.85f, 1.15f);
            mesh.vertices.push_back({std::cos(angle) * radius * bv, bottomY, std::sin(angle) * radius * bv});
            mesh.vertices.push_back({std::cos(angle) * radius * tv, topY, std::sin(angle) * radius * tv});
        }

        for (int i = 0; i < segments; ++i) {
            const int next = (i + 1) % segments;
            mesh.triangles.insert(mesh.triangles.end(), {
                0, 2 + i * 2, 2 + next * 2,
                1, 3 + next * 2, 3 + i * 2,
                2 + i * 2, 3 + i * 2, 2 + next * 2,
                2 + next * 2, 3 + i * 2, 3 + next * 2
            });
        }
        return mesh;
    }
    
    GameMesh createOrganicBlob(float radius = 1.0f, int segments = 8) {
        GameMesh mesh {};
        for (int ring = 0; ring <= segments; ++ring) {
            const float ringAngle = (static_cast<float>(ring) / static_cast<float>(segments)) * kPi;
            const float ringRadius = std::sin(ringAngle) * radius;
            const float ringY = std::cos(ringAngle) * radius;

            for (int seg = 0; seg < segments; ++seg) {
                const float segAngle = (static_cast<float>(seg) / static_cast<float>(segments)) * 2.0f * kPi;
                const float deform = rng.uniform(0.7f, 1.3f);
                const float nx = std::sin(segAngle * 3.0f) * 0.2f;
                const float nz = std::cos(segAngle * 3.0f) * 0.2f;
                const float x = (std::cos(segAngle) * ringRadius + nx) * deform;
                const float z = (std::sin(segAngle) * ringRadius + nz) * deform;
                const float y = ringY * rng.uniform(0.8f, 1.2f);
                mesh.vertices.push_back({x, y, z});
            }
        }

        for (int ring = 0; ring < segments; ++ring) {
            for (int seg = 0; seg < segments; ++seg) {
                const int current = ring * segments + seg;
                const int nextSeg = ring * segments + ((seg + 1) % segments);
                const int upper = (ring + 1) * segments + seg;
                const int upperNext = (ring + 1) * segments + ((seg + 1) % segments);
                mesh.triangles.insert(mesh.triangles.end(), {current, upper, nextSeg, nextSeg, upper, upperNext});
            }
        }
        return mesh;
    }

    GameMesh createIrregularRockMesh(float baseSize = 1.0f, float irregularity = 0.5f) {
        GameMesh mesh {};
        const int segments = 6;
        const int rings = 4;

        for (int ring = 0; ring <= rings; ++ring) {
            const float ringAngle = (static_cast<float>(ring) / static_cast<float>(rings)) * kPi;
            const float ringRadius = std::sin(ringAngle) * baseSize;
            const float ringY = std::cos(ringAngle) * baseSize;

            for (int seg = 0; seg < segments; ++seg) {
                const float segAngle = (static_cast<float>(seg) / static_cast<float>(segments)) * 2.0f * kPi;
                const float irregularFactor = rng.uniform(1.0f - irregularity, 1.0f + irregularity);
                const float noiseFactor =
                    (std::sin(segAngle * 2.5f) * 0.3f + std::cos(ringAngle * 3.0f) * 0.2f + rng.uniform(-0.2f, 0.2f)) * irregularity;

                const float rv = ringRadius * irregularFactor * (1.0f + noiseFactor);
                const float yv = ringY * rng.uniform(0.7f, 1.3f);
                const float x = std::cos(segAngle) * rv;
                const float z = std::sin(segAngle) * rv;
                const float bump = std::sin(x * 8.0f) * std::cos(z * 8.0f) * 0.1f + rng.uniform(-0.05f, 0.05f);
                mesh.vertices.push_back({x + bump, yv + bump * 0.5f, z + bump});
            }
        }

        for (int ring = 0; ring < rings; ++ring) {
            for (int seg = 0; seg < segments; ++seg) {
                const int current = ring * segments + seg;
                const int nextSeg = ring * segments + ((seg + 1) % segments);
                const int upper = (ring + 1) * segments + seg;
                const int upperNext = (ring + 1) * segments + ((seg + 1) % segments);
                mesh.triangles.insert(mesh.triangles.end(), {current, upper, nextSeg, nextSeg, upper, upperNext});
            }
        }
        return mesh;
    }

    int populateWithAssets(int numTrees = 20, int numRocks = 25) {
        vegetation.clear();
        rockFormations.clear();

        for (int i = 0; i < numTrees; ++i) {
            const float x = rng.uniform(-80.0f, 80.0f);
            const float z = rng.uniform(-80.0f, 80.0f);
            const float y = getHeight(x, z);
            if (y > 1.0f && y < 15.0f) {
                vegetation.push_back(createSimpleTree(x, y, z));
            }
        }

        for (int i = 0; i < numRocks; ++i) {
            const float x = rng.uniform(-90.0f, 90.0f);
            const float z = rng.uniform(-90.0f, 90.0f);
            const float y = getHeight(x, z);
            if (y > 3.0f) {
                rockFormations.push_back(createSimpleRock(x, y, z));
            }
        }

        return static_cast<int>(vegetation.size() + rockFormations.size());
    }

private:
    void tryLoadGaeaHeightAsset();
    float sampleHeightmapBilinear(float x, float z) const;

    static long long editKey(int ix, int iz) {
        return (static_cast<long long>(ix) << 32)
             ^ static_cast<long long>(static_cast<std::uint32_t>(iz));
    }

    float digSample(int ix, int iz) const {
        const auto it = digCells.find(editKey(ix, iz));
        return (it == digCells.end()) ? 0.0f : it->second;
    }

    std::unordered_map<long long, float> digCells {};
    std::vector<DigPit> digPits {};

    std::vector<float> heightfield {};
    int hfW {0};
    int hfH {0};
    float worldExtentX {200.0f};
    float worldExtentZ {200.0f};
    float hfVerticalScale {520.0f};
    bool hasHeightfield {false};
    bool usingGaeaPreviewHeightfield {false};

    Entity createSimpleTree(float x, float y, float z) {
        Entity tree {};
        tree.model = createOrganicCylinder(0.15f, rng.uniform(3.0f, 5.0f), 8);
        tree.position = {x, y, z};
        tree.color = GameColor::rgb(101, 67, 33);
        return tree;
    }

    Entity createSimpleRock(float x, float y, float z) {
        Entity rock {};
        rock.model = createIrregularRockMesh(rng.uniform(0.8f, 1.5f), 0.5f);
        rock.position = {x, y + 0.2f, z};
        rock.color = GameColor::rgb(rng.uniformInt(90, 130), rng.uniformInt(85, 115), rng.uniformInt(75, 105));
        return rock;
    }

    RNG rng {};
    std::vector<Entity> vegetation {};
    std::vector<Entity> rockFormations {};
};

static bool readTextFileWhole(const std::string& path, std::string* out) {
    std::ifstream f(path, std::ios::binary);
    if (!f) {
        return false;
    }
    out->assign(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());
    return !out->empty();
}

static bool parseGaeaTerrainExtentsFromJson(const std::string& json, float* worldX, float* worldZ) {
    const std::string key = "\"Width\"";
    std::size_t pos = 0;
    while ((pos = json.find(key, pos)) != std::string::npos) {
        std::size_t colon = json.find(':', pos + key.size());
        if (colon == std::string::npos) {
            break;
        }
        ++colon;
        while (colon < json.size() && std::isspace(static_cast<unsigned char>(json[colon]))) {
            ++colon;
        }
        std::size_t numEnd = colon;
        while (numEnd < json.size() && (std::isdigit(static_cast<unsigned char>(json[numEnd])) || json[numEnd] == '.' || json[numEnd] == '-')) {
            ++numEnd;
        }
        if (numEnd == colon) {
            ++pos;
            continue;
        }
        float w = 0.0f;
        try {
            w = std::stof(json.substr(colon, numEnd - colon));
        } catch (...) {
            pos = numEnd;
            continue;
        }
        if (w < 80.0f) {
            pos = numEnd;
            continue;
        }

        const std::size_t hKey = json.find("\"Height\"", numEnd);
        if (hKey == std::string::npos || hKey > numEnd + 220U) {
            pos = numEnd;
            continue;
        }
        std::size_t hColon = json.find(':', hKey + 8U);
        if (hColon == std::string::npos) {
            ++pos;
            continue;
        }
        ++hColon;
        while (hColon < json.size() && std::isspace(static_cast<unsigned char>(json[hColon]))) {
            ++hColon;
        }
        std::size_t hEnd = hColon;
        while (hEnd < json.size() && (std::isdigit(static_cast<unsigned char>(json[hEnd])) || json[hEnd] == '.' || json[hEnd] == '-')) {
            ++hEnd;
        }
        if (hEnd == hColon) {
            ++pos;
            continue;
        }
        float h = 0.0f;
        try {
            h = std::stof(json.substr(hColon, hEnd - hColon));
        } catch (...) {
            pos = hEnd;
            continue;
        }
        if (h < 80.0f) {
            pos = hEnd;
            continue;
        }

        *worldX = w;
        *worldZ = h;
        return true;
    }
    return false;
}

static float hashNoise2D(int x, int z);
static bool inWorldTearScar(float x, float z);

static bool loadHeightfieldFromExr(
    const std::string& exrPath,
    std::vector<float>* outHeightfield,
    int* outW,
    int* outH,
    float verticalScale
) {
    float* rgba = nullptr;
    int w = 0;
    int h = 0;
    const char* err = nullptr;
    const int ret = LoadEXR(&rgba, &w, &h, exrPath.c_str(), &err);
    if (ret != TINYEXR_SUCCESS || rgba == nullptr || w <= 0 || h <= 0) {
        if (err != nullptr) {
            std::cout << "EXR decode failed for " << exrPath << ": " << err << '\n';
            FreeEXRErrorMessage(err);
        } else {
            std::cout << "EXR decode failed for " << exrPath << " (unknown error)\n";
        }
        if (rgba != nullptr) {
            free(rgba);
        }
        return false;
    }

    const std::size_t pixelCount = static_cast<std::size_t>(w) * static_cast<std::size_t>(h);
    std::vector<float> linearHeights(pixelCount, 0.0f);

    float minV = std::numeric_limits<float>::max();
    float maxV = std::numeric_limits<float>::lowest();
    for (std::size_t i = 0; i < pixelCount; ++i) {
        const float r = rgba[i * 4 + 0];
        linearHeights[i] = r;
        minV = std::min(minV, r);
        maxV = std::max(maxV, r);
    }
    free(rgba);

    const float range = maxV - minV;
    if (!std::isfinite(range) || range <= 1.0e-8f) {
        std::cout << "EXR has invalid/flat range for " << exrPath << " (min=" << minV << ", max=" << maxV << ")\n";
        return false;
    }

    outHeightfield->resize(pixelCount);
    for (std::size_t i = 0; i < pixelCount; ++i) {
        float t = (linearHeights[i] - minV) / range;
        t = std::max(0.0f, std::min(1.0f, t));
        // Aggressive boost: EXR range is only ~11%, so push contrast hard.
        t = std::pow(t, 0.38f);
        (*outHeightfield)[i] = t * verticalScale;
    }
    *outW = w;
    *outH = h;
    std::cout << "Loaded EXR with TinyEXR: " << exrPath << " (" << w << " x " << h
              << "), normalized from [" << minV << ", " << maxV << "]\n";
    return true;
}

