// ============================================================
enum class ItemKind : int {
    None = 0,
    Material,
    Seed,
    Consumable,
    Focus,
    Field,
    Relic,
    Knowledge
};

enum class VesselId : int {
    Unchosen = 0,
    Althea,
    Angela,
    Jenna,
    Freya,
    Aleanea,
    Visitor
};

enum class InvPane : int {
    None = 0,
    Bag,
    Hotbar,
    Equip
};

struct ItemDef {
    int id {0};
    const char* name {""};
    const char* kindLabel {""};
    const char* description {""};
    ItemKind kind {ItemKind::None};
    int maxStack {1};
    ::Color ink {245, 230, 200, 255};
    ::Color glow {212, 137, 26, 255};
};

struct InventorySlot {
    int itemId {0};
    int count {0};

    bool empty() const { return itemId <= 0 || count <= 0; }
    void clear() {
        itemId = 0;
        count = 0;
    }
};

struct SlotRef {
    InvPane pane {InvPane::None};
    int index {-1};

    bool valid() const { return pane != InvPane::None && index >= 0; }
    bool operator==(const SlotRef& o) const { return pane == o.pane && index == o.index; }
};

