    // ── roster ──────────────────────────────────────────────
    bool playable(int idx) const {
        if (idx < 0 || idx >= static_cast<int>(VesselRoster::kCount)) return false;
        return VesselRoster::isPlayable(VesselRoster::kRoster[static_cast<std::size_t>(idx)], profile);
    }
    /** The vessel you will spawn as. Falls back to the starter so gameplay
     *  never has to cope with "nobody selected". */
    int chosenIndex() const {
        if (chosenVessel >= 0 && playable(chosenVessel)) return chosenVessel;
        return VesselRoster::starterIndex();
    }
    const VesselRoster::Def& chosenDef() const {
        return VesselRoster::kRoster[static_cast<std::size_t>(chosenIndex())];
    }
    VesselRoster::Kit chosenKit() const { return chosenDef().kit; }
    PlayerProfile& playerProfile() { return profile; }
    const PlayerProfile& playerProfile() const { return profile; }

    void selectVessel(int idx) {
        if (!playable(idx)) {
            noticeAt = static_cast<float>(GetTime());
            return;
        }
        chosenVessel = idx;
        vesselChosen = true;
        vesselSelectAt = static_cast<float>(GetTime());
        const VesselRoster::Def& d = VesselRoster::kRoster[static_cast<std::size_t>(idx)];
        profile.setLastVessel(d.id);
        profile.saveIfDirty();
        std::cout << "Vessel selected: " << d.name << " - " << d.subtitle
                  << " (" << d.tags << ")\n";
    }

    /** Award a challenge. Returns true the first time, so the caller can
     *  fire the banner exactly once. */
    bool grantUnlock(const char* id) {
        const int idx = VesselRoster::indexOfId(id);
        if (idx < 0) return false;
        if (!profile.unlock(id)) return false;
        profile.saveIfDirty();
        unlockBannerAt = static_cast<float>(GetTime());
        unlockBannerName = VesselRoster::kRoster[static_cast<std::size_t>(idx)].name;
        return true;
    }
    bool unlockBannerActive(float now) const {
        return unlockBannerAt >= 0.0f && now - unlockBannerAt < 6.0f;
    }
    float unlockBannerAge(float now) const { return now - unlockBannerAt; }
    const std::string& unlockBannerVessel() const { return unlockBannerName; }

    const WorldMeta* activeWorld() const {
        return activeWorldValid ? &activeWorldMeta : nullptr;
    }
    const std::string& activeWorldPath() const { return activeWorldPathStr; }
    /** Legacy name — trailer paths still call this. Prefer selectAngelaStarter
     *  for freeplay world entry. */
    void selectAlthea() { selectVessel(chosenIndex()); }

    /** Every new run begins as Angela, The First Hands. Higher vessels are
     *  earned unlocks and only enter play through the soul realm cord. */
    void selectAngelaStarter() {
        selectVessel(VesselRoster::starterIndex());
        rosterCursor = VesselRoster::starterIndex();
    }

    /** Resume the incarnation this world seed last wore (sandbox alternate history). */
    void selectWorldIncarnation(const WorldMeta& m) {
        // Morph seeds unlock Morph — they do NOT force the Visitor incarnation.
        morphUnlockedThisWorld = GameModes::isMorphSeed(m.seed)
            || profile.stats().visitorSeedUnlocks > 0
            || profile.isUnlocked(GameModes::visitorVesselId());
        if (GameModes::isMorphSeed(m.seed)) {
            if (profile.stats().visitorSeedUnlocks <= 0) {
                profile.noteVisitorSeed();
            }
            profile.unlock(GameModes::visitorVesselId());
            profile.saveIfDirty();
            morphUnlockedThisWorld = true;
        }
        morphFormCursor = 0; // TRUE FORM
        refreshMorphCatalog();

        const int idx = VesselRoster::indexOfId(m.incarnationVessel);
        if (idx < 0
            || !VesselRoster::isPlayable(VesselRoster::kRoster[static_cast<std::size_t>(idx)],
                                         profile)) {
            selectAngelaStarter();
            return;
        }
        selectVessel(idx);
        rosterCursor = idx;
    }

    void refreshMorphCatalog() {
        morphCatalog = PlayerMorph::buildCatalog(profile, morphUnlockedThisWorld);
        if (morphFormCursor < 0 || morphFormCursor >= static_cast<int>(morphCatalog.size())) {
            morphFormCursor = 0;
        }
    }

    bool morphEnabled() const { return morphUnlockedThisWorld; }

    void cycleMorph(int delta) {
        if (!morphUnlockedThisWorld) return;
        refreshMorphCatalog();
        if (morphCatalog.empty()) return;
        const int n = static_cast<int>(morphCatalog.size());
        morphFormCursor = ((morphFormCursor + delta) % n + n) % n;
        const PlayerMorph::Form& f = morphCatalog[static_cast<std::size_t>(morphFormCursor)];
        if (f.rosterIndex >= 0) loadVessel(f.rosterIndex);
    }

    const char* morphLabel() const {
        if (!morphUnlockedThisWorld || morphCatalog.empty()) return "TRUE FORM";
        return morphCatalog[static_cast<std::size_t>(morphFormCursor)].label;
    }

    /** Roster index to DRAW (morph costume), or chosen incarnation if TRUE FORM. */
    int visualVesselIndex() const {
        if (!morphUnlockedThisWorld || morphCatalog.empty()) return chosenIndex();
        const PlayerMorph::Form& f = morphCatalog[static_cast<std::size_t>(morphFormCursor)];
        if (f.rosterIndex < 0) return chosenIndex();
        return f.rosterIndex;
    }

    bool persistActiveIncarnation(const char* vesselId, int tier) {
        if (!activeWorldValid) return false;
        return WorldSaveStore::saveIncarnation(activeWorldMeta, vesselId, tier);
    }

    bool persistLampProgress(int pct) {
        if (!activeWorldValid) return false;
        return WorldSaveStore::saveLampProgress(activeWorldMeta, pct);
    }

    /** Offline demo — binds Demo Island and returns true when ready to load. */
    bool prepareDemoWorld() {
        WorldMeta created {};
        if (!WorldSaveStore::createWorld("Demo Island", "DEMO45",
                                        GameModes::idString(GameModes::Id::Sandbox), &created)) {
            created = {};
            for (const WorldMeta& w : WorldSaveStore::listWorlds()) {
                if (w.seed == "DEMO45" || w.name == "Demo Island") {
                    created = w;
                    break;
                }
            }
        }
        if (created.name.empty()) return false;
        activeWorldMeta = created;
        WorldSaveStore::touchLastPlayed(activeWorldMeta);
        activeWorldPathStr = activeWorldMeta.path.string();
        activeWorldValid = true;
        selectWorldIncarnation(activeWorldMeta);
        worldChronicle.bind(activeWorldMeta.path);
        pendingWorldDrift = false;
        pendingAwayHours = 0.0;
        // Demo mode is shelved for later — prepareDemoWorld only binds the world.
        return true;
    }

    WorldChronicle& chronicle() { return worldChronicle; }
    bool consumeWorldDrift(double* outHours) {
        if (!pendingWorldDrift) return false;
        pendingWorldDrift = false;
        if (outHours) *outHours = pendingAwayHours;
        pendingAwayHours = 0.0;
        return true;
    }

    GameModes::Id activeGameMode() const {
        if (!activeWorldValid) return GameModes::Id::Sandbox;
        return GameModes::fromString(activeWorldMeta.gameMode);
    }

    int lampProgress() const {
        return activeWorldValid ? activeWorldMeta.lampProgress : 0;
    }

