    void loadSkyDecalTextures() {
        constexpr int n = 128;
        Image sun = GenImageColor(n, n, BLANK);
        for (int y = 0; y < n; ++y) {
            for (int x = 0; x < n; ++x) {
                const float dx = (static_cast<float>(x) + 0.5f) / static_cast<float>(n) - 0.5f;
                const float dy = (static_cast<float>(y) + 0.5f) / static_cast<float>(n) - 0.5f;
                const float d = std::sqrt(dx * dx + dy * dy) / 0.5f;
                if (d > 1.0f) {
                    continue;
                }
                const float a = (1.0f - d) * (1.0f - d);
                const unsigned char alpha = static_cast<unsigned char>(255.0f * a * a);
                ImageDrawPixel(&sun, x, y, ::Color {255, 238, 210, alpha});
            }
        }
        sunGlowTex = LoadTextureFromImage(sun);
        UnloadImage(sun);
        if (sunGlowTex.id > 0) {
            SetTextureFilter(sunGlowTex, TEXTURE_FILTER_BILINEAR);
        }

        Image cloud = GenImageColor(n, n, BLANK);
        for (int y = 0; y < n; ++y) {
            for (int x = 0; x < n; ++x) {
                const float dx = (static_cast<float>(x) + 0.5f) / static_cast<float>(n) - 0.5f;
                const float dy = (static_cast<float>(y) + 0.5f) / static_cast<float>(n) - 0.5f;
                const float d = std::sqrt(dx * dx + dy * dy) / 0.42f;
                float a = std::max(0.0f, 1.0f - d * d);
                a = a * a;
                const unsigned char alpha = static_cast<unsigned char>(228.0f * a);
                ImageDrawPixel(&cloud, x, y, ::Color {245, 250, 255, alpha});
            }
        }
        cloudBlobTex = LoadTextureFromImage(cloud);
        UnloadImage(cloud);
        if (cloudBlobTex.id > 0) {
            SetTextureFilter(cloudBlobTex, TEXTURE_FILTER_BILINEAR);
        }

        hasSkyDecals = (sunGlowTex.id > 0 && cloudBlobTex.id > 0);
        if (!hasSkyDecals) {
            std::cout << "Sky decal textures failed to load; using 2D sun disk only.\n";
        }
    }

    void loadSunGlb() {
        // Authoritative sun: basics_3D/Gold Mine/sun (sun.glb). Do not use weather/sun.
        const char* paths[] = {
            R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\basics_3D\Gold Mine\sun.glb)",
            R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\basics_3D\Gold Mine\sun)",
        };
        const char* used = nullptr;
        for (const char* path : paths) {
            if (!FileExists(path)) continue;
            sunGlb = LoadModel(path);
            if (sunGlb.meshCount > 0) {
                used = path;
                break;
            }
            UnloadModel(sunGlb);
            sunGlb = {};
        }
        if (used == nullptr) {
            std::cout << "Gold Mine/sun missing — procedural sun fallback.\n";
            return;
        }

        const BoundingBox bb = GetModelBoundingBox(sunGlb);
        const float dx = bb.max.x - bb.min.x;
        const float dy = bb.max.y - bb.min.y;
        const float dz = bb.max.z - bb.min.z;
        const float diam = std::max(0.01f, std::max(dx, std::max(dy, dz)));
        // Compact sunrise disc (~150 m) — fully framed, not sky-filling.
        sunGlbScale = 150.0f / diam;
        sunOriginX = 0.5f * (bb.min.x + bb.max.x);
        sunOriginY = 0.5f * (bb.min.y + bb.max.y);
        sunOriginZ = 0.5f * (bb.min.z + bb.max.z);

        // Prefer the first real albedo (Gold Mine packs texture on material 1, not 0).
        Texture2D bestAlbedo {};
        for (int i = 0; i < sunGlb.materialCount; ++i) {
            Texture2D& t = sunGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].texture;
            if (t.id > 1 && t.width > 1 && t.height > 1) {
                bestAlbedo = t;
                break;
            }
        }
        for (int i = 0; i < sunGlb.materialCount; ++i) {
            sunGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].color = WHITE;
            if (bestAlbedo.id > 1) {
                sunGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].texture = bestAlbedo;
            }
            Texture2D& t = sunGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].texture;
            if (t.id > 1) {
                GenTextureMipmaps(&t);
                SetTextureFilter(t, TEXTURE_FILTER_BILINEAR);
            }
        }
        hasSunGlb = true;
        std::cout << "Sun ready from " << used
                  << " (scale " << sunGlbScale << ", diam " << diam << ").\n";
    }

