    void loadCloudGlb() {
        const char* path =
            R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\basics_3D\Gold Mine\cloud.glb)";
        if (!FileExists(path)) {
            std::cout << "Gold Mine cloud.glb missing — blob-cloud fallback.\n";
            return;
        }
        cloudGlb = LoadModel(path);
        if (cloudGlb.meshCount <= 0 || cloudGlb.meshes[0].vertexCount <= 0) {
            UnloadModel(cloudGlb);
            cloudGlb = {};
            std::cout << "Gold Mine cloud.glb failed to load.\n";
            return;
        }
        const BoundingBox bb = GetModelBoundingBox(cloudGlb);
        const float dx = bb.max.x - bb.min.x;
        const float dy = bb.max.y - bb.min.y;
        const float dz = bb.max.z - bb.min.z;
        const float span = std::max(0.01f, std::max(dx, dz));
        // Gold Mine cloud.glb is a ~1 m pancake mesh — bank it at ~160 m across.
        cloudGlbScale = 160.0f / span;
        cloudOriginX = 0.5f * (bb.min.x + bb.max.x);
        cloudOriginY = 0.5f * (bb.min.y + bb.max.y);
        cloudOriginZ = 0.5f * (bb.min.z + bb.max.z);

        const char* vs =
            "#version 330\n"
            "in vec3 vertexPosition;\n"
            "in vec2 vertexTexCoord;\n"
            "in vec4 vertexColor;\n"
            "out vec2 fragTexCoord;\n"
            "out vec4 fragColor;\n"
            "uniform mat4 mvp;\n"
            "void main(){\n"
            "  fragTexCoord = vertexTexCoord;\n"
            "  fragColor = vertexColor;\n"
            "  gl_Position = mvp * vec4(vertexPosition, 1.0);\n"
            "}\n";
        const char* fs =
            "#version 330\n"
            "in vec2 fragTexCoord;\n"
            "in vec4 fragColor;\n"
            "out vec4 finalColor;\n"
            "uniform sampler2D texture0;\n"
            "uniform vec4 colDiffuse;\n"
            "void main(){\n"
            "  vec4 texel = texture(texture0, fragTexCoord);\n"
            "  vec4 c = texel * colDiffuse * fragColor;\n"
            "  finalColor = vec4(c.rgb, 1.0);\n"
            "}\n";
        cloudUnlit = LoadShaderFromMemory(vs, fs);
        cloudUnlitOwned = (cloudUnlit.id != 0);

        Texture2D bestAlbedo {};
        for (int i = 0; i < cloudGlb.materialCount; ++i) {
            Texture2D& t = cloudGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].texture;
            if (t.id > 1 && t.width > 1 && t.height > 1) {
                bestAlbedo = t;
                break;
            }
        }
        for (int i = 0; i < cloudGlb.materialCount; ++i) {
            if (cloudUnlitOwned) cloudGlb.materials[i].shader = cloudUnlit;
            cloudGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].color = WHITE;
            if (bestAlbedo.id > 1) {
                cloudGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].texture = bestAlbedo;
            }
            Texture2D& t = cloudGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].texture;
            if (t.id > 1) {
                GenTextureMipmaps(&t);
                SetTextureFilter(t, TEXTURE_FILTER_TRILINEAR);
            }
        }
        if (cloudGlb.meshCount > 0 && cloudGlb.meshMaterial != nullptr && bestAlbedo.id > 1) {
            int bestMat = 0;
            for (int i = 0; i < cloudGlb.materialCount; ++i) {
                Texture2D& t = cloudGlb.materials[i].maps[MATERIAL_MAP_ALBEDO].texture;
                if (t.id == bestAlbedo.id) { bestMat = i; break; }
            }
            for (int mi = 0; mi < cloudGlb.meshCount; ++mi) {
                cloudGlb.meshMaterial[mi] = bestMat;
            }
        }
        hasCloudGlb = true;
        std::cout << "Clouds ready from cloud.glb (span " << span
                  << " m local, " << (span * cloudGlbScale) << " m in sky).\n";
    }

    void loadCloudSprite() {
        const char* path =
            R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\basics_3D\Gold Mine\ParticleCloudWhite.png)";
        if (!FileExists(path)) {
            std::cout << "ParticleCloudWhite.png missing — mesh/blob cloud fallback.\n";
            return;
        }
        Image img = LoadImage(path);
        if (img.data == nullptr || img.width <= 0) {
            std::cout << "ParticleCloudWhite.png failed to load.\n";
            return;
        }
        ImageFormat(&img, PIXELFORMAT_UNCOMPRESSED_R8G8B8A8);
        auto* px = static_cast<unsigned char*>(img.data);
        const int n = img.width * img.height;
        for (int i = 0; i < n; ++i) {
            unsigned char* p = px + i * 4;
            // Black plate is transparency; keep the grey shading in RGB.
            const int lum = (static_cast<int>(p[0]) * 2 + static_cast<int>(p[1]) * 3
                             + static_cast<int>(p[2])) / 6;
            p[3] = static_cast<unsigned char>(lum);
        }
        cloudSpriteTex = LoadTextureFromImage(img);
        UnloadImage(img);
        if (cloudSpriteTex.id <= 0) {
            std::cout << "ParticleCloudWhite.png texture upload failed.\n";
            return;
        }
        GenTextureMipmaps(&cloudSpriteTex);
        SetTextureFilter(cloudSpriteTex, TEXTURE_FILTER_BILINEAR);
        SetTextureWrap(cloudSpriteTex, TEXTURE_WRAP_CLAMP);
        hasCloudSprite = true;
        std::cout << "Sky clouds using ParticleCloudWhite.png ("
                  << cloudSpriteTex.width << "x" << cloudSpriteTex.height << ").\n";
    }

