/** foliage.ts crossed leaf card — two alpha quads (kept for close detail). */
static void drawGoldMineLeafCard(const Vector3& c, float size, float yaw, float tilt,
                                 const Texture2D& tex, ::Color tint) {
    if (tex.id <= 0) return;
    const float hy = size * 0.55f;
    rlSetTexture(tex.id);
    rlBegin(RL_QUADS);
    rlColor4ub(tint.r, tint.g, tint.b, tint.a);
    for (int q = 0; q < 2; ++q) {
        const float a = yaw + q * kPi * 0.5f;
        const float ux = std::cos(a), uz = std::sin(a);
        const float corners[4][4] = {
            {-1.0f, -1.0f, 0.0f, 0.0f},
            { 1.0f, -1.0f, 1.0f, 0.0f},
            { 1.0f,  1.0f, 1.0f, 1.0f},
            {-1.0f,  1.0f, 0.0f, 1.0f},
        };
        rlNormal3f(ux * 0.55f, 0.72f, uz * 0.55f);
        for (int i = 0; i < 4; ++i) {
            const float sx0 = corners[i][0], sy0 = corners[i][1];
            rlTexCoord2f(corners[i][2], corners[i][3]);
            rlVertex3f(
                c.x + ux * size * 0.5f * sx0 + ux * tilt * hy * sy0,
                c.y + hy * sy0,
                c.z + uz * size * 0.5f * sx0 + uz * tilt * hy * sy0);
        }
    }
    rlEnd();
    rlSetTexture(0);
}

static ::Color gltfBaseColorFactor(const cgltf_material* mat) {
    if (mat == nullptr || !mat->has_pbr_metallic_roughness) return WHITE;
    const cgltf_float* f = mat->pbr_metallic_roughness.base_color_factor;
    auto u8 = [](cgltf_float x) -> unsigned char {
        const float v = std::max(0.0f, std::min(1.0f, static_cast<float>(x))) * 255.0f;
        return static_cast<unsigned char>(v + 0.5f);
    };
    return {u8(f[0]), u8(f[1]), u8(f[2]), u8(f[3])};
}

// ============================================================
// Large GLB loader — raylib truncates u32 indices to u16 which
// shatters any mesh with >65535 verts (tree.glb = 70k). We expand
// to a non-indexed mesh so geometry stays intact.
// ============================================================
static Model loadLargeGlbUnindexed(const char* path) {
    Model model {};
    cgltf_options options {};
    cgltf_data* data = nullptr;
    cgltf_result res = cgltf_parse_file(&options, path, &data);
    if (res != cgltf_result_success || data == nullptr) {
        std::cout << "cgltf parse failed for " << path << '\n';
        return model;
    }
    res = cgltf_load_buffers(&options, data, path);
    if (res != cgltf_result_success) {
        std::cout << "cgltf buffers failed for " << path << '\n';
        cgltf_free(data);
        return model;
    }

    // Find first mesh primitive with positions
    cgltf_primitive* prim = nullptr;
    cgltf_mesh* srcMesh = nullptr;
    for (cgltf_size mi = 0; mi < data->meshes_count && prim == nullptr; ++mi) {
        for (cgltf_size pi = 0; pi < data->meshes[mi].primitives_count; ++pi) {
            if (data->meshes[mi].primitives[pi].type == cgltf_primitive_type_triangles) {
                srcMesh = &data->meshes[mi];
                prim = &data->meshes[mi].primitives[pi];
                break;
            }
        }
    }
    if (prim == nullptr) {
        std::cout << "No triangle primitive in " << path << '\n';
        cgltf_free(data);
        return model;
    }

    cgltf_accessor* accPos = nullptr;
    cgltf_accessor* accNrm = nullptr;
    cgltf_accessor* accUv = nullptr;
    for (cgltf_size a = 0; a < prim->attributes_count; ++a) {
        cgltf_attribute& attr = prim->attributes[a];
        if (attr.type == cgltf_attribute_type_position) accPos = attr.data;
        else if (attr.type == cgltf_attribute_type_normal) accNrm = attr.data;
        else if (attr.type == cgltf_attribute_type_texcoord && attr.index == 0) accUv = attr.data;
    }
    if (accPos == nullptr) {
        std::cout << "No POSITION in " << path << '\n';
        cgltf_free(data);
        return model;
    }

    cgltf_accessor* accIdx = prim->indices;
    const cgltf_size cornerCount = (accIdx != nullptr) ? accIdx->count : accPos->count;
    if (cornerCount < 3) {
        cgltf_free(data);
        return model;
    }

    Mesh mesh {};
    mesh.triangleCount = static_cast<int>(cornerCount / 3);
    mesh.vertexCount = static_cast<int>(cornerCount); // non-indexed expansion
    mesh.vertices = static_cast<float*>(MemAlloc(mesh.vertexCount * 3 * static_cast<int>(sizeof(float))));
    mesh.normals = static_cast<float*>(MemAlloc(mesh.vertexCount * 3 * static_cast<int>(sizeof(float))));
    mesh.texcoords = static_cast<float*>(MemAlloc(mesh.vertexCount * 2 * static_cast<int>(sizeof(float))));
    mesh.indices = nullptr;

    auto readIndex = [&](cgltf_size i) -> cgltf_size {
        if (accIdx == nullptr) return i;
        cgltf_uint idx = 0;
        cgltf_accessor_read_uint(accIdx, i, &idx, 1);
        return static_cast<cgltf_size>(idx);
    };

    for (cgltf_size c = 0; c < cornerCount; ++c) {
        const cgltf_size vi = readIndex(c);
        float p[3] = {0, 0, 0};
        float n[3] = {0, 1, 0};
        float uv[2] = {0, 0};
        cgltf_accessor_read_float(accPos, vi, p, 3);
        if (accNrm) cgltf_accessor_read_float(accNrm, vi, n, 3);
        if (accUv) cgltf_accessor_read_float(accUv, vi, uv, 2);
        mesh.vertices[c * 3 + 0] = p[0];
        mesh.vertices[c * 3 + 1] = p[1];
        mesh.vertices[c * 3 + 2] = p[2];
        mesh.normals[c * 3 + 0] = n[0];
        mesh.normals[c * 3 + 1] = n[1];
        mesh.normals[c * 3 + 2] = n[2];
        mesh.texcoords[c * 2 + 0] = uv[0];
        mesh.texcoords[c * 2 + 1] = uv[1];
    }

    UploadMesh(&mesh, false);

    model = LoadModelFromMesh(mesh); // takes ownership of mesh GPU data
    cgltf_material* mat = prim->material;
    const ::Color baseFac = gltfBaseColorFactor(mat);
    for (int i = 0; i < model.materialCount; ++i) {
        model.materials[i].maps[MATERIAL_MAP_ALBEDO].color = WHITE;
    }

    // Load baseColor texture from glTF material if present
    Texture2D albedo {};
    if (mat != nullptr && mat->has_pbr_metallic_roughness) {
        cgltf_texture* tex = mat->pbr_metallic_roughness.base_color_texture.texture;
        if (tex != nullptr && tex->image != nullptr) {
            cgltf_image* img = tex->image;
            const unsigned char* bytes = nullptr;
            cgltf_size nbytes = 0;
            if (img->buffer_view != nullptr) {
                const cgltf_buffer_view* bv = img->buffer_view;
                bytes = static_cast<const unsigned char*>(bv->buffer->data) + bv->offset;
                nbytes = bv->size;
            }
            if (bytes != nullptr && nbytes > 0) {
                const char* ext = ".png";
                if (img->mime_type && std::strstr(img->mime_type, "jpeg")) ext = ".jpg";
                Image image = LoadImageFromMemory(ext, bytes, static_cast<int>(nbytes));
                if (image.data != nullptr) {
                    if (baseFac.r != 255 || baseFac.g != 255 || baseFac.b != 255) {
                        ImageColorTint(&image, baseFac);
                    }
                    albedo = LoadTextureFromImage(image);
                    UnloadImage(image);
                }
            }
        }
    }
    if (albedo.id > 0) {
        GenTextureMipmaps(&albedo);
        SetTextureFilter(albedo, TEXTURE_FILTER_TRILINEAR);
        SetMaterialTexture(&model.materials[0], MATERIAL_MAP_ALBEDO, albedo);
        // Keep a note: UnloadModel will unload material textures that were set
    } else {
        for (int i = 0; i < model.materialCount; ++i) {
            model.materials[i].maps[MATERIAL_MAP_ALBEDO].color = baseFac;
        }
    }

    std::cout << "Loaded large GLB unindexed: " << mesh.vertexCount << " verts / "
              << mesh.triangleCount << " tris from " << path << '\n';
    cgltf_free(data);
    return model;
}

/**
 * Whole-scene GLB loader — cactus.glb is a multi-primitive scene whose parts
 * carry node transforms. The single-primitive loader above grabbed only the
 * first primitive and ignored transforms, which drew it as a flat dark slab.
 * Builds one unindexed Raylib mesh per triangle primitive with its world
 * transform baked in and its own baseColor texture (copied per material so
 * UnloadModel never double-frees a shared texture).
 */
static Model loadGlbUnindexedScene(const char* path) {
    Model model {};
    cgltf_options options {};
    cgltf_data* data = nullptr;
    if (cgltf_parse_file(&options, path, &data) != cgltf_result_success || data == nullptr) {
        std::cout << "cgltf parse failed for " << path << '\n';
        return model;
    }
    if (cgltf_load_buffers(&options, data, path) != cgltf_result_success) {
        std::cout << "cgltf buffers failed for " << path << '\n';
        cgltf_free(data);
        return model;
    }

    struct Piece {
        cgltf_primitive* prim {nullptr};
        float world[16] {};
    };
    std::vector<Piece> pieces;
    for (cgltf_size ni = 0; ni < data->nodes_count; ++ni) {
        cgltf_node* node = &data->nodes[ni];
        if (node->mesh == nullptr) continue;
        Piece base {};
        cgltf_node_transform_world(node, base.world);
        for (cgltf_size pi = 0; pi < node->mesh->primitives_count; ++pi) {
            if (node->mesh->primitives[pi].type != cgltf_primitive_type_triangles) continue;
            Piece p = base;
            p.prim = &node->mesh->primitives[pi];
            pieces.push_back(p);
        }
    }
    if (pieces.empty()) {
        std::cout << "No triangle primitives in scene " << path << '\n';
        cgltf_free(data);
        return model;
    }

    model.transform = MatrixIdentity();
    model.meshCount = static_cast<int>(pieces.size());
    model.materialCount = model.meshCount;
    model.meshes = static_cast<Mesh*>(MemAlloc(model.meshCount * static_cast<int>(sizeof(Mesh))));
    model.materials = static_cast<Material*>(MemAlloc(model.materialCount * static_cast<int>(sizeof(Material))));
    model.meshMaterial = static_cast<int*>(MemAlloc(model.meshCount * static_cast<int>(sizeof(int))));
    if (model.meshes == nullptr || model.materials == nullptr || model.meshMaterial == nullptr) {
        cgltf_free(data);
        return Model {};
    }

    int totalVerts = 0;
    for (int k = 0; k < model.meshCount; ++k) {
        const Piece& piece = pieces[static_cast<size_t>(k)];
        cgltf_primitive* prim = piece.prim;
        const float* m = piece.world;

        cgltf_accessor* accPos = nullptr;
        cgltf_accessor* accNrm = nullptr;
        cgltf_accessor* accUv = nullptr;
        for (cgltf_size a = 0; a < prim->attributes_count; ++a) {
            cgltf_attribute& attr = prim->attributes[a];
            if (attr.type == cgltf_attribute_type_position) accPos = attr.data;
            else if (attr.type == cgltf_attribute_type_normal) accNrm = attr.data;
            else if (attr.type == cgltf_attribute_type_texcoord && attr.index == 0) accUv = attr.data;
        }
        cgltf_accessor* accIdx = prim->indices;
        const cgltf_size cornerCount =
            (accPos == nullptr) ? 0 : ((accIdx != nullptr) ? accIdx->count : accPos->count);

        Mesh mesh {};
        mesh.triangleCount = static_cast<int>(cornerCount / 3);
        mesh.vertexCount = static_cast<int>(cornerCount);
        if (mesh.vertexCount >= 3) {
            mesh.vertices = static_cast<float*>(MemAlloc(mesh.vertexCount * 3 * static_cast<int>(sizeof(float))));
            mesh.normals = static_cast<float*>(MemAlloc(mesh.vertexCount * 3 * static_cast<int>(sizeof(float))));
            mesh.texcoords = static_cast<float*>(MemAlloc(mesh.vertexCount * 2 * static_cast<int>(sizeof(float))));
        }
        if (mesh.vertices != nullptr && mesh.normals != nullptr && mesh.texcoords != nullptr) {
            for (cgltf_size c = 0; c < cornerCount; ++c) {
                cgltf_size vi = c;
                if (accIdx != nullptr) {
                    cgltf_uint idx = 0;
                    cgltf_accessor_read_uint(accIdx, c, &idx, 1);
                    vi = static_cast<cgltf_size>(idx);
                }
                float p[3] = {0, 0, 0};
                float n[3] = {0, 1, 0};
                float uv[2] = {0, 0};
                cgltf_accessor_read_float(accPos, vi, p, 3);
                if (accNrm) cgltf_accessor_read_float(accNrm, vi, n, 3);
                if (accUv) cgltf_accessor_read_float(accUv, vi, uv, 2);
                // glTF matrices are column-major: world position + rotated normal.
                const float wx = m[0] * p[0] + m[4] * p[1] + m[8] * p[2] + m[12];
                const float wy = m[1] * p[0] + m[5] * p[1] + m[9] * p[2] + m[13];
                const float wz = m[2] * p[0] + m[6] * p[1] + m[10] * p[2] + m[14];
                float nx = m[0] * n[0] + m[4] * n[1] + m[8] * n[2];
                float ny = m[1] * n[0] + m[5] * n[1] + m[9] * n[2];
                float nz = m[2] * n[0] + m[6] * n[1] + m[10] * n[2];
                const float nl = std::sqrt(nx * nx + ny * ny + nz * nz);
                if (nl > 1.0e-6f) { nx /= nl; ny /= nl; nz /= nl; }
                mesh.vertices[c * 3 + 0] = wx;
                mesh.vertices[c * 3 + 1] = wy;
                mesh.vertices[c * 3 + 2] = wz;
                mesh.normals[c * 3 + 0] = nx;
                mesh.normals[c * 3 + 1] = ny;
                mesh.normals[c * 3 + 2] = nz;
                mesh.texcoords[c * 2 + 0] = uv[0];
                mesh.texcoords[c * 2 + 1] = uv[1];
            }
            UploadMesh(&mesh, false);
            totalVerts += mesh.vertexCount;
        }
        model.meshes[k] = mesh;

        model.materials[k] = LoadMaterialDefault();
        model.materials[k].maps[MATERIAL_MAP_ALBEDO].color = WHITE;
        model.meshMaterial[k] = k;

        cgltf_material* mat = prim->material;
        const ::Color baseFac = gltfBaseColorFactor(mat);
        if (mat != nullptr && mat->has_pbr_metallic_roughness) {
            cgltf_texture* tex = mat->pbr_metallic_roughness.base_color_texture.texture;
            if (tex != nullptr && tex->image != nullptr && tex->image->buffer_view != nullptr) {
                const cgltf_buffer_view* bv = tex->image->buffer_view;
                const unsigned char* bytes = static_cast<const unsigned char*>(bv->buffer->data) + bv->offset;
                const char* ext = ".png";
                if (tex->image->mime_type && std::strstr(tex->image->mime_type, "jpeg")) ext = ".jpg";
                Image image = LoadImageFromMemory(ext, bytes, static_cast<int>(bv->size));
                if (image.data != nullptr) {
                    if (baseFac.r != 255 || baseFac.g != 255 || baseFac.b != 255) {
                        ImageColorTint(&image, baseFac);
                    }
                    Texture2D albedo = LoadTextureFromImage(image);
                    UnloadImage(image);
                    if (albedo.id > 0) {
                        GenTextureMipmaps(&albedo);
                        SetTextureFilter(albedo, TEXTURE_FILTER_TRILINEAR);
                        SetMaterialTexture(&model.materials[k], MATERIAL_MAP_ALBEDO, albedo);
                    } else {
                        model.materials[k].maps[MATERIAL_MAP_ALBEDO].color = baseFac;
                    }
                } else {
                    model.materials[k].maps[MATERIAL_MAP_ALBEDO].color = baseFac;
                }
            } else {
                model.materials[k].maps[MATERIAL_MAP_ALBEDO].color = baseFac;
            }
        }
    }

    std::cout << "Loaded GLB scene unindexed: " << model.meshCount << " prims / "
              << totalVerts << " verts from " << path << '\n';
    cgltf_free(data);
    return model;
}

