static void drawCrystalForests(const Vec3& playerPos, EnhancedAfricanTerrain& terrainSystem) {
    const int half = 45;
    const float spacing = 3.8f;
    for (int gz = -half; gz <= half; ++gz) {
        for (int gx = -half; gx <= half; ++gx) {
            const int worldCellX = static_cast<int>(std::floor(playerPos.x / spacing)) + gx;
            const int worldCellZ = static_cast<int>(std::floor(playerPos.z / spacing)) + gz;
            const float n = hashNoise2D(worldCellX, worldCellZ);
            if (n < 0.975f) {
                continue;
            }

            const float x = static_cast<float>(worldCellX) * spacing;
            const float z = static_cast<float>(worldCellZ) * spacing;
            const float y = terrainSystem.getHeight(x, z);
            if (y < 0.8f) {
                continue;
            }

            const float treeH = 4.0f + n * 7.0f;
            const float trunkR = 0.12f + n * 0.06f;
            DrawCylinder(
                {x, y + treeH * 0.5f, z},
                trunkR,
                trunkR * 0.85f,
                treeH,
                8,
                ::Color {88, 68, 45, 255}
            );

            const float crownR = 1.5f + n * 1.7f;
            DrawSphere({x, y + treeH + crownR * 0.35f, z}, crownR, ::Color {68, 118, 62, 255});
            DrawSphere({x + 0.8f, y + treeH + crownR * 0.12f, z - 0.5f}, crownR * 0.72f, ::Color {72, 126, 66, 255});
            DrawSphere({x - 0.7f, y + treeH + crownR * 0.1f, z + 0.6f}, crownR * 0.66f, ::Color {64, 110, 58, 255});
        }
    }
}

static void drawAlienSkyBodies(const Vec3& playerPos) {
    const Vector3 p1 {playerPos.x + 250.0f, playerPos.y + 170.0f, playerPos.z + 320.0f};
    const Vector3 p2 {playerPos.x - 310.0f, playerPos.y + 210.0f, playerPos.z + 430.0f};
    const Vector3 p3 {playerPos.x + 60.0f, playerPos.y + 110.0f, playerPos.z + 260.0f};

    DrawSphere(p1, 54.0f, ::Color {232, 196, 255, 255});
    DrawSphere(p2, 38.0f, ::Color {160, 190, 255, 255});
    DrawSphere(p3, 20.0f, ::Color {255, 178, 148, 255});

    for (int i = 0; i < 40; ++i) {
        const float t = static_cast<float>(i) / 40.0f;
        const float a = t * 2.0f * kPi;
        const float rX = 85.0f;
        const float rZ = 28.0f;
        const Vector3 ringPos {p1.x + std::cos(a) * rX, p1.y + std::sin(a) * 4.0f, p1.z + std::sin(a) * rZ};
        DrawSphere(ringPos, 1.8f, ::Color {250, 232, 190, 255});
    }
}

/**
 * Starfield. Port of Gold Mine world.ts ParticleSpec kind:"star":
 *   genNight   — 1800 points, #dfe8ff, size 0.5, no drift
 *   genShadow  — 2200 points, #8ef0e0, size 0.6, hung between the two grounds
 *
 * Drawn in 2D after the sky wash and before the 3D pass, but projected from
 * fixed world directions so the field turns correctly with the camera and
 * still sits behind everything without fighting the depth buffer.
 */
enum class StarPalette { Night, Shadow, Space };

static void drawStarfield(const Camera3D& camera, float amount, float time,
                          StarPalette palette = StarPalette::Night) {
    if (amount <= 0.004f) return;
    const int kStars = (palette == StarPalette::Shadow) ? 2200
                     : (palette == StarPalette::Space)  ? 3200
                     : 1800;
    const float sizeMul = (palette == StarPalette::Shadow) ? 1.20f
                        : (palette == StarPalette::Space)  ? 1.35f
                        : 1.0f;
    constexpr float kShell = 4000.0f;   // inside the 8000 far plane

    Vector3 fwd {camera.target.x - camera.position.x,
                 camera.target.y - camera.position.y,
                 camera.target.z - camera.position.z};
    const float fl = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
    if (fl < 1.0e-4f) return;
    fwd = {fwd.x / fl, fwd.y / fl, fwd.z / fl};

    const int sw = GetScreenWidth();
    const int sh = GetScreenHeight();

    // Additive so they read as lights, and a night-grade boost because the
    // day-cycle shader multiplies the captured scene by ~0.52 after dark.
    // Space shots skip that crush, so they get a gentler boost.
    const float gradeBoost = (palette == StarPalette::Space)
        ? (1.15f + 0.55f * amount)
        : (0.90f + 0.95f * amount);
    BeginBlendMode(BLEND_ADDITIVE);
    for (int i = 0; i < kStars; ++i) {
        // Fixed lattice, not GetRandomValue — the sky has to be the same sky
        // every frame or the whole field boils.
        unsigned n = static_cast<unsigned>(i) * 2654435761u;
        n ^= n >> 15U;
        const float u = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 1274126177u; n ^= n >> 13U;
        const float v = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 2246822519u; n ^= n >> 11U;
        const float mag = static_cast<float>(n & 0xFFFFU) / 65535.0f;

        // Even distribution over the sphere. Night/Shadow bias to the upper
        // hemisphere (looking at the sky). Space uses the full sphere so the
        // artificial-sun shot is a starfield behind Earth, not a black void.
        const float phi = u * 2.0f * kPi;
        const float hemi = (palette == StarPalette::Space) ? 1.00f
                         : (palette == StarPalette::Shadow) ? 0.82f
                         : 0.62f;
        const float ct = 1.0f - 2.0f * v * hemi;
        const float st = std::sqrt(std::max(0.0f, 1.0f - ct * ct));
        const Vector3 dir {st * std::cos(phi), ct, st * std::sin(phi)};

        // Space keeps a wider forward cone — Earth fills the centre, stars
        // have to live in the rim.
        const float fwdMin = (palette == StarPalette::Space) ? -0.15f : 0.12f;
        if (dir.x * fwd.x + dir.y * fwd.y + dir.z * fwd.z <= fwdMin) continue;

        const Vector3 world {camera.position.x + dir.x * kShell,
                             camera.position.y + dir.y * kShell,
                             camera.position.z + dir.z * kShell};
        const Vector2 s = GetWorldToScreen(world, camera);
        if (s.x < -8.0f || s.y < -8.0f || s.x > sw + 8.0f || s.y > sh + 8.0f) continue;

        // Slow, per-star twinkle. Fast twinkle reads as dropped frames.
        // world.ts stars have rise: 0 — they do not drift, only pulse.
        const float tw = 0.78f + 0.22f * std::sin(time * (0.5f + mag * 1.1f) + mag * 31.0f);
        const float bright = (0.38f + 0.62f * mag * mag) * tw * amount * gradeBoost;
        const unsigned char a8 = static_cast<unsigned char>(std::min(255.0f, 255.0f * bright));
        if (a8 < 8) continue;

        ::Color c {223, 232, 255, a8};           // genNight #dfe8ff
        if (palette == StarPalette::Shadow) {
            c = {142, 240, 224, a8};             // genShadow #8ef0e0
            if (mag > 0.90f) c = {200, 255, 245, a8};
        } else if (palette == StarPalette::Space) {
            c = {235, 240, 255, a8};
            if (mag > 0.92f)      c = {255, 250, 240, a8};
            else if (mag < 0.12f) c = {180, 200, 255, a8};
        } else {
            if (mag > 0.93f)      c = {198, 216, 255, a8};
            else if (mag < 0.10f) c = {255, 222, 198, a8};
        }

        if (mag > 0.965f) {
            DrawCircleV(s, 1.8f * sizeMul, c);
            DrawCircleV(s, 3.6f * sizeMul, ::Color {c.r, c.g, c.b, static_cast<unsigned char>(a8 / 5)});
        } else if (mag > 0.55f) {
            DrawCircleV(s, 1.25f * sizeMul, c);
        } else {
            DrawCircleV(s, 0.95f * sizeMul, c);
        }
    }
    EndBlendMode();
}

/**
 * world.ts genShadow: 90 GLOW spheres hung between the two grounds —
 * "burning stars too close". Additive so they read as lamps, not rocks.
 */
static void drawBurningCloseStars(const Camera3D& camera, float amount, float time) {
    if (amount <= 0.04f) return;
    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    for (int k = 0; k < 90; ++k) {
        unsigned n = static_cast<unsigned>(k) * 2246822519u;
        n ^= n >> 13U;
        const float ux = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 2654435761u; n ^= n >> 15U;
        const float uz = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 1274126177u; n ^= n >> 13U;
        const float uy = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 374761393u; n ^= n >> 11U;
        const float ur = static_cast<float>(n & 0xFFFFU) / 65535.0f;

        const float x = camera.position.x + (ux - 0.5f) * 220.0f;
        const float z = camera.position.z + (uz - 0.5f) * 220.0f;
        const float y = camera.position.y + 10.0f + uy * 32.0f
                        + 0.35f * std::sin(time * 0.7f + ur * 12.0f);
        const float r = 1.05f + ur * 1.55f;
        const unsigned char aHalo = static_cast<unsigned char>(58.0f * amount);
        const unsigned char aCore = static_cast<unsigned char>(150.0f * amount);
        DrawSphereEx({x, y, z}, r, 7, 7, ::Color {142, 240, 224, aHalo});
        DrawSphereEx({x, y, z}, r * 0.32f, 5, 5, ::Color {230, 255, 248, aCore});
    }
    rlEnableDepthMask();
    EndBlendMode();
}

/**
 * world.ts genNight: 500 fireflies, #66ffd0, size 0.22, rise 0.15, drifting
 * a few metres above the grass. Freeplay night uses the same field.
 */
static void drawNightFireflies(const Camera3D& camera, const Vec3& focus,
                               float amount, float time) {
    if (amount <= 0.08f) return;
    constexpr int kCount = 220;   // 500 in the voxel scene; this is the readable set
    Vector3 fwd {camera.target.x - camera.position.x,
                 camera.target.y - camera.position.y,
                 camera.target.z - camera.position.z};
    const float fl = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
    if (fl < 1.0e-4f) return;
    fwd = {fwd.x / fl, fwd.y / fl, fwd.z / fl};

    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    for (int i = 0; i < kCount; ++i) {
        unsigned n = static_cast<unsigned>(i) * 2654435761u;
        n ^= n >> 15U;
        const float ux = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 1274126177u; n ^= n >> 13U;
        const float uz = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 2246822519u; n ^= n >> 11U;
        const float uy = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 374761393u; n ^= n >> 11U;
        const float ph = static_cast<float>(n & 0xFFFFU) / 65535.0f;

        const float x = focus.x + (ux - 0.5f) * 160.0f;
        const float z = focus.z + (uz - 0.5f) * 160.0f;
        const float y = focus.y + 1.4f + uy * 10.0f
                        + std::fmod(time * 0.15f + ph * 7.0f, 6.0f);
        const float dx = x - camera.position.x;
        const float dy = y - camera.position.y;
        const float dz = z - camera.position.z;
        if (dx * fwd.x + dy * fwd.y + dz * fwd.z < 1.0f) continue;

        const float tw = 0.40f + 0.60f * (0.5f + 0.5f * std::sin(time * 2.1f + ph * 40.0f));
        const unsigned char a8 = static_cast<unsigned char>(
            std::min(255.0f, 200.0f * tw * amount));
        DrawSphereEx({x, y, z}, 0.11f, 4, 4, ::Color {102, 255, 208, a8});
    }
    rlEnableDepthMask();
    EndBlendMode();
}

/**
 * The artificial sun, mid-construction: a burning core inside an unfinished
 * shell. `build` is how much of the shell exists, so the same object can read
 * as scaffolding or as nearly closed.
 *
 * Follows the existing sky-object grammar — additive billboard glow like the
 * real sun, segmented additive geometry like the devourer.
 */
static void drawArtificialSun(const Camera3D& camera, const Vector3& c, float radius,
                              float build, float time, const Texture2D& glowTex) {
    const float coreR = radius * 0.80f;

    // Core. Layered rather than one sphere so the limb falls off instead of
    // ending on a hard circle edge.
    DrawSphereEx(c, coreR, 24, 24, ::Color {255, 238, 196, 255});
    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    DrawSphereEx(c, coreR * 1.05f, 20, 20, ::Color {255, 186, 84, 90});
    DrawSphereEx(c, coreR * 1.14f, 16, 16, ::Color {255, 138, 42, 46});
    if (glowTex.id > 0) {
        DrawBillboard(camera, glowTex, c, radius * 4.6f, ::Color {255, 176, 72, 40});
        DrawBillboard(camera, glowTex, c, radius * 2.9f, ::Color {255, 214, 140, 54});
    }
    rlEnableDepthMask();
    EndBlendMode();

    // Unfinished shell. Latitude rings of panels, each ring only partly filled,
    // with the gaps biased toward the poles so it reads as being built outward
    // from the equator rather than randomly eaten away.
    constexpr int kRings = 9;
    constexpr int kPerRing = 26;
    const float shellR = radius * 1.16f;
    for (int r = 0; r < kRings; ++r) {
        const float lat = (static_cast<float>(r) / (kRings - 1) - 0.5f) * kPi * 0.94f;
        const float cl = std::cos(lat);
        const float sl = std::sin(lat);
        const float ringFill = build * (0.45f + 0.55f * cl);   // equator first
        for (int k = 0; k < kPerRing; ++k) {
            unsigned h = static_cast<unsigned>(r * 73856093 + k * 19349663);
            h ^= h >> 13U; h *= 1274126177u; h ^= h >> 16U;
            const float pick = static_cast<float>(h & 0xFFFFU) / 65535.0f;
            if (pick > ringFill) continue;

            const float a0 = (static_cast<float>(k) / kPerRing) * 2.0f * kPi;
            const float a1 = a0 + (2.0f * kPi / kPerRing) * 0.72f;
            const Vector3 p0 {c.x + std::cos(a0) * cl * shellR,
                              c.y + sl * shellR,
                              c.z + std::sin(a0) * cl * shellR};
            const Vector3 p1 {c.x + std::cos(a1) * cl * shellR,
                              c.y + sl * shellR,
                              c.z + std::sin(a1) * cl * shellR};
            const float beam = radius * 0.034f;
            DrawCylinderEx(p0, p1, beam, beam, 5, ::Color {58, 62, 72, 255});
        }
    }

    // Two working rings still being laid, turning slowly — the only motion in
    // the shot, and what separates "being built" from "derelict".
    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    for (int s = 0; s < 2; ++s) {
        const float spin = time * (0.05f + 0.03f * s) + s * 1.7f;
        const float tilt = (s == 0) ? 0.22f : -0.34f;
        const float rr = radius * (1.30f + 0.16f * s);
        constexpr int kSeg = 64;
        for (int k = 0; k < kSeg; ++k) {
            const float a0 = spin + (static_cast<float>(k) / kSeg) * 2.0f * kPi;
            const float a1 = spin + (static_cast<float>(k + 1) / kSeg) * 2.0f * kPi;
            const Vector3 q0 {c.x + std::cos(a0) * rr,
                              c.y + std::sin(a0) * rr * tilt,
                              c.z + std::sin(a0) * rr};
            const Vector3 q1 {c.x + std::cos(a1) * rr,
                              c.y + std::sin(a1) * rr * tilt,
                              c.z + std::sin(a1) * rr};
            DrawCylinderEx(q0, q1, radius * 0.012f, radius * 0.012f, 4,
                           ::Color {120, 196, 255, 130});
        }
    }
    rlEnableDepthMask();
    EndBlendMode();
}

static void drawShallowWater(const Vec3& focus, EnhancedAfricanTerrain& terrainSystem,
                             GanfaulWater* ganfaul, const Vector3& camPos) {
    constexpr float tile = 3.0f;
    constexpr int halfSpan = 40;  // 120 m of water surface around the camera
    const bool useGanfaul = ganfaul != nullptr && ganfaul->hasLook();

    // Terrain is static — rescan for wet tiles only when the focus moves.
    struct WaterTile { float x; float z; float level; ::Color col; };
    static std::vector<WaterTile> tiles;
    static float lastX = 1.0e30f, lastZ = 1.0e30f;
    if (std::fabs(focus.x - lastX) + std::fabs(focus.z - lastZ) > 9.0f) {
        lastX = focus.x;
        lastZ = focus.z;
        tiles.clear();
        const int centerX = static_cast<int>(std::floor(focus.x / tile));
        const int centerZ = static_cast<int>(std::floor(focus.z / tile));
        for (int dz = -halfSpan; dz < halfSpan; ++dz) {
            for (int dx = -halfSpan; dx < halfSpan; ++dx) {
                const float x0 = static_cast<float>(centerX + dx) * tile;
                const float z0 = static_cast<float>(centerZ + dz) * tile;
                const float waterLevel = 1.0f + std::sin((x0 + z0) * 0.02f) * 0.2f;
                if (terrainSystem.getHeight(x0, z0) > waterLevel) continue;
                ::Color col {64, 164, 223, 195};
                if (!useGanfaul) {
                    // blocks.ts T.WATER — pack.water #40a4df with fbm ripple:
                    // 0.85 + (fbm*0.6 + fbm*0.4) * 0.35, evaluated per tile.
                    const float rip = goldMineFbm(x0 * 0.35f, z0 * 0.35f, 3, 100) * 0.6f
                                    + goldMineFbm(x0 * 1.05f, z0 * 1.05f, 2, 4) * 0.4f;
                    const float m = 0.85f + rip * 0.35f;
                    const auto ch = [&](float base) {
                        return static_cast<unsigned char>(std::min(255.0f, base * m));
                    };
                    col = ::Color {ch(64), ch(164), ch(223), 195};
                }
                tiles.push_back({x0, z0, waterLevel, col});
            }
        }
    }
    if (tiles.empty()) return;

    if (useGanfaul) {
        rlDrawRenderBatchActive();
        BeginBlendMode(BLEND_ALPHA);
        rlDisableBackfaceCulling();
        ganfaul->begin(camPos);
        rlBegin(RL_QUADS);
        for (const WaterTile& w : tiles) {
            rlNormal3f(0.0f, 1.0f, 0.0f);
            rlVertex3f(w.x,        w.level, w.z);
            rlVertex3f(w.x + tile, w.level, w.z);
            rlVertex3f(w.x + tile, w.level, w.z + tile);
            rlVertex3f(w.x,        w.level, w.z + tile);
        }
        rlEnd();
        ganfaul->end();
        rlEnableBackfaceCulling();
        EndBlendMode();
        return;
    }

    for (const WaterTile& w : tiles) {
        const Vector3 v00 {w.x, w.level, w.z};
        const Vector3 v10 {w.x + tile, w.level, w.z};
        const Vector3 v01 {w.x, w.level, w.z + tile};
        const Vector3 v11 {w.x + tile, w.level, w.z + tile};
        DrawTriangle3D(v00, v10, v11, w.col);
        DrawTriangle3D(v00, v11, v01, w.col);
        DrawTriangle3D(v11, v10, v00, w.col);
        DrawTriangle3D(v01, v11, v00, w.col);
    }
}

// Defined with the Nubian desert below; declared here so the terrain LOD can
// tint its own tiles sand inside the biome instead of leaving green underneath
// whatever the sand carpet fails to cover.
static float desertEdgeAt(float fieldX, float fieldZ, float x, float z);

// Distant grass under the dawn haze. The sub-horizon sky band, the
// ClearBackground, and the far-tile fog all converge on ONE colour, so the
// seam where terrain runs out (~2.4 km) and any cracks between LOD rings
// show "more grass" instead of a bare tan band with pale slivers in it.
static constexpr ::Color kDawnHorizonHaze {116, 129, 82, 255};
// Beyond this camera distance dawn tiles are drawn UNTEXTURED. A textured
// quad can never render brighter than tint*texel, GRASS_TOP averages
// (41,61,28) — nearly black — and past ~200 m the mip chain converges every
// pixel onto that average, so the whole midfield went uniformly dark no
// matter what the fog aimed at. Flat quads have no such ceiling and converge
// exactly on the haze. The cut tucks in just under where the grass carpets
// (tufts + ground.glb underlay) finish fading, so the texture is never
// missed: everything nearer is covered by real geometry.
static constexpr float kDawnFlatCut = 220.0f;
// Same trick for the Nubian shot: GRASS_TOP mips to a dark green, so a
// textured far tile can never look like sand no matter how hard you fog it.
// Untextured sand past this cut converges on the desert haze / sky bottom.
static constexpr ::Color kDesertHorizonHaze {216, 198, 160, 255};
static constexpr float kDesertFlatCut = 240.0f;

static void drawTerrainLOD(
    const Vec3& playerPos,
    EnhancedAfricanTerrain& terrainSystem,
    const Camera3D& camera,
    float tileSize,
    int halfSpan,
    float minDist,
    float maxDist,
    const WeatherVisualParams& weather,
    float clarityMult,
    const Texture2D& grassTex,
    bool dawnSavanna = false,
    // Desert-aware terrain. Tiles fully inside the Nubian lobes are deferred to
    // a second pass drawn with the sand tile, so the heightfield under the
    // carpet is already sand. A carpet quad that goes missing then reads as
    // slightly flatter sand instead of a green hole.
    const Texture2D* desertTex = nullptr,
    float desertFieldX = 0.0f,
    float desertFieldZ = 0.0f,
    bool forceSand = false,
    float yBias = 0.0f,
    bool sandUnderlay = false
) {
    const int centerX = static_cast<int>(std::floor(playerPos.x / tileSize));
    const int centerZ = static_cast<int>(std::floor(playerPos.z / tileSize));
    // Gold Mine triplanar.ts: texScale = 0.16 → ~6.25 m per grass tile.
    // Freeplay slightly denser so 512px grass doesn't read as big soft pixels.
    const float kTexScale = dawnSavanna ? 0.28f : 0.20f;
    constexpr ::Color kGrass {88, 130, 62, 255};
    constexpr ::Color kDry   {148, 138, 86, 255};
    constexpr ::Color kDawnGrass {78, 125, 52, 255};

    const bool textured = grassTex.id > 0 && !sandUnderlay;
    const bool desertAware = !sandUnderlay && textured && desertTex != nullptr && desertTex->id > 0;
    const float underlayY = sandUnderlay
        ? (terrainSystem.getHeight(playerPos.x, playerPos.z) + yBias)
        : 0.0f;

    // Dawn fog set-up, once per call (not per tile). Textured tiles all sit
    // inside kDawnFlatCut where fog is zero; only the flat far tiles fog, and
    // they converge on the haze the backdrop is painted with.
    WeatherVisualParams dawnFog = weather;
    if (dawnSavanna) {
        dawnFog.fogStart = kDawnFlatCut;
        dawnFog.fogEnd = 1500.0f;
        dawnFog.fogAmountScale = 1.4f;   // saturate the exp curve at the far edge
        dawnFog.fogColor = kDawnHorizonHaze;
        } else if (forceSand) {
            // Keep the near desert solid. Weather fog is rain/dust in the
            // air, not a wall that eats the pyramids at 280 m.
            dawnFog.fogStart = std::max(weather.fogStart, 640.0f);
            dawnFog.fogEnd = std::max(weather.fogEnd, 1800.0f);
            dawnFog.fogAmountScale = 1.15f;
            dawnFog.fogColor = kDesertHorizonHaze;
    }

    struct LodSandTile {
        float x0, z0, x1, z1;
        float h00, h10, h11, h01;
        ::Color tint;
    };
    thread_local std::vector<LodSandTile> sandTiles;
    sandTiles.clear();
    // Dawn-only: far tiles re-routed out of the textured batch (see kDawnFlatCut).
    thread_local std::vector<LodSandTile> flatTiles;
    flatTiles.clear();

    if (textured) {
        rlSetTexture(grassTex.id);
        rlBegin(RL_QUADS);
    }

    const float min2 = minDist * minDist;
    const float max2 = maxDist * maxDist;

    // Sample each grid corner once (was 4× getHeight per tile — CPU killer).
    const int gridN = halfSpan * 2 + 1;
    thread_local std::vector<float> heightGrid;
    heightGrid.resize(static_cast<std::size_t>(gridN) * static_cast<std::size_t>(gridN));
    for (int gz = 0; gz < gridN; ++gz) {
        for (int gx = 0; gx < gridN; ++gx) {
            const float wx = static_cast<float>(centerX - halfSpan + gx) * tileSize;
            const float wz = static_cast<float>(centerZ - halfSpan + gz) * tileSize;
            heightGrid[static_cast<std::size_t>(gz) * static_cast<std::size_t>(gridN)
                       + static_cast<std::size_t>(gx)] = terrainSystem.getHeight(wx, wz);
        }
    }

    auto heightAt = [&](int lx, int lz) -> float {
        return heightGrid[static_cast<std::size_t>(lz) * static_cast<std::size_t>(gridN)
                          + static_cast<std::size_t>(lx)];
    };

    for (int dz = 0; dz < halfSpan * 2; ++dz) {
        for (int dx = 0; dx < halfSpan * 2; ++dx) {
            const float x0 = static_cast<float>(centerX - halfSpan + dx) * tileSize;
            const float z0 = static_cast<float>(centerZ - halfSpan + dz) * tileSize;
            const float x1 = x0 + tileSize;
            const float z1 = z0 + tileSize;
            const float mx = (x0 + x1) * 0.5f;
            const float mz = (z0 + z1) * 0.5f;
            const float ddx = mx - playerPos.x;
            const float ddz = mz - playerPos.z;
            const float d2 = ddx * ddx + ddz * ddz;
            if (d2 < min2 || d2 >= max2) continue;

            const float h00 = heightAt(dx, dz);
            const float h10 = heightAt(dx + 1, dz);
            const float h01 = heightAt(dx, dz + 1);
            const float h11 = heightAt(dx + 1, dz + 1);

            const Vec3 n0 = estimateTileNormal(h00, h10, h01);
            const Vec3 sunDir = Vec3(0.55f, 0.9f, 0.35f).normalized();
            const float light0 = 0.42f + std::max(0.0f, n0.dot(sunDir)) * 0.58f;
            const float hAvg = (h00 + h10 + h11 + h01) * 0.25f;
            const float slopeBias = (std::fabs(h10 - h00) + std::fabs(h01 - h00)) / tileSize * 0.04f;
            const float shadedLight = std::max(0.35f, light0 - std::min(0.25f, slopeBias));

            const float macro = goldMineFbm(mx * 0.045f, mz * 0.045f, 2, 19);
            const float macroL = goldMineFbm(mx * 0.0135f, mz * 0.0135f, 2, 41);
            float lum = 0.90f + 0.20f * macro;
            const float dry = std::max(0.0f, std::min(1.0f, (macroL - 0.42f) / 0.36f));
            const float flatness = std::max(0.0f, std::min(1.0f, (n0.y - 0.35f) / 0.57f));

            ::Color tint {};
            if (dawnSavanna && textured) {
                // Push hard toward grass green so brown albedo cannot read as bare dirt.
                tint = shadeColor(::Color {110, 175, 55, 255}, shadedLight * (0.92f + 0.10f * macro));
                tint.r = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.r * (0.85f + dry * 0.05f))));
                tint.g = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.g * (1.05f + dry * 0.02f))));
                tint.b = static_cast<unsigned char>(std::max(0, static_cast<int>(tint.b * (0.45f - dry * 0.08f))));
            } else if (dawnSavanna) {
                tint = shadeColor(::Color {105, 170, 52, 255}, shadedLight * (0.95f + 0.12f * macro));
            } else if (textured) {
                // Valheim meadow: muted olive carpet, cool midtones — not bright savanna.
                tint = shadeColor(::Color {214, 220, 198, 255}, shadedLight * lum * 0.94f);
                tint.r = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.r * (0.94f + dry * 0.06f + flatness * 0.03f))));
                tint.g = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.g * (0.98f + dry * 0.02f))));
                tint.b = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.b * (1.04f - dry * 0.08f))));
            } else {
                tint = shadeColor(mixColor(::Color {78, 108, 62, 255}, kDry, dry * 0.45f), shadedLight * lum);
            }
            if (clarityMult > 0.7f) {
                const float boost = 1.0f + 0.06f * (clarityMult - 0.7f) / 0.3f;
                tint.r = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.r * boost)));
                tint.g = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.g * boost)));
                tint.b = static_cast<unsigned char>(std::min(255, static_cast<int>(tint.b * boost)));
            }

            const Vector3 quadCenter {mx, hAvg, mz};
            const WeatherVisualParams& fogW = (dawnSavanna || forceSand) ? dawnFog : weather;

            // Dawn far field: flat quads whose colour is free to converge on
            // the haze. Seeded with a plain grass green that continues the
            // carpet look — NOT tint*textureAverage, which is nearly black
            // and painted a black band where nothing covered it. The cut is
            // by CAMERA distance: the rings are centred on the camera TARGET,
            // which in trailer shots sits hundreds of metres ahead.
            const float camDx = mx - camera.position.x;
            const float camDz = mz - camera.position.z;
            const float camD2 = camDx * camDx + camDz * camDz;
            if (dawnSavanna && textured && camD2 > kDawnFlatCut * kDawnFlatCut) {
                ::Color flat = shadeColor(::Color {56, 86, 22, 255},
                                          shadedLight * (0.92f + 0.10f * macro));
                flat = applyDistanceFog(flat, quadCenter, camera,
                    fogW.fogStart, fogW.fogEnd, fogW.fogAmountScale, fogW.fogColor);
                flatTiles.push_back(LodSandTile {x0, z0, x1, z1,
                                                 h00, h10, h11, h01, flat});
                continue;
            }

            // Sand: inside the Nubian lobes, OR the whole frame when the
            // pyramids shot is up (forceSand). A grass texel at the horizon
            // stays green even after sand-coloured fog, which is the stripe
            // behind the monuments. Far sand is untextured so it can actually
            // converge on the haze.
            //
            // The cut is by FOCUS distance (d2), not camera distance. The
            // pyramids crane keeps the look-at still and dollies the camera,
            // so a camera-distance cut crawled across the dunes every frame
            // — textured sand vanishing and popping back as flat haze.
            const bool tileIsSand = forceSand
                || sandUnderlay
                || (desertAware
                    && desertEdgeAt(desertFieldX, desertFieldZ, mx, mz) > -tileSize);
            if (tileIsSand) {
                // Keep the 3 m / 10 m rings textured. Flattening them at a
                // camera- or focus-distance cut painted a crawling circle of
                // pale quads around the monuments. Only the coarse ring and
                // the sunk underlay go untextured.
                const bool farSand = sandUnderlay || tileSize >= 30.0f;
                if (farSand || !desertAware) {
                    // Far underlay is the haze colour itself — lighting a
                    // 200 m tile at grazing angle shaded the world-edge into
                    // a dark lip (the "green band" at the end of the crane).
                    ::Color flat = sandUnderlay
                        ? kDesertHorizonHaze
                        : shadeColor(::Color {216, 189, 132, 255},
                                     shadedLight * (0.92f + 0.14f * macro));
                    if (sandUnderlay && d2 < 900.0f * 900.0f) {
                        // Near cracks should read as sand, not washed haze.
                        flat = shadeColor(::Color {216, 189, 132, 255}, 0.96f);
                    }
                    flat = applyDistanceFog(flat, quadCenter, camera,
                        fogW.fogStart, fogW.fogEnd, fogW.fogAmountScale, fogW.fogColor);
                    const bool flatten = sandUnderlay && d2 > 900.0f * 900.0f;
                    const float y00 = flatten ? underlayY : h00 + yBias;
                    const float y10 = flatten ? underlayY : h10 + yBias;
                    const float y11 = flatten ? underlayY : h11 + yBias;
                    const float y01 = flatten ? underlayY : h01 + yBias;
                    flatTiles.push_back(LodSandTile {x0, z0, x1, z1,
                                                     y00, y10, y11, y01, flat});
                    continue;
                }
                ::Color sandTint = shadeColor(WHITE, shadedLight * (0.92f + 0.16f * macro));
                sandTint = applyDistanceFog(sandTint, quadCenter, camera,
                    fogW.fogStart, fogW.fogEnd, fogW.fogAmountScale, fogW.fogColor);
                sandTiles.push_back(LodSandTile {x0, z0, x1, z1,
                                                 h00 + yBias, h10 + yBias,
                                                 h11 + yBias, h01 + yBias, sandTint});
                continue;
            }

            tint = applyDistanceFog(tint, quadCenter, camera,
                fogW.fogStart, fogW.fogEnd, fogW.fogAmountScale, fogW.fogColor);

            if (textured) {
                rlCheckRenderBatchLimit(8);
                const float u0 = x0 * kTexScale, v0 = z0 * kTexScale;
                const float u1 = x1 * kTexScale, v1 = z1 * kTexScale;
                const float yLift = 0.02f + yBias;
                rlColor4ub(tint.r, tint.g, tint.b, 255);
                rlNormal3f(n0.x, n0.y, n0.z);
                rlTexCoord2f(u0, v0); rlVertex3f(x0, h00 + yLift, z0);
                rlTexCoord2f(u1, v0); rlVertex3f(x1, h10 + yLift, z0);
                rlTexCoord2f(u1, v1); rlVertex3f(x1, h11 + yLift, z1);
                rlTexCoord2f(u0, v1); rlVertex3f(x0, h01 + yLift, z1);

                // Near-only detail octave (kept mild — high UV scale looked pixelated)
                if (tileSize <= 2.0f && d2 < 28.0f * 28.0f) {
                    constexpr float kDetail = 2.15f;
                    const float du0 = u0 * kDetail, dv0 = v0 * kDetail;
                    const float du1 = u1 * kDetail, dv1 = v1 * kDetail;
                    rlColor4ub(tint.r, tint.g, tint.b, 48);
                    rlTexCoord2f(du0, dv0); rlVertex3f(x0, h00 + yLift + 0.01f, z0);
                    rlTexCoord2f(du1, dv0); rlVertex3f(x1, h10 + yLift + 0.01f, z0);
                    rlTexCoord2f(du1, dv1); rlVertex3f(x1, h11 + yLift + 0.01f, z1);
                    rlTexCoord2f(du0, dv1); rlVertex3f(x0, h01 + yLift + 0.01f, z1);
                }
            } else {
                DrawTriangle3D({x0, h00 + yBias, z0}, {x1, h10 + yBias, z0},
                               {x1, h11 + yBias, z1}, tint);
                DrawTriangle3D({x0, h00 + yBias, z0}, {x1, h11 + yBias, z1},
                               {x0, h01 + yBias, z1}, tint);
            }
        }
    }

    if (textured) {
        rlEnd();
        rlSetTexture(0);
    }

    // Dawn far field, untextured. Drawn through DrawTriangle3D — raw
    // rlBegin(RL_QUADS) quads after the textured batch kept sampling a
    // leftover dark texel and rendered near-black no matter the tint.
    if (!flatTiles.empty()) {
        for (const LodSandTile& t : flatTiles) {
            DrawTriangle3D({t.x0, t.h00, t.z0}, {t.x1, t.h10, t.z0},
                           {t.x1, t.h11, t.z1}, t.tint);
            DrawTriangle3D({t.x0, t.h00, t.z0}, {t.x1, t.h11, t.z1},
                           {t.x0, t.h01, t.z1}, t.tint);
        }
    }

    // Second pass: the same heightfield tiles, sand-tiled, for the biome
    // interior. Same 1/9 world-space UV as the carpet so the two layers line up.
    if (desertAware && !sandTiles.empty()) {
        constexpr float kSandUv = 1.0f / 9.0f;
        rlSetTexture(desertTex->id);
        rlBegin(RL_QUADS);
        rlNormal3f(0.0f, 1.0f, 0.0f);
        for (const LodSandTile& t : sandTiles) {
            rlCheckRenderBatchLimit(4);
            rlColor4ub(t.tint.r, t.tint.g, t.tint.b, 255);
            constexpr float yLift = 0.02f;
            rlTexCoord2f(t.x0 * kSandUv, t.z0 * kSandUv); rlVertex3f(t.x0, t.h00 + yLift, t.z0);
            rlTexCoord2f(t.x1 * kSandUv, t.z0 * kSandUv); rlVertex3f(t.x1, t.h10 + yLift, t.z0);
            rlTexCoord2f(t.x1 * kSandUv, t.z1 * kSandUv); rlVertex3f(t.x1, t.h11 + yLift, t.z1);
            rlTexCoord2f(t.x0 * kSandUv, t.z1 * kSandUv); rlVertex3f(t.x0, t.h01 + yLift, t.z1);
        }
        rlEnd();
        rlSetTexture(0);
    }
}

static void drawSmoothTerrain(
    const Vec3& playerPos,
    EnhancedAfricanTerrain& terrainSystem,
    const Camera3D& camera,
    const WeatherVisualParams& weather,
    float clarityMult,
    const Texture2D& grassTex,
    bool dawnSavanna = false,
    const Texture2D* desertTex = nullptr,
    float desertFieldX = 0.0f,
    float desertFieldZ = 0.0f,
    bool forceSand = false
) {
    const Vec3 focus {camera.target.x, playerPos.y, camera.target.z};
    // NOTE: each ring's max distance must stay within what its grid actually
    // covers (~(halfSpan-2)*tileSize) and the next ring must start exactly
    // there. The old radii claimed more than the grids spanned, which left
    // ring-shaped bands of missing terrain (sky showing through) at the
    // horizon.
    const float lodCap = GameSettings::terrainMaxDrawMeters(GameSettings::get().graphics);
    auto capped = [&](float maxDist) { return std::min(maxDist, lodCap); };
    if (dawnSavanna) {
        // Full GRASS_TOP carpet from under the camera out to the horizon.
        // Rings OVERLAP slightly (each min sits inside the previous max): at
        // exactly-abutting boundaries the two grids leave hairline cracks and
        // the backdrop glinted through them as bright slivers on the horizon.
        // The coarser ring now backfills the seam with same-coloured ground.
        drawTerrainLOD(focus, terrainSystem, camera, 3.0f,  42, 0.0f,   capped(120.0f),  weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
        rlDrawRenderBatchActive();
        if (lodCap > 105.0f) {
            drawTerrainLOD(focus, terrainSystem, camera, 10.0f, 36, 105.0f,  capped(340.0f), weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
            rlDrawRenderBatchActive();
        }
        if (lodCap > 290.0f) {
            drawTerrainLOD(focus, terrainSystem, camera, 36.0f, 30, 290.0f, capped(1008.0f), weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
            rlDrawRenderBatchActive();
        }
        if (lodCap > 860.0f) {
            drawTerrainLOD(focus, terrainSystem, camera, 110.0f,24, 860.0f, capped(2420.0f), weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
            rlDrawRenderBatchActive();
        }
        return;
    }
    if (forceSand) {
        // Sunk untextured sand under the whole view first. Overlapping
        // detail rings used to z-fight as the crane moved — that is the
        // desert "disappearing and reappearing". Hairline seams now fall
        // through to this underlay (sand, not grass or sky) instead of
        // two meshes fighting for the same pixels.
        drawTerrainLOD(focus, terrainSystem, camera, 200.0f, 30, 0.0f, 6000.0f,
                       weather, clarityMult, grassTex, false, desertTex,
                       desertFieldX, desertFieldZ, true, -0.70f, true);
        rlDrawRenderBatchActive();
        drawTerrainLOD(focus, terrainSystem, camera, 3.0f,  42, 0.0f,   125.0f,
                       weather, clarityMult, grassTex, false, desertTex,
                       desertFieldX, desertFieldZ, true, 0.0f, false);
        rlDrawRenderBatchActive();
        drawTerrainLOD(focus, terrainSystem, camera, 10.0f, 36, 110.0f,  345.0f,
                       weather, clarityMult, grassTex, false, desertTex,
                       desertFieldX, desertFieldZ, true, -0.12f, false);
        rlDrawRenderBatchActive();
        drawTerrainLOD(focus, terrainSystem, camera, 36.0f, 30, 325.0f, 1008.0f,
                       weather, clarityMult, grassTex, false, desertTex,
                       desertFieldX, desertFieldZ, true, -0.28f, false);
        rlDrawRenderBatchActive();
        return;
    }
    // Always grass-tint the heightfield — brown dirt LOD made tuft gaps look bare.
    // Flush between rings. The four of them submit ~42,000 immediate-mode
    // vertices against a batch that holds 32,768 by default, and nothing in
    // between forced a draw — so the far rings, and then the sand carpet later
    // in the frame, were being silently dropped by rlVertex3f.
    drawTerrainLOD(focus, terrainSystem, camera, 2.0f,  36, 0.0f,    68.0f,  weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
    rlDrawRenderBatchActive();
    drawTerrainLOD(focus, terrainSystem, camera, 8.0f,  34, 68.0f,   256.0f, weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
    rlDrawRenderBatchActive();
    drawTerrainLOD(focus, terrainSystem, camera, 32.0f, 28, 256.0f,  832.0f, weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
    rlDrawRenderBatchActive();
    drawTerrainLOD(focus, terrainSystem, camera, 100.0f,24, 832.0f, 2200.0f, weather, clarityMult, grassTex, true, desertTex, desertFieldX, desertFieldZ);
    rlDrawRenderBatchActive();
}

// ============================================================
// NUBIAN PYRAMIDS — port of Gold Mine world.ts pyramid() / genDesert().
// Steep stepped pyramids in sandstone / darkstone with an entrance chapel,
// plus the avenue of small chapels that lines the approach.
// ============================================================
static void nubianPyramidFieldXZ(const Vec3& playerPos, float* outX, float* outZ) {
    // One desert field per 3×3-cell region (3.6 km), at a hash-chosen cell —
    // nearest of the 9 surrounding regions. The old hash-gate had a fallback
    // that snapped a phantom field into the player's OWN cell whenever no
    // gated cell was in range: the desert (and its grass/tree exclusion)
    // followed the player around the savanna, eating the grass near spawn.
    constexpr float kCell = 1200.0f;
    constexpr float kRegion = kCell * 3.0f;
    const int srx = static_cast<int>(std::floor(playerPos.x / kRegion));
    const int srz = static_cast<int>(std::floor(playerPos.z / kRegion));
    float bestD2 = 1.0e30f;
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dx = -1; dx <= 1; ++dx) {
            const int rx = srx + dx;
            const int rz = srz + dz;
            const int cx = rx * 3 + static_cast<int>(hashNoise2D(rx * 41 + 220, rz * 37 + 880) * 2.999f);
            const int cz = rz * 3 + static_cast<int>(hashNoise2D(rx * 43 + 615, rz * 53 + 112) * 2.999f);
            const float ox = static_cast<float>(cx) * kCell + 280.0f;
            const float oz = static_cast<float>(cz) * kCell + 160.0f;
            const float ddx = ox - playerPos.x;
            const float ddz = oz - playerPos.z;
            const float d2 = ddx * ddx + ddz * ddz;
            if (d2 < bestD2) {
                bestD2 = d2;
                *outX = ox;
                *outZ = oz;
            }
        }
    }
}

// The five monuments as offsets from the field anchor. One table, three
// readers: the renderer builds them, the cacti keep off their footprints, and
// the wyvern flight roosts on them. It used to be copy-pasted per function,
// which is how the cacti table drifted out of step with the tints.
struct NubianPyramidSite {
    float lx;
    float lz;
    float base;
    ::Color tint;
};
static constexpr float kNubianPyramidSteep = 1.7f;
static constexpr NubianPyramidSite kNubianPyramidSites[] = {
    {-36.0f, -8.0f, 44.0f, ::Color {255, 249, 236, 255}},  // pale, still holds its casing
    { 16.0f,-32.0f, 34.0f, ::Color {241, 223, 194, 255}},
    { 56.0f, 20.0f, 28.0f, ::Color {255, 231, 199, 255}},  // the red sandstone one
    {  0.0f, 56.0f, 24.0f, ::Color {231, 219, 201, 255}},  // grey with weather
    { 80.0f,-48.0f, 20.0f, ::Color {248, 236, 212, 255}},
};
static constexpr int kNubianPyramidCount =
    static_cast<int>(sizeof(kNubianPyramidSites) / sizeof(kNubianPyramidSites[0]));

/** Apex height above the monument's own ground. Mirrors the layer count in
 *  drawGoldMinePyramid — one metre per course — so anything that wants to
 *  clear the tip agrees with what is actually drawn. */
static float nubianPyramidApex(float base) {
    return static_cast<float>(static_cast<int>((base * 0.5f) * kNubianPyramidSteep));
}

/** The same monuments expressed as wyvern roosts. Footprint and apex are
 *  derived from the numbers the renderer builds with, so the flight circles
 *  what is actually standing there rather than a guessed radius. */
static std::vector<WyvernRenderer::Roost> nubianPyramidRoosts() {
    std::vector<WyvernRenderer::Roost> out;
    out.reserve(static_cast<std::size_t>(kNubianPyramidCount));
    for (const NubianPyramidSite& s : kNubianPyramidSites) {
        WyvernRenderer::Roost r {};
        r.lx = s.lx;
        r.lz = s.lz;
        r.halfWidth = s.base * 0.5f;
        r.apexHeight = nubianPyramidApex(s.base);
        out.push_back(r);
    }
    return out;
}

static void drawGoldMinePyramid(float cx, float gy, float cz, float base,
                                const Texture2D& faceTex, float steep,
                                ::Color tint = WHITE) {
    const GoldMineBlockAtlas& blocks = gGoldMineBlocks;
    const int layers = static_cast<int>((base * 0.5f) * steep);
    blocks.beginCubes(faceTex);
    for (int y = 0; y <= layers; ++y) {
        const int ri = static_cast<int>(std::round(std::max(0.0f, base * 0.5f - static_cast<float>(y) / steep)));
        const float shade = 1.0f - static_cast<float>(y) / static_cast<float>(layers + 1) * 0.18f;
        const ::Color c {
            static_cast<unsigned char>(tint.r * shade),
            static_cast<unsigned char>(tint.g * shade),
            static_cast<unsigned char>(tint.b * shade),
            255};
        const float yb = gy + static_cast<float>(y) + 0.5f;
        if (ri <= 1) {
            blocks.emitCube({cx, yb, cz}, 1.08f, 1.08f, 1.08f, c);
            continue;
        }
        // 1 m ashlars on the step rim — a single r*2 slab was the grey pancake
        // that looked like the monument had failed to load.
        for (int dz = -ri; dz <= ri; ++dz) {
            for (int dx = -ri; dx <= ri; ++dx) {
                const int cheb = std::max(std::abs(dx), std::abs(dz));
                if (cheb < ri - 1) continue;
                blocks.emitCube({cx + static_cast<float>(dx), yb, cz + static_cast<float>(dz)},
                                1.08f, 1.08f, 1.08f, c);
            }
        }
        if (ri > 2) {
            const float fill = static_cast<float>((ri - 1) * 2) - 0.12f;
            blocks.emitCube({cx, yb, cz}, fill, 1.02f, fill, c);
        }
    }
    // Entrance chapel — world.ts box of sandstone + air doorway, not a
    // dark DrawCube hole punched in a stub.
    const int r0 = static_cast<int>(std::round(base * 0.5f));
    for (int y = 1; y <= 4; ++y) {
        for (int dz = -2; dz <= 2; ++dz) {
            for (int dx = 0; dx <= 3; ++dx) {
                const bool air = (y <= 3 && dz >= -1 && dz <= 1);
                if (air) continue;
                blocks.emitCube({cx + static_cast<float>(r0 + dx),
                                 gy + static_cast<float>(y) + 0.5f,
                                 cz + static_cast<float>(dz)},
                                1.08f, 1.08f, 1.08f, tint);
            }
        }
    }
    blocks.endCubes();
}

static void emitSandstoneShrine(const GoldMineBlockAtlas& blocks,
                                float x, float gy, float z, ::Color tint) {
    for (int y = 1; y <= 4; ++y) {
        for (int dz = -2; dz <= 2; ++dz) {
            for (int dx = -2; dx <= 2; ++dx) {
                const bool shell = (std::abs(dx) == 2 || std::abs(dz) == 2 || y == 4);
                if (!shell) continue;
                const bool door = (dx == 2 && std::abs(dz) <= 1 && y <= 3);
                if (door) continue;
                blocks.emitCube({x + static_cast<float>(dx),
                                 gy + static_cast<float>(y) + 0.5f,
                                 z + static_cast<float>(dz)},
                                1.08f, 1.08f, 1.08f, tint);
            }
        }
    }
}

static void drawNubianPyramids(const Vec3& playerPos, EnhancedAfricanTerrain& terrainSystem) {
    restoreDefault3DShader();
    float fieldX = 0.0f, fieldZ = 0.0f;
    nubianPyramidFieldXZ(playerPos, &fieldX, &fieldZ);

    // Sites from Gold Mine genDesert(), remapped around the field and scaled up
    // so they read as monuments rather than voxel toys — see kNubianPyramidSites.
    //
    // All sandstone. The voxel prototype alternated sandstone and DARKSTONE for
    // variety, but darkstone is #3a332e — against lit sand at this scale three
    // of the five monuments came out as near-black silhouettes, which is not
    // what Meroe looks like and read as a mistake. The variety now comes from
    // tinting the same warm stone, the way a real field weathers unevenly.
    const GoldMineBlockAtlas& blocks = gGoldMineBlocks;

    for (const NubianPyramidSite& s : kNubianPyramidSites) {
        const float x = fieldX + s.lx;
        const float z = fieldZ + s.lz;
        const float y = terrainSystem.getHeight(x, z);
        drawGoldMinePyramid(x, y, z, s.base, blocks.sandstone, kNubianPyramidSteep, s.tint);
        rlDrawRenderBatchActive();
    }

    // Avenue of small chapels lining the approach — real sandstone shrines,
    // not 2 m grey stubs.
    blocks.beginCubes(blocks.sandstone);
    for (int k = 0; k < 12; ++k) {
        const float x = fieldX - 88.0f + static_cast<float>(k) * 8.0f;
        for (const float zOff : {-68.0f, -40.0f}) {
            const float z = fieldZ + zOff;
            const float y = terrainSystem.getHeight(x, z);
            emitSandstoneShrine(blocks, x, y, z, WHITE);
        }
    }
    blocks.endCubes();
}

// ── NUBIAN DESERT SHAPE — Terraria-style sprawling biome, not a circle. ──
// Union of offset lobes around the pyramid field: ~1.8 × 1.6 km of sand
// with an organic boundary. Trees, grass, the sand carpet and the cacti
// all test against the same lobes so the biome edge is consistent.
//
// This was ~640 × 570 m, then ~1120 × 990 m, and the savanna still sat as a
// green stripe behind the monuments: the crane looks kilometres, and a
// grass texel will not turn into sand no matter how you fog it. The shot
// now paints the whole heightfield as sand; these lobes are the freeplay
// biome so walking the field is still desert, not a sandpit in a lawn.
struct DesertLobe { float dx; float dz; float r; };
// Roughly 2.4x the old radii so the sand runs past the draw distance and
// reads as desert continuing to the horizon, rather than a circular patch
// with green plains visible all the way round it. drawDesertSandGround's
// kStep grew with these to keep the quad count flat.
static constexpr DesertLobe kDesertLobes[] = {
    {    0.0f,     0.0f, 1730.0f },
    {-1000.0f,   385.0f, 1150.0f },
    { 1080.0f,  -335.0f, 1200.0f },
    {  575.0f,  1010.0f, 1030.0f },
    { -815.0f, -1010.0f, 1080.0f },
};
static constexpr int kDesertLobeCount =
    static_cast<int>(sizeof(kDesertLobes) / sizeof(kDesertLobes[0]));

/** Metres inside the desert boundary (max over lobes); negative = outside.
 *  Forward-declared above drawTerrainLOD. */
static float desertEdgeAt(float fieldX, float fieldZ, float x, float z) {
    float best = -1.0e9f;
    for (const DesertLobe& lobe : kDesertLobes) {
        const float dx = x - (fieldX + lobe.dx);
        const float dz = z - (fieldZ + lobe.dz);
        const float e = lobe.r - std::sqrt(dx * dx + dz * dz);
        if (e > best) best = e;
    }
    return best;
}

/**
 * Sand carpet under the Nubian Pyramids — Gold Mine blocks.ts T.SAND laid
 * over the terrain so the desert actually reads as desert, not grass.
 * Terrain-following quads with an alpha fade at the biome rim. Heights are
 * cached per field anchor so the per-frame cost is just quad submission.
 */
static void drawDesertSandGround(const Vec3& playerPos, const Camera3D& camera,
                                 EnhancedAfricanTerrain& terrainSystem,
                                 const WeatherVisualParams& weather) {
    const Texture2D& sandTex = gGoldMineBlocks.sand;
    if (sandTex.id <= 0) return;
    if (gGoldMineSetFade <= 0.0f) return;

    float fieldX = 0.0f, fieldZ = 0.0f;
    nubianPyramidFieldXZ(playerPos, &fieldX, &fieldZ);

    // 11 m cells, not 7. The grid spans the lobe bounding box, so widening the
    // biome to ~1120 m squared the cost: at 7 m that is ~22,900 immediate-mode
    // quads a frame against ~7,900 before, and kDrawDist no longer culls any of
    // them because the whole biome now fits inside it. This is flat ground with
    // smoothly drifting dune luminance and nothing to resolve at 7 m.
    // Cell size scales with the lobes below. The grid spans the lobe bounding
    // box, so widening the desert without widening the cell squares the quad
    // count — 11 m cells over the enlarged lobes would be ~130k quads a frame.
    // At 24 m the desert covers far more ground for the same cost, and this is
    // flat sand with nothing to resolve at 11 m anyway.
    constexpr float kStep = 24.0f;
    constexpr float kLift = 0.30f;   // above terrain bumps between grid samples
    // Wide rim fade so the sand dissolves into the plains over ~250 m instead
    // of ending on a visible circle.
    constexpr float kFade = 250.0f;

    WeatherVisualParams fogW = weather;
    fogW.fogStart = 420.0f;
    fogW.fogEnd = 1600.0f;
    fogW.fogAmountScale = 0.48f;
    fogW.fogColor = ::Color {216, 176, 120, 255};

    // Bounding box of the lobe union, in field-local metres.
    float minX = 1.0e9f, maxX = -1.0e9f, minZ = 1.0e9f, maxZ = -1.0e9f;
    for (const DesertLobe& lobe : kDesertLobes) {
        minX = std::min(minX, lobe.dx - lobe.r);
        maxX = std::max(maxX, lobe.dx + lobe.r);
        minZ = std::min(minZ, lobe.dz - lobe.r);
        maxZ = std::max(maxZ, lobe.dz + lobe.r);
    }
    const float x0 = fieldX + minX;
    const float z0 = fieldZ + minZ;
    const int nx = static_cast<int>(std::ceil((maxX - minX) / kStep));
    const int nz = static_cast<int>(std::ceil((maxZ - minZ) / kStep));

    // Per-vertex terrain height, dune luminance and rim alpha. None of these
    // depend on the camera, so they are built once per field anchor — only the
    // fog blend below is paid per frame.
    static float cachedX = 1.0e30f, cachedZ = 1.0e30f;
    static std::vector<float> heights;
    static std::vector<unsigned char> duneLum;
    static std::vector<unsigned char> rimAlpha;
    if (cachedX != fieldX || cachedZ != fieldZ) {
        const size_t n = static_cast<size_t>((nx + 1) * (nz + 1));
        heights.assign(n, 0.0f);
        duneLum.assign(n, 255);
        rimAlpha.assign(n, 0);
        for (int j = 0; j <= nz; ++j) {
            for (int i = 0; i <= nx; ++i) {
                const float x = x0 + i * kStep;
                const float z = z0 + j * kStep;
                const size_t k = static_cast<size_t>(j * (nx + 1) + i);
                heights[k] = terrainSystem.getHeight(x, z) + kLift;
                // Smooth drift, replacing the old per-cell random luminance
                // that tiled the biome into flat-shaded 7 m squares.
                const float dune = goldMineFbm(x * 0.018f, z * 0.018f, 3, 61) * 0.58f
                                 + goldMineFbm(x * 0.062f, z * 0.062f, 2, 17) * 0.42f;
                duneLum[k] = static_cast<unsigned char>(
                    std::min(255.0f, 255.0f * (0.86f + dune * 0.30f)));
                const float rim = std::max(0.0f, std::min(1.0f,
                    desertEdgeAt(fieldX, fieldZ, x, z) / kFade));
                rimAlpha[k] = static_cast<unsigned char>(rim * 255.0f);
            }
        }
        cachedX = fieldX;
        cachedZ = fieldZ;
    }
    const auto emit = [&](int i, int j, float x, float z, float u, float v) {
        const size_t k = static_cast<size_t>(j * (nx + 1) + i);
        const unsigned char l8 = duneLum[k];
        const float y = heights[k];
        const ::Color c = applyDistanceFog(::Color {l8, l8, l8, 255}, Vector3 {x, y, z}, camera,
                                           fogW.fogStart, fogW.fogEnd,
                                           fogW.fogAmountScale, fogW.fogColor);
        rlColor4ub(c.r, c.g, c.b,
                   static_cast<unsigned char>(static_cast<float>(rimAlpha[k]) * gGoldMineSetFade));
        rlTexCoord2f(u, v);
        rlVertex3f(x, y, z);
    };

    rlDisableBackfaceCulling();
    rlSetTexture(sandTex.id);
    rlBegin(RL_QUADS);
    rlNormal3f(0.0f, 1.0f, 0.0f);
    for (int j = 0; j < nz; ++j) {
        const float za = z0 + j * kStep;
        const float zb = za + kStep;
        for (int i = 0; i < nx; ++i) {
            const float xa = x0 + i * kStep;
            const float xb = xa + kStep;
            // Skip cells whose centre is well outside the biome.
            if (desertEdgeAt(fieldX, fieldZ, xa + kStep * 0.5f, za + kStep * 0.5f) < -kStep) {
                continue;
            }
            // Draw every biome cell. Distance and frustum culls both made
            // cells pop as the camera moved, leaving holes that read as the
            // desert disappearing. The grid is static once the field is
            // cached, so this cost does not change per frame.
            rlCheckRenderBatchLimit(4);
            // Repeat off a prime-ish span so the tile seams stop landing on the
            // quad grid and reinforcing it.
            constexpr float kUvScale = 1.0f / 9.0f;
            emit(i,     j,     xa, za, xa * kUvScale, za * kUvScale);
            emit(i,     j + 1, xa, zb, xa * kUvScale, zb * kUvScale);
            emit(i + 1, j + 1, xb, zb, xb * kUvScale, zb * kUvScale);
            emit(i + 1, j,     xb, za, xb * kUvScale, za * kUvScale);
        }
    }
    rlEnd();
    rlSetTexture(0);
    rlEnableBackfaceCulling();
}

/** Gold Mine cactus.glb scattered through the Nubian desert — off the monuments. */
static void drawDesertCacti(const Vec3& playerPos, const Vector3& camPos,
                            EnhancedAfricanTerrain& terrainSystem,
                            const CactusRenderer& cacti) {
    if (!cacti.isReady()) return;
    float fieldX = 0.0f, fieldZ = 0.0f;
    nubianPyramidFieldXZ(playerPos, &fieldX, &fieldZ);

    // cactus.glb is a 40k-tri model — scatter across the whole lobe union but
    // only draw the ones near the camera.
    constexpr float kSpacing = 13.0f;
    // 190 m put the cull line inside the trailer crane's own framing, so cacti
    // popped in across the middle of the shot.
    constexpr float kCullDist = 900.0f;
    float minX = 1.0e9f, maxX = -1.0e9f, minZ = 1.0e9f, maxZ = -1.0e9f;
    for (const DesertLobe& lobe : kDesertLobes) {
        minX = std::min(minX, lobe.dx - lobe.r);
        maxX = std::max(maxX, lobe.dx + lobe.r);
        minZ = std::min(minZ, lobe.dz - lobe.r);
        maxZ = std::max(maxZ, lobe.dz + lobe.r);
    }
    const int cxA = static_cast<int>(std::floor((fieldX + minX) / kSpacing));
    const int cxB = static_cast<int>(std::ceil((fieldX + maxX) / kSpacing));
    const int czA = static_cast<int>(std::floor((fieldZ + minZ) / kSpacing));
    const int czB = static_cast<int>(std::ceil((fieldZ + maxZ) / kSpacing));

    for (int cellZ = czA; cellZ <= czB; ++cellZ) {
        for (int cellX = cxA; cellX <= cxB; ++cellX) {
            const float n = hashNoise2D(cellX * 13 + 5, cellZ * 11 + 3);
            if (n < 0.68f) continue;

            const float x = static_cast<float>(cellX) * kSpacing
                          + (hashNoise2D(cellX, 51) - 0.5f) * 8.0f;
            const float z = static_cast<float>(cellZ) * kSpacing
                          + (hashNoise2D(cellZ, 53) - 0.5f) * 8.0f;
            // Stay inside the biome, off the fading rim.
            if (desertEdgeAt(fieldX, fieldZ, x, z) < 6.0f) continue;
            const float cdx = x - camPos.x;
            const float cdz = z - camPos.z;
            if (cdx * cdx + cdz * cdz > kCullDist * kCullDist) continue;

            bool onMonument = false;
            for (const NubianPyramidSite& s : kNubianPyramidSites) {
                const float mx = x - (fieldX + s.lx);
                const float mz = z - (fieldZ + s.lz);
                const float r = s.base * 0.5f + 6.0f;
                if (mx * mx + mz * mz < r * r) { onMonument = true; break; }
            }
            if (onMonument) continue;
            // Keep the chapel avenue clear too.
            if (z > fieldZ - 74.0f && z < fieldZ - 34.0f
                && x > fieldX - 94.0f && x < fieldX + 8.0f) continue;

            const float y = terrainSystem.getHeight(x, z);
            const float sizeVar = 0.7f + hashNoise2D(cellX + 7, cellZ - 9) * 0.8f;
            const float yaw = hashNoise2D(cellX - 3, cellZ + 17) * 360.0f;
            cacti.drawOne(x, y, z, sizeVar, yaw);
        }
    }
}

// ============================================================
// THE TEAR BETWEEN WORLDS — world.ts genRift() / codex "the-seam".
// A chasm tearing the savanna in half, rift-stone lining, inverted
// Africa hanging above, and #00ffb4 motes rising out of the cut.
// Anchored at the existing "RIFT MARKER" pillar (spawn + 80, 80)
// so the trailer shot and freeplay look at the same place.
// ============================================================
static float gRiftSeamX = 0.0f;
static float gRiftSeamZ = 0.0f;

static void riftSeamXZ(float* outX, float* outZ) {
    *outX = gRiftSeamX;
    *outZ = gRiftSeamZ;
}

static float riftSeamCenterX(float z) {
    // world.ts: cx = 64 + sin(z * 0.06) * 8, scaled to metres.
    return gRiftSeamX + std::sin((z - gRiftSeamZ) * 0.024f) * 22.0f;
}

static float riftSeamHalfW(float z) {
    return 9.0f + goldMineFbm((z - gRiftSeamZ) * 0.05f, 0.0f, 3, 2) * 10.0f;
}

static bool inWorldTearScar(float x, float z) {
    const float dz = z - gRiftSeamZ;
    if (std::fabs(dz) > 145.0f) return false;
    return std::fabs(x - riftSeamCenterX(z)) < riftSeamHalfW(z) + 4.0f;
}

static void applyRiftTreeKeepout(SavannaTreeRenderer& trees) {
    trees.setExclusionZone(12, gRiftSeamX, gRiftSeamZ - 90.0f, 58.0f);
    trees.setExclusionZone(13, gRiftSeamX, gRiftSeamZ, 58.0f);
    trees.setExclusionZone(14, gRiftSeamX, gRiftSeamZ + 90.0f, 58.0f);
}

static void drawWorldTear(EnhancedAfricanTerrain& terrainSystem, const Camera3D& camera,
                          float time) {
    const float ox = gRiftSeamX;
    const float oz = gRiftSeamZ;
    const float cdx = camera.position.x - ox;
    const float cdz = camera.position.z - oz;
    if (cdx * cdx + cdz * cdz > 900.0f * 900.0f) return;

    constexpr float kLen = 280.0f;
    constexpr float kStep = 5.0f;
    constexpr float kDepth = 36.0f;
    constexpr ::Color kAbyss {2, 10, 12, 255};
    constexpr ::Color kWall {6, 28, 26, 255};
    constexpr ::Color kLip {0, 255, 180, 255};
    constexpr ::Color kGlow {0, 220, 160, 255};

    rlDisableBackfaceCulling();
    // Mouth of the tear: dark strip covering the grass, then walls dropping
    // into the cut so a look across it reads as a hole, not a painted line.
    for (float z = oz - kLen * 0.5f; z < oz + kLen * 0.5f; z += kStep) {
        const float z1 = z + kStep;
        const float cx0 = riftSeamCenterX(z);
        const float cx1 = riftSeamCenterX(z1);
        const float w0 = riftSeamHalfW(z);
        const float w1 = riftSeamHalfW(z1);
        const float yL0 = terrainSystem.getHeight(cx0 - w0, z);
        const float yR0 = terrainSystem.getHeight(cx0 + w0, z);
        const float yL1 = terrainSystem.getHeight(cx1 - w1, z1);
        const float yR1 = terrainSystem.getHeight(cx1 + w1, z1);
        const float yC0 = (yL0 + yR0) * 0.5f - kDepth;
        const float yC1 = (yL1 + yR1) * 0.5f - kDepth;
        const float lift = 0.12f;

        DrawTriangle3D({cx0 - w0, yL0 + lift, z}, {cx0 + w0, yR0 + lift, z},
                       {cx1 + w1, yR1 + lift, z1}, kAbyss);
        DrawTriangle3D({cx0 - w0, yL0 + lift, z}, {cx1 + w1, yR1 + lift, z1},
                       {cx1 - w1, yL1 + lift, z1}, kAbyss);

        DrawTriangle3D({cx0 - w0, yL0, z}, {cx0, yC0, z}, {cx1, yC1, z1}, kWall);
        DrawTriangle3D({cx0 - w0, yL0, z}, {cx1, yC1, z1}, {cx1 - w1, yL1, z1}, kWall);
        DrawTriangle3D({cx0 + w0, yR0, z}, {cx1 + w1, yR1, z1}, {cx1, yC1, z1}, kWall);
        DrawTriangle3D({cx0 + w0, yR0, z}, {cx1, yC1, z1}, {cx0, yC0, z}, kWall);
    }

    // Glowing rift lining — world.ts B.RIFT on both lips.
    const GoldMineBlockAtlas& blocks = gGoldMineBlocks;
    const bool tex = blocks.ready && blocks.glow.id > 0;
    for (float z = oz - kLen * 0.5f; z < oz + kLen * 0.5f; z += 3.2f) {
        const float cx = riftSeamCenterX(z);
        const float hw = riftSeamHalfW(z);
        for (int s = -1; s <= 1; s += 2) {
            const float x = cx + static_cast<float>(s) * hw;
            const float y = terrainSystem.getHeight(x, z);
            const float pulse = 0.55f + 0.45f * std::sin(time * 2.4f + z * 0.08f);
            const ::Color lip {
                static_cast<unsigned char>(kLip.r * pulse),
                static_cast<unsigned char>(kLip.g * pulse),
                static_cast<unsigned char>(kLip.b * pulse), 255};
            if (tex) {
                blocks.drawCube(blocks.glow, {x, y + 0.55f, z}, 1.15f, 1.15f, 1.15f, lip);
                if (hashNoise2D(static_cast<int>(x), static_cast<int>(z)) > 0.7f) {
                    blocks.drawCube(blocks.glow, {x, y + 1.6f, z}, 0.85f, 0.85f, 0.85f, kGlow);
                }
            } else {
                DrawCube({x, y + 0.55f, z}, 1.15f, 1.15f, 1.15f, lip);
            }
        }
    }

    // Parallel Africa bleeding through — inverted islands above the tear.
    for (int k = 0; k < 9; ++k) {
        const float n1 = hashNoise2D(k * 13 + 3, 91);
        const float n2 = hashNoise2D(k * 17 + 5, 44);
        const float n3 = hashNoise2D(k * 19 + 7, 22);
        const float n4 = hashNoise2D(k * 23 + 9, 8);
        const float ix = ox - 18.0f + n1 * 36.0f;
        const float iz = oz - 90.0f + n2 * 180.0f;
        const float gy = terrainSystem.getHeight(ix, iz);
        const float iy = gy + 22.0f + n3 * 18.0f;
        const float r = 4.2f + n4 * 5.5f;
        DrawSphereEx({ix, iy, iz}, r, 8, 8, ::Color {86, 72, 52, 255});
        DrawSphereEx({ix, iy + r * 0.35f, iz}, r * 0.92f, 8, 8, ::Color {72, 118, 48, 255});
        if (k % 3 == 0) {
            DrawCylinder({ix, iy + r * 0.6f, iz}, 0.22f, 0.18f, 3.4f, 6, ::Color {90, 62, 36, 255});
            DrawSphereEx({ix, iy + r * 0.6f + 4.2f, iz}, 2.4f, 6, 6, ::Color {68, 112, 44, 255});
        }
    }

    // Floating rift shards along the seam.
    for (int k = 0; k < 80; ++k) {
        const float n1 = hashNoise2D(k + 9, 1);
        const float n2 = hashNoise2D(k + 3, 2);
        const float n3 = hashNoise2D(k + 5, 3);
        const float n4 = hashNoise2D(k + 7, 4);
        const float z = oz - kLen * 0.5f + n1 * kLen;
        const float cx = riftSeamCenterX(z);
        const float x = cx + (n2 - 0.5f) * 28.0f;
        const float gy = terrainSystem.getHeight(x, z);
        const float y = gy + 8.0f + n3 * 28.0f;
        const float s = 0.55f + n4 * 0.7f;
        const ::Color shard = (n4 > 0.6f) ? kGlow : kLip;
        DrawCube({x, y, z}, s, s, s, shard);
    }
    rlEnableBackfaceCulling();
}

/** world.ts genRift particles: 1200, #00ffb4, size 0.26, rise 0.9. */
static void drawRiftMotes(const Camera3D& camera, float time) {
    const float ox = gRiftSeamX;
    const float oz = gRiftSeamZ;
    const float cdx = camera.position.x - ox;
    const float cdz = camera.position.z - oz;
    if (cdx * cdx + cdz * cdz > 700.0f * 700.0f) return;

    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    for (int i = 0; i < 420; ++i) {
        unsigned n = static_cast<unsigned>(i) * 2654435761u;
        n ^= n >> 15U;
        const float uz = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 1274126177u; n ^= n >> 13U;
        const float ux = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 2246822519u; n ^= n >> 11U;
        const float uy = static_cast<float>(n & 0xFFFFU) / 65535.0f;
        n = n * 374761393u; n ^= n >> 11U;
        const float ph = static_cast<float>(n & 0xFFFFU) / 65535.0f;

        const float z = oz + (uz - 0.5f) * 240.0f;
        const float cx = riftSeamCenterX(z);
        const float x = cx + (ux - 0.5f) * 36.0f;
        const float y = camera.target.y - 8.0f + uy * 40.0f
                        + std::fmod(time * 0.9f + ph * 11.0f, 28.0f);
        const unsigned char a8 = static_cast<unsigned char>(
            90.0f + 110.0f * (0.5f + 0.5f * std::sin(time * 1.7f + ph * 20.0f)));
        DrawSphereEx({x, y, z}, 0.18f + uy * 0.12f, 4, 4, ::Color {0, 255, 180, a8});
    }
    rlEnableDepthMask();
    EndBlendMode();
}

// ============================================================
// CONGO RAINFOREST — the set behind the "Into the Cathedral" and
// "Canopy" trailer shots, both of which used to play over open savanna
// because no forest existed. Same anchoring scheme as the Nubian desert.
// ============================================================
static void jungleFieldXZ(const Vec3& playerPos, float* outX, float* outZ) {
    constexpr float kCell = 1200.0f;
    constexpr float kRegion = kCell * 3.0f;
    const int srx = static_cast<int>(std::floor(playerPos.x / kRegion));
    const int srz = static_cast<int>(std::floor(playerPos.z / kRegion));
    float bestD2 = 1.0e30f;
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dx = -1; dx <= 1; ++dx) {
            const int rx = srx + dx;
            const int rz = srz + dz;
            // The desert's chosen cell for this same region — the jungle must
            // not land on it, or the two biomes fight over the same ground.
            const int dcx = static_cast<int>(hashNoise2D(rx * 41 + 220, rz * 37 + 880) * 2.999f);
            const int dcz = static_cast<int>(hashNoise2D(rx * 43 + 615, rz * 53 + 112) * 2.999f);
            int jcx = static_cast<int>(hashNoise2D(rx * 17 + 909, rz * 23 + 455) * 2.999f);
            int jcz = static_cast<int>(hashNoise2D(rx * 29 + 131, rz * 19 + 707) * 2.999f);
            if (jcx == dcx && jcz == dcz) jcx = (jcx + 1) % 3;  // >= 1.2 km apart
            const float ox = static_cast<float>(rx * 3 + jcx) * kCell + 620.0f;
            const float oz = static_cast<float>(rz * 3 + jcz) * kCell + 540.0f;
            const float ddx = ox - playerPos.x;
            const float ddz = oz - playerPos.z;
            const float d2 = ddx * ddx + ddz * ddz;
            if (d2 < bestD2) {
                bestD2 = d2;
                *outX = ox;
                *outZ = oz;
            }
        }
    }
}

// Sprawling lobed outline, same trick as the desert so the treeline is
// organic rather than a circle. ~700 x 620 m of forest.
struct JungleLobe { float dx; float dz; float r; };
static constexpr JungleLobe kJungleLobes[] = {
    {   0.0f,    0.0f, 185.0f },
    {-150.0f,  -70.0f, 140.0f },
    { 165.0f,   55.0f, 150.0f },
    {  60.0f, -160.0f, 125.0f },
    {-100.0f,  150.0f, 130.0f },
};
static constexpr int kJungleLobeCount =
    static_cast<int>(sizeof(kJungleLobes) / sizeof(kJungleLobes[0]));

/** Metres inside the jungle boundary (max over lobes); negative = outside. */
static float jungleEdgeAt(float fieldX, float fieldZ, float x, float z) {
    float best = -1.0e9f;
    for (const JungleLobe& lobe : kJungleLobes) {
        const float dx = x - (fieldX + lobe.dx);
        const float dz = z - (fieldZ + lobe.dz);
        const float e = lobe.r - std::sqrt(dx * dx + dz * dz);
        if (e > best) best = e;
    }
    return best;
}

// ============================================================
// WINTER WONDERLAND — alpine snow field + ice monsters.
// Same 3x3 region lattice as desert/jungle; cell chosen to avoid both.
// ============================================================
static void winterFieldXZ(const Vec3& playerPos, float* outX, float* outZ) {
    constexpr float kCell = 1200.0f;
    constexpr float kRegion = kCell * 3.0f;
    const int srx = static_cast<int>(std::floor(playerPos.x / kRegion));
    const int srz = static_cast<int>(std::floor(playerPos.z / kRegion));
    float bestD2 = 1.0e30f;
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dx = -1; dx <= 1; ++dx) {
            const int rx = srx + dx;
            const int rz = srz + dz;
            const int dcx = static_cast<int>(hashNoise2D(rx * 41 + 220, rz * 37 + 880) * 2.999f);
            const int dcz = static_cast<int>(hashNoise2D(rx * 43 + 615, rz * 53 + 112) * 2.999f);
            int jcx = static_cast<int>(hashNoise2D(rx * 17 + 909, rz * 23 + 455) * 2.999f);
            int jcz = static_cast<int>(hashNoise2D(rx * 29 + 131, rz * 19 + 707) * 2.999f);
            if (jcx == dcx && jcz == dcz) jcx = (jcx + 1) % 3;
            int wcx = static_cast<int>(hashNoise2D(rx * 71 + 404, rz * 67 + 303) * 2.999f);
            int wcz = static_cast<int>(hashNoise2D(rx * 83 + 515, rz * 59 + 212) * 2.999f);
            if ((wcx == dcx && wcz == dcz) || (wcx == jcx && wcz == jcz)) {
                wcx = (wcx + 2) % 3;
            }
            const float ox = static_cast<float>(rx * 3 + wcx) * kCell + 880.0f;
            const float oz = static_cast<float>(rz * 3 + wcz) * kCell + 720.0f;
            const float ddx = ox - playerPos.x;
            const float ddz = oz - playerPos.z;
            const float d2 = ddx * ddx + ddz * ddz;
            if (d2 < bestD2) {
                bestD2 = d2;
                *outX = ox;
                *outZ = oz;
            }
        }
    }
}

struct WinterLobe { float dx; float dz; float r; };
static constexpr WinterLobe kWinterLobes[] = {
    {   0.0f,    0.0f, 160.0f },
    {-120.0f,  -55.0f, 120.0f },
    { 130.0f,   70.0f, 130.0f },
    {  40.0f, -140.0f, 110.0f },
    { -90.0f,  125.0f, 115.0f },
};
static constexpr int kWinterLobeCount =
    static_cast<int>(sizeof(kWinterLobes) / sizeof(kWinterLobes[0]));
static constexpr float kWinterClearRadius = 280.0f;

static float winterEdgeAt(float fieldX, float fieldZ, float x, float z) {
    float best = -1.0e9f;
    for (const WinterLobe& lobe : kWinterLobes) {
        const float dx = x - (fieldX + lobe.dx);
        const float dz = z - (fieldZ + lobe.dz);
        const float e = lobe.r - std::sqrt(dx * dx + dz * dz);
        if (e > best) best = e;
    }
    return best;
}

/**
 * Leaf-litter floor under the Congo canopy — dirt tiles laid over the
 * terrain so the rainforest does not read as savanna turf. Same structure
 * as drawDesertSandGround: opaque across the biome with distance fog
 * carrying it into the haze, per-vertex shading and rim alpha cached per
 * field anchor, and only the fog blend paid per frame.
 */
static void drawJungleFloor(const Vec3& playerPos, const Camera3D& camera,
                            EnhancedAfricanTerrain& terrainSystem,
                            const WeatherVisualParams& weather) {
    const Texture2D& litterTex = gGoldMineBlocks.dirt;
    if (litterTex.id <= 0) return;
    if (gGoldMineSetFade <= 0.0f) return;
    const Vector3 camPos = camera.position;
    constexpr float kDrawDist = 1400.0f;

    float fieldX = 0.0f, fieldZ = 0.0f;
    jungleFieldXZ(playerPos, &fieldX, &fieldZ);

    constexpr float kStep = 7.0f;
    constexpr float kLift = 0.28f;
    constexpr float kFade = 30.0f;

    // Humid green gloom rather than the desert's warm dust.
    WeatherVisualParams fogW = weather;
    fogW.fogStart = 260.0f;
    fogW.fogEnd = 1100.0f;
    fogW.fogAmountScale = 0.62f;
    fogW.fogColor = ::Color {104, 128, 92, 255};

    float minX = 1.0e9f, maxX = -1.0e9f, minZ = 1.0e9f, maxZ = -1.0e9f;
    for (const JungleLobe& lobe : kJungleLobes) {
        minX = std::min(minX, lobe.dx - lobe.r);
        maxX = std::max(maxX, lobe.dx + lobe.r);
        minZ = std::min(minZ, lobe.dz - lobe.r);
        maxZ = std::max(maxZ, lobe.dz + lobe.r);
    }
    const float x0 = fieldX + minX;
    const float z0 = fieldZ + minZ;
    const int nx = static_cast<int>(std::ceil((maxX - minX) / kStep));
    const int nz = static_cast<int>(std::ceil((maxZ - minZ) / kStep));

    static float cachedX = 1.0e30f, cachedZ = 1.0e30f;
    static std::vector<float> heights;
    static std::vector<unsigned char> litterLum;
    static std::vector<unsigned char> rimAlpha;
    if (cachedX != fieldX || cachedZ != fieldZ) {
        const size_t n = static_cast<size_t>((nx + 1) * (nz + 1));
        heights.assign(n, 0.0f);
        litterLum.assign(n, 255);
        rimAlpha.assign(n, 0);
        for (int j = 0; j <= nz; ++j) {
            for (int i = 0; i <= nx; ++i) {
                const float x = x0 + i * kStep;
                const float z = z0 + j * kStep;
                const size_t k = static_cast<size_t>(j * (nx + 1) + i);
                heights[k] = terrainSystem.getHeight(x, z) + kLift;
                // Patchy litter and moss, darker than open ground because the
                // canopy is meant to be eating the light.
                const float patch = goldMineFbm(x * 0.021f, z * 0.021f, 3, 29) * 0.6f
                                  + goldMineFbm(x * 0.080f, z * 0.080f, 2, 47) * 0.4f;
                litterLum[k] = static_cast<unsigned char>(
                    std::min(255.0f, 255.0f * (0.42f + patch * 0.34f)));
                const float rim = std::max(0.0f, std::min(1.0f,
                    jungleEdgeAt(fieldX, fieldZ, x, z) / kFade));
                rimAlpha[k] = static_cast<unsigned char>(rim * 255.0f);
            }
        }
        cachedX = fieldX;
        cachedZ = fieldZ;
    }
    const auto emit = [&](int i, int j, float x, float z, float u, float v) {
        const size_t k = static_cast<size_t>(j * (nx + 1) + i);
        const unsigned char l8 = litterLum[k];
        const float y = heights[k];
        // Slight green bias so the floor is leaf mould, not desert dirt.
        const ::Color base {
            static_cast<unsigned char>(l8 * 0.86f),
            l8,
            static_cast<unsigned char>(l8 * 0.70f),
            255
        };
        const ::Color c = applyDistanceFog(base, Vector3 {x, y, z}, camera,
                                           fogW.fogStart, fogW.fogEnd,
                                           fogW.fogAmountScale, fogW.fogColor);
        rlColor4ub(c.r, c.g, c.b,
                   static_cast<unsigned char>(static_cast<float>(rimAlpha[k]) * gGoldMineSetFade));
        rlTexCoord2f(u, v);
        rlVertex3f(x, y, z);
    };

    rlDisableBackfaceCulling();
    rlSetTexture(litterTex.id);
    rlBegin(RL_QUADS);
    rlNormal3f(0.0f, 1.0f, 0.0f);
    for (int j = 0; j < nz; ++j) {
        const float za = z0 + j * kStep;
        const float zb = za + kStep;
        for (int i = 0; i < nx; ++i) {
            const float xa = x0 + i * kStep;
            const float xb = xa + kStep;
            if (jungleEdgeAt(fieldX, fieldZ, xa + kStep * 0.5f, za + kStep * 0.5f) < -kStep) {
                continue;
            }
            {
                const float ccx = xa + kStep * 0.5f - camPos.x;
                const float ccz = za + kStep * 0.5f - camPos.z;
                if (ccx * ccx + ccz * ccz > (kDrawDist + kStep) * (kDrawDist + kStep)) continue;
            }
            rlCheckRenderBatchLimit(4);
            constexpr float kUvScale = 1.0f / 5.0f;
            emit(i,     j,     xa, za, xa * kUvScale, za * kUvScale);
            emit(i,     j + 1, xa, zb, xa * kUvScale, zb * kUvScale);
            emit(i + 1, j + 1, xb, zb, xb * kUvScale, zb * kUvScale);
            emit(i + 1, j,     xb, za, xb * kUvScale, za * kUvScale);
        }
    }
    rlEnd();
    rlSetTexture(0);
    rlEnableBackfaceCulling();
}

// ============================================================
// THE REGISTRY — the false god's laboratory, out on its own.
// ============================================================
// Same 3x3 nearest-region lattice as the desert and jungle, with its own
// hash salts. It steps off BOTH of their cells: a metal facility poking
// out of a dune or swallowed by rainforest reads as a bug, and the point
// of the place is that it sits alone in empty savanna.
//
// As with the others there is deliberately NO fallback to the player's own
// cell — that is exactly what used to make the village teleport whenever
// the player crossed a grid line.
static void labFieldXZ(const Vec3& playerPos, float* outX, float* outZ) {
    constexpr float kCell = 1200.0f;
    constexpr float kRegion = kCell * 3.0f;
    const int srx = static_cast<int>(std::floor(playerPos.x / kRegion));
    const int srz = static_cast<int>(std::floor(playerPos.z / kRegion));
    float bestD2 = 1.0e30f;
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dx = -1; dx <= 1; ++dx) {
            const int rx = srx + dx;
            const int rz = srz + dz;
            // Desert and jungle picks for this region, recomputed with the
            // same salts they use so the three never share a cell.
            const int dcx = static_cast<int>(hashNoise2D(rx * 41 + 220, rz * 37 + 880) * 2.999f);
            const int dcz = static_cast<int>(hashNoise2D(rx * 43 + 615, rz * 53 + 112) * 2.999f);
            int jcx = static_cast<int>(hashNoise2D(rx * 17 + 909, rz * 23 + 455) * 2.999f);
            const int jcz = static_cast<int>(hashNoise2D(rx * 29 + 131, rz * 19 + 707) * 2.999f);
            if (jcx == dcx && jcz == dcz) jcx = (jcx + 1) % 3;

            int lcx = static_cast<int>(hashNoise2D(rx * 59 + 313, rz * 67 + 271) * 2.999f);
            int lcz = static_cast<int>(hashNoise2D(rx * 71 + 823, rz * 61 + 149) * 2.999f);
            for (int guard = 0; guard < 3; ++guard) {
                const bool onDesert = (lcx == dcx && lcz == dcz);
                const bool onJungle = (lcx == jcx && lcz == jcz);
                if (!onDesert && !onJungle) break;
                lcx = (lcx + 1) % 3;
                if (lcx == 0) lcz = (lcz + 1) % 3;
            }
            const float ox = static_cast<float>(rx * 3 + lcx) * kCell + 305.0f;
            const float oz = static_cast<float>(rz * 3 + lcz) * kCell + 870.0f;
            const float ddx = ox - playerPos.x;
            const float ddz = oz - playerPos.z;
            const float d2 = ddx * ddx + ddz * ddz;
            if (d2 < bestD2) {
                bestD2 = d2;
                *outX = ox;
                *outZ = oz;
            }
        }
    }
}

/** Outer radius covering the lab footprint plus a clear apron around it. */
static constexpr float kLabClearRadius = 26.0f;
// Grass hugs the walls — 26 m left a bald checkerboard apron around the lab.
static constexpr float kLabGrassClearRadius = 10.0f;

// ============================================================
// GOLD MINE VILLAGE — port of world.ts hut() + genZimbabwe().
// Round mudbrick thatched huts, the Great Enclosure dry-stone wall
// with its ruined north gap, conical tower, market fires, terraces.
// ============================================================
static void goldMineVillageXZ(const Vec3& playerPos, float* outX, float* outZ) {
    // One Great Enclosure per 3×3-cell region (~1.9 km), at a hash-chosen
    // cell — nearest of the 9 surrounding regions wins. The old version
    // hash-gated cells (~18%) and fell back to floor-cell snapping when no
    // gated cell was in range: that fallback village TELEPORTED every time
    // the player crossed a 640 m grid line ("it disappeared outta nowhere").
    // This placement is deterministic and only switches anchors ~1 km out.
    constexpr float kCell = 640.0f;
    constexpr float kRegion = kCell * 3.0f;
    const int srx = static_cast<int>(std::floor(playerPos.x / kRegion));
    const int srz = static_cast<int>(std::floor(playerPos.z / kRegion));
    float bestD2 = 1.0e30f;
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dx = -1; dx <= 1; ++dx) {
            const int rx = srx + dx;
            const int rz = srz + dz;
            const int cx = rx * 3 + static_cast<int>(hashNoise2D(rx * 17 + 901, rz * 29 + 447) * 2.999f);
            const int cz = rz * 3 + static_cast<int>(hashNoise2D(rx * 23 + 133, rz * 31 + 577) * 2.999f);
            const float ox = static_cast<float>(cx) * kCell + 48.0f
                           + (hashNoise2D(cx, cz + 3) - 0.5f) * 80.0f;
            const float oz = static_cast<float>(cz) * kCell + 32.0f
                           + (hashNoise2D(cx + 5, cz) - 0.5f) * 80.0f;
            const float ddx = ox - playerPos.x;
            const float ddz = oz - playerPos.z;
            const float d2 = ddx * ddx + ddz * ddz;
            if (d2 < bestD2) {
                bestD2 = d2;
                *outX = ox;
                *outZ = oz;
            }
        }
    }
}

/** The Tear Between Worlds — own hashed cell, never on desert / jungle / lab
 *  / Great Enclosure. Spawn+80 put the chasm through Dry Stone's wall track. */
static void riftFieldXZ(const Vec3& playerPos, float* outX, float* outZ) {
    constexpr float kCell = 1200.0f;
    constexpr float kRegion = kCell * 3.0f;
    const int srx = static_cast<int>(std::floor(playerPos.x / kRegion));
    const int srz = static_cast<int>(std::floor(playerPos.z / kRegion));
    float vx = 0.0f, vz = 0.0f;
    goldMineVillageXZ(playerPos, &vx, &vz);
    float bestD2 = 1.0e30f;
    float bestX = vx + 1600.0f;
    float bestZ = vz - 900.0f;
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dx = -1; dx <= 1; ++dx) {
            const int rx = srx + dx;
            const int rz = srz + dz;
            const int dcx = static_cast<int>(hashNoise2D(rx * 41 + 220, rz * 37 + 880) * 2.999f);
            const int dcz = static_cast<int>(hashNoise2D(rx * 43 + 615, rz * 53 + 112) * 2.999f);
            int jcx = static_cast<int>(hashNoise2D(rx * 17 + 909, rz * 23 + 455) * 2.999f);
            const int jcz = static_cast<int>(hashNoise2D(rx * 29 + 131, rz * 19 + 707) * 2.999f);
            if (jcx == dcx && jcz == dcz) jcx = (jcx + 1) % 3;
            int lcx = static_cast<int>(hashNoise2D(rx * 59 + 313, rz * 67 + 271) * 2.999f);
            int lcz = static_cast<int>(hashNoise2D(rx * 71 + 823, rz * 61 + 149) * 2.999f);
            for (int guard = 0; guard < 3; ++guard) {
                if (!((lcx == dcx && lcz == dcz) || (lcx == jcx && lcz == jcz))) break;
                lcx = (lcx + 1) % 3;
                if (lcx == 0) lcz = (lcz + 1) % 3;
            }
            int rcx = static_cast<int>(hashNoise2D(rx * 83 + 190, rz * 97 + 404) * 2.999f);
            int rcz = static_cast<int>(hashNoise2D(rx * 89 + 616, rz * 73 + 228) * 2.999f);
            for (int guard = 0; guard < 6; ++guard) {
                const bool onDesert = (rcx == dcx && rcz == dcz);
                const bool onJungle = (rcx == jcx && rcz == jcz);
                const bool onLab = (rcx == lcx && rcz == lcz);
                if (!onDesert && !onJungle && !onLab) break;
                rcx = (rcx + 1) % 3;
                if (rcx == 0) rcz = (rcz + 1) % 3;
            }
            const float ox = static_cast<float>(rx * 3 + rcx) * kCell + 740.0f;
            const float oz = static_cast<float>(rz * 3 + rcz) * kCell + 210.0f;
            const float vdx = ox - vx;
            const float vdz = oz - vz;
            if (vdx * vdx + vdz * vdz < 550.0f * 550.0f) continue;
            const float ddx = ox - playerPos.x;
            const float ddz = oz - playerPos.z;
            const float d2 = ddx * ddx + ddz * ddz;
            if (d2 < bestD2) {
                bestD2 = d2;
                bestX = ox;
                bestZ = oz;
            }
        }
    }
    *outX = bestX;
    *outZ = bestZ;
}

/** Village house — GameObject Gaia meshes, mudbrick cubes if they failed to load. */
static void drawGoldMineHut(float cx, float gy, float cz, float r, int seed) {
    if (gGaiaHouses.isReady()) {
        const float yaw = hashNoise2D(seed * 19 + 3, seed * 7 + 11) * 360.0f;
        gGaiaHouses.draw(cx, gy, cz, yaw, seed);
        return;
    }
    const float wallH = 3.0f;
    const GoldMineBlockAtlas& blocks = gGoldMineBlocks;
    // 1.08 m ashlars on a 1 m grid overlap so a seam cannot open as a sky square.
    constexpr float kAsh = 1.08f;

    const int ri = static_cast<int>(std::ceil(r));
    blocks.beginCubes(blocks.mudbrick);
    for (int dz = -ri; dz <= ri; ++dz) {
        for (int dx = -ri; dx <= ri; ++dx) {
            const float d = std::sqrt(static_cast<float>(dx * dx + dz * dz));
            if (d > r || d <= r - 1.15f) continue;
            if (dx >= static_cast<int>(r) - 1 && std::abs(dz) <= 1) continue;
            for (int y = 1; y <= static_cast<int>(wallH); ++y) {
                blocks.emitCube({cx + static_cast<float>(dx), gy + static_cast<float>(y) + 0.5f,
                                 cz + static_cast<float>(dz)},
                                kAsh, kAsh, kAsh, WHITE);
            }
        }
    }
    blocks.endCubes();

    const int rh = static_cast<int>(std::ceil(r * 1.5f));
    blocks.beginCubes(blocks.thatch);
    for (int y = 0; y <= rh; ++y) {
        const float rr = r + 0.8f - (static_cast<float>(y) / std::max(1, rh)) * (r + 0.8f);
        const int span = static_cast<int>(std::ceil(rr + 0.5f));
        for (int dz = -span; dz <= span; ++dz) {
            for (int dx = -span; dx <= span; ++dx) {
                const float d = std::sqrt(static_cast<float>(dx * dx + dz * dz));
                if (d > rr + 0.5f) continue;
                blocks.emitCube({cx + static_cast<float>(dx),
                                 gy + wallH + static_cast<float>(y) + 0.5f,
                                 cz + static_cast<float>(dz)},
                                kAsh, kAsh, kAsh, WHITE);
            }
        }
    }
    blocks.endCubes();

    if (hashNoise2D(static_cast<int>(cx) + seed * 17, static_cast<int>(cz)) > 0.55f) {
        blocks.drawCube(blocks.wood,
            {cx, gy + wallH + static_cast<float>(rh) + 1.5f, cz},
            0.45f, 1.2f, 0.45f, WHITE);
    }
}

static void drawVillageSettlement(const Vec3& playerPos, EnhancedAfricanTerrain& terrainSystem,
                                  bool dryStoneOnly) {
    restoreDefault3DShader();
    float cx = 0.0f, cz = 0.0f;
    goldMineVillageXZ(playerPos, &cx, &cz);
    const GoldMineBlockAtlas& blocks = gGoldMineBlocks;

    // Great Enclosure — Gold Mine genZimbabwe granite columns.
    // The north breach is a TUNNEL through the four-course wall (lintel stays
    // up), not a missing tooth that reads as the wall failing to load.
    constexpr int kSegs = 256;
    constexpr int kThick = 4;
    constexpr float kTunnelA0 = 4.68f;
    constexpr float kTunnelA1 = 4.92f;
    constexpr float kTunnelH = 4.35f;
    constexpr float kSink = 1.45f;
    blocks.beginCubes(blocks.granite);
    for (int a = 0; a < kSegs; ++a) {
        const float ang = (static_cast<float>(a) / static_cast<float>(kSegs)) * 2.0f * kPi;
        const bool tunnel = (ang > kTunnelA0 && ang < kTunnelA1);
        const float rr = 30.0f + std::sin(ang * 3.0f) * 2.5f;
        for (int t = 0; t < kThick; ++t) {
            const float x = cx + std::cos(ang) * (rr + static_cast<float>(t));
            const float z = cz + std::sin(ang) * (rr + static_cast<float>(t));
            const float gy = terrainSystem.getHeight(x, z);
            const float n = hashNoise2D(static_cast<int>(x * 0.1f), static_cast<int>(z * 0.1f));
            const float wallH = 9.0f - static_cast<float>(t) * 0.85f + n * 1.6f;
            if (tunnel) {
                // Floor of the passage — beaten granite, not a grass slice.
                blocks.emitCube({x, gy + 0.12f, z}, 1.62f, 0.40f, 1.62f, WHITE);
                if (wallH > kTunnelH + 0.8f) {
                    const float lintelH = wallH - kTunnelH;
                    blocks.emitCube({x, gy + kTunnelH + lintelH * 0.5f + 0.5f, z},
                                    1.62f, lintelH, 1.62f, WHITE);
                }
            } else {
                blocks.emitCube({x, gy + (wallH + kSink) * 0.5f + 0.15f, z},
                                1.62f, wallH + kSink, 1.62f, WHITE);
            }
        }
    }
    blocks.endCubes();
    rlDrawRenderBatchActive();

    if (dryStoneOnly) return;

    const float centerY = terrainSystem.getHeight(cx, cz);

    {
        const float tx = cx + 14.0f;
        const float tz = cz + 8.0f;
        const float ty = terrainSystem.getHeight(tx, tz);
        blocks.beginCubes(blocks.granite);
        for (int y = 0; y < 16; y += 2) {
            const float rad = 5.0f - static_cast<float>(y) * 0.2f;
            const int span = static_cast<int>(std::ceil(rad));
            for (int dz = -span; dz <= span; ++dz) {
                for (int dx = -span; dx <= span; ++dx) {
                    if (std::sqrt(static_cast<float>(dx * dx + dz * dz)) > rad) continue;
                    blocks.emitCube({tx + static_cast<float>(dx), ty + 1.0f + static_cast<float>(y) + 1.0f,
                                     tz + static_cast<float>(dz)},
                                    1.08f, 2.08f, 1.08f, WHITE);
                }
            }
        }
        blocks.endCubes();
        rlDrawRenderBatchActive();
    }

    auto plantHut = [&](float ox, float oz, float radius, int seed) {
        const float hx = cx + ox;
        const float hz = cz + oz;
        const float hy = terrainSystem.getHeight(hx, hz);
        drawGoldMineHut(hx, hy, hz, radius, seed);
        const float fx = hx + 6.0f;
        const float fz = hz + 4.0f;
        const float fy = terrainSystem.getHeight(fx, fz);
        // Ember, not a 1 m glowing cube — those read as the "invisible squares"
        // sitting at the hut feet through the north gap.
        DrawSphereEx({fx, fy + 0.55f, fz}, 0.22f, 8, 8, ::Color {255, 168, 72, 220});
        blocks.drawCube(blocks.wood, {fx, fy + 0.22f, fz}, 0.7f, 0.28f, 0.7f, WHITE);
    };

    plantHut(-12.0f, -10.0f, 4.2f, 0);
    plantHut(  8.0f, -12.0f, 4.2f, 1);
    plantHut( -8.0f,  12.0f, 4.2f, 2);
    plantHut( 12.0f,  14.0f, 4.2f, 3);
    // Forge stands in the inner ring as the fifth house.
    plantHut(  0.0f, -20.0f, 4.2f, -1);

    for (int i = 0; i < 8; ++i) {
        const float a = (static_cast<float>(i) / 8.0f) * 2.0f * kPi + 0.18f;
        plantHut(std::cos(a) * 48.0f, std::sin(a) * 48.0f, 4.0f, 20 + i);
    }

    blocks.beginCubes(blocks.granite);
    for (int k = 0; k < 40; ++k) {
        const float a = hashNoise2D(k, 3) * 2.0f * kPi;
        const float r = 40.0f + hashNoise2D(k, 7) * 22.0f;
        const float x = cx + std::cos(a) * r;
        const float z = cz + std::sin(a) * r;
        const float gy = terrainSystem.getHeight(x, z);
        const int layers = 1 + static_cast<int>(hashNoise2D(k, 1) * 2.99f);
        for (int ly = 0; ly < layers; ++ly) {
            const float s = 6.2f - static_cast<float>(ly) * 1.15f;
            blocks.emitCube({x, gy + 0.55f + static_cast<float>(ly), z},
                            s, 1.12f, s, WHITE);
        }
    }
    blocks.endCubes();
    rlDrawRenderBatchActive();

    gSoilClumps.drawPlaza(cx, centerY + 0.55f, cz);
}

static void showcaseMainVillageXZ(const Vec3& p, float* outX, float* outZ) {
    goldMineVillageXZ(p, outX, outZ);
}

static void showcaseHiddenCampXZ(const Vec3& p, float* outX, float* outZ) {
    // Memory / childhood camp offset from a rare village cell
    float vx = 0.0f, vz = 0.0f;
    goldMineVillageXZ(p, &vx, &vz);
    *outX = vx + 180.0f;
    *outZ = vz - 140.0f;
}

// ============================================================
// TRUE KNOWLEDGE — ward strength only (no geometric FX shapes).
// Places that remember + Frequency Armor damp corrupt 3D→5D bleed.
// ============================================================
static constexpr float kKnowledgeFieldRadius = 52.0f;

/** 0..1 how strongly the Great Stone City wards this position. */
static float villageKnowledgeProtection(const Vec3& p) {
    float vx = 0.0f, vz = 0.0f;
    goldMineVillageXZ(p, &vx, &vz);
    const float dx = p.x - vx;
    const float dz = p.z - vz;
    const float d = std::sqrt(dx * dx + dz * dz);
    if (d >= kKnowledgeFieldRadius) return 0.0f;
    const float t = 1.0f - d / kKnowledgeFieldRadius;
    return t * t;
}

// ============================================================
// BARTER MARKET — port of npc.ts buildBarterMarket().
// Ring of stalls on the granite plaza: real goods for real goods.
// ============================================================
static ::Color hexRgb(unsigned int rgb) {
    return ::Color {
        static_cast<unsigned char>((rgb >> 16) & 0xFF),
        static_cast<unsigned char>((rgb >> 8) & 0xFF),
        static_cast<unsigned char>(rgb & 0xFF),
        255
    };
}

static void drawBarterMarketStall(float ox, float oy, float oz, float rotY, int stallIdx) {
    static constexpr unsigned int kStallColors[] = {
        0x9a3b2e, 0x1a4d4d, 0x7a5230, 0x3b5e8c, 0x4b6b32, 0xc1694f
    };
    static constexpr unsigned int kGoodsColors[] = {
        0xd4891a, 0x7bbf5a, 0xb9a06a, 0xc1694f, 0xe8dcc0, 0x8a5c38
    };
    const GoldMineBlockAtlas& blocks = gGoldMineBlocks;
    const ::Color cloth = hexRgb(kStallColors[stallIdx % 6]);

    rlPushMatrix();
    rlTranslatef(ox, oy, oz);
    rlRotatef(rotY * RAD2DEG, 0.0f, 1.0f, 0.0f);

    // Table from blocks.ts WOOD / PLANK look
    blocks.drawCube(blocks.wood, {0.0f, 1.0f, 0.0f}, 2.6f, 0.14f, 1.3f, WHITE);
    for (const float lx : {-1.15f, 1.15f}) {
        for (const float lz : {-0.5f, 0.5f}) {
            blocks.drawCube(blocks.wood, {lx, 0.5f, lz}, 0.14f, 1.0f, 0.14f, WHITE);
        }
    }
    for (const float px : {-1.2f, 1.2f}) {
        blocks.drawCube(blocks.wood, {px, 1.3f, -0.55f}, 0.12f, 2.6f, 0.12f, WHITE);
    }
    // Canopy cloth (dyed) over thatch weave
    blocks.drawCube(blocks.thatch, {0.0f, 2.55f, -0.1f}, 2.9f, 0.06f, 1.6f, cloth);
    for (int j = 0; j < 5; ++j) {
        const float gx = -0.9f + (j / 4.0f) * 1.8f;
        const ::Color gc = hexRgb(kGoodsColors[(stallIdx + j) % 6]);
        const Vector3 p {gx, 1.2f, 0.1f + (j % 2) * 0.25f};
        const int kind = (stallIdx + j) % 3;
        if (kind == 0) DrawSphereEx(p, 0.18f, 10, 10, gc);
        else if (kind == 1) blocks.drawCube(blocks.thatch, p, 0.36f, 0.3f, 0.36f, gc);
        else blocks.drawCube(blocks.mudbrick, p, 0.32f, 0.34f, 0.32f, gc);
    }
    rlPopMatrix();
}

static void drawBarterMarket(const Vec3& playerPos, EnhancedAfricanTerrain& terrainSystem) {
    float cx = 0.0f, cz = 0.0f;
    goldMineVillageXZ(playerPos, &cx, &cz);
    // Gold Mine stalls are placed relative to world centre (64,64)
    static constexpr float kStalls[][3] = {
        {-6.0f, -4.0f, 0.4f}, {6.0f, -4.0f, 1.2f}, {-6.0f, 8.0f, 2.0f},
        {6.0f, 8.0f, 2.8f}, {-12.0f, 2.0f, 0.9f}, {12.0f, 2.0f, 2.3f}
    };
    for (int i = 0; i < 6; ++i) {
        const float x = cx + kStalls[i][0];
        const float z = cz + kStalls[i][1];
        const float y = terrainSystem.getHeight(x, z);
        drawBarterMarketStall(x, y, z, kStalls[i][2], i);
    }
    // Central gathering fire — GLOW + WOOD from blocks.ts
    const float fy = terrainSystem.getHeight(cx, cz);
    gGoldMineBlocks.drawCube(gGoldMineBlocks.wood, {cx, fy + 0.4f, cz}, 2.0f, 0.4f, 2.0f, WHITE);
    gGoldMineBlocks.drawCube(gGoldMineBlocks.glow, {cx, fy + 1.2f, cz}, 0.9f, 1.2f, 0.9f, WHITE);
}

