class HolographicPillar {
public:
    Vec3 position;
    std::string gnosticConcept;
    ::Color symbolColor;
    float rotation {0.0f};
    float pulsePhase {0.0f};
    bool isActive {true};
    static Model pillarModel;
    static bool modelLoaded;
    
    HolographicPillar(const Vec3& pos, const std::string& concept, const ::Color& col)
        : position(pos), gnosticConcept(concept), symbolColor(col) {
        // Load model on first pillar creation
        if (!modelLoaded) {
            loadModel();
        }
    }
    
    static void loadModel() {
        if (modelLoaded) return;
        const char* modelPath = "D:\\Ashwins Games-Minecraft Stuff\\Project Inertia\\basics_3D\\models\\ancient_stone_pillar__3d_model__game_ready__p.glb";
        std::cout << "Loading pillar model from: " << modelPath << "\n";
        std::cout << "Model file exists: ";
        
        FILE* f = fopen(modelPath, "rb");
        if (f) {
            std::cout << "YES\n";
            fclose(f);
        } else {
            std::cout << "NO\n";
        }
        
        pillarModel = LoadModel(modelPath);
        modelLoaded = true;
        
        std::cout << "Model loaded.\n";
        std::cout << "  Mesh count: " << pillarModel.meshCount << "\n";
        std::cout << "  Material count: " << pillarModel.materialCount << "\n";
        
        if (pillarModel.meshCount > 0) {
            std::cout << "  First mesh vertices: " << pillarModel.meshes[0].vertexCount << "\n";
        }
    }
    
    static void unloadModel() {
        if (modelLoaded) {
            UnloadModel(pillarModel);
            modelLoaded = false;
        }
    }
    
    void update(float dt) {
        rotation += dt * 45.0f;
        pulsePhase += dt * 3.0f;
        if (pulsePhase > 2.0f * 3.14159f) pulsePhase -= 2.0f * 3.14159f;
    }
    
    void draw(float clarityMult) {
        // TEST: Draw huge red spheres at pillar positions - absolutely impossible to miss
        std::cout << "Drawing pillar at: " << position.x << ", " << position.y << ", " << position.z << "\n";
        
        rlPushMatrix();
        rlTranslatef(position.x, position.y, position.z);
        
        // Draw HUGE 5-unit radius sphere in solid color
        DrawSphere({0, 0, 0}, 5.0f, symbolColor);
        DrawSphere({0, 0, 0}, 5.2f, WHITE);  // Outline
        
        rlPopMatrix();
    }
    
    void drawAtPosition(float clarityMult, const Vec3& pos) {
        // Draw pillar at specific position - STATIONARY, TALL STRUCTURES
        rlPushMatrix();
        // Move pillar up significantly to be more prominent
        rlTranslatef(pos.x, pos.y + 10.0f, pos.z);
        
        // NO rotation, NO bobbing - just draw as solid structure
        // Scale up MUCH larger - 10x to be towering monuments
        rlScalef(10.0f, 10.0f, 10.0f);
        
        // Draw the actual ancient stone pillar model if loaded
        if (modelLoaded && pillarModel.meshCount > 0) {
            DrawModel(pillarModel, {0, 0, 0}, 1.0f, WHITE);
        } else {
            // Fallback: draw HUGE tall colored cylinder if model didn't load
            DrawCylinder({0, 5.0f, 0}, 2.5f, 2.5f, 15.0f, 16, symbolColor);
            DrawCylinderWires({0, 5.0f, 0}, 2.5f, 2.5f, 15.0f, 16, WHITE);
        }
        
        rlPopMatrix();
    }
};

