class SpectatorMode {
public:
    bool isActive {false};
    Vec3 position {0, 5, 0};
    float speed {30.0f};  // Units per second
    bool isNighttime {false};
    Texture2D nightSkyTexture {0};
    Texture2D multidimensionalGrassTexture {0};
    
    SpectatorMode() {
        // Try to load nighttime sky
        const char* nightSkyPath = "D:\\Ashwins Games-Minecraft Stuff\\Project Inertia\\basics_3D\\models\\Nighttime sky.jpeg";
        nightSkyTexture = LoadTexture(nightSkyPath);
        std::cout << "Loading nighttime sky from: " << nightSkyPath << "\n";
        if (nightSkyTexture.id != 0) {
            std::cout << "Nighttime sky texture loaded successfully\n";
        } else {
            std::cout << "Warning: Could not load nighttime sky texture\n";
        }
        
        // Try to load multidimensional grass
        const char* grassPath = "D:\\Ashwins Games-Minecraft Stuff\\Project Inertia\\basics_3D\\models\\Multidimensonal Grass.gif";
        multidimensionalGrassTexture = LoadTexture(grassPath);
        std::cout << "Loading multidimensional grass from: " << grassPath << "\n";
        if (multidimensionalGrassTexture.id != 0) {
            std::cout << "Multidimensional grass texture loaded successfully\n";
            // Enable texture wrapping for tiling
            SetTextureWrap(multidimensionalGrassTexture, TEXTURE_WRAP_REPEAT);
        } else {
            std::cout << "Warning: Could not load multidimensional grass texture\n";
        }
    }
    
    ~SpectatorMode() {
        if (nightSkyTexture.id != 0) {
            UnloadTexture(nightSkyTexture);
        }
        if (multidimensionalGrassTexture.id != 0) {
            UnloadTexture(multidimensionalGrassTexture);
        }
    }
    
    void update(float dt) {
        if (!isActive) return;
        
        // Free-flying camera controls (spectator mode like Minecraft)
        float moveSpeed = speed * dt;
        
        // WASD for movement in horizontal plane
        if (IsKeyDown(KEY_W)) position.z += moveSpeed;
        if (IsKeyDown(KEY_S)) position.z -= moveSpeed;
        if (IsKeyDown(KEY_A)) position.x -= moveSpeed;
        if (IsKeyDown(KEY_D)) position.x += moveSpeed;
        
        // SPACE/CTRL for vertical movement
        if (IsKeyDown(KEY_SPACE)) position.y += moveSpeed;
        if (IsKeyDown(KEY_LEFT_CONTROL)) position.y -= moveSpeed;
        
        // SHIFT for sprint
        if (IsKeyDown(KEY_LEFT_SHIFT)) speed = 60.0f;
        else speed = 30.0f;
    }
    
    Camera3D getCamera() const {
        Camera3D cam;
        cam.position = {position.x, position.y, position.z};
        cam.target = {position.x, position.y - 1.0f, position.z + 1.0f};
        cam.up = {0.0f, 1.0f, 0.0f};
        cam.fovy = 60.0f;
        cam.projection = CAMERA_PERSPECTIVE;
        return cam;
    }
    
    void drawNightSky() {
        if (!isNighttime || nightSkyTexture.id == 0) return;
        
        // Draw nighttime sky as full-screen texture
        DrawTexture(nightSkyTexture, 0, 0, WHITE);
    }
};

// ============================================================
// DAY CYCLE — world clock (AM/PM), sun path, grade shader.
// Rise ~6:00 · shine midday/afternoon · set ~19:00 · night moon.
// ============================================================
class DayCycleSystem {
public:
    void init() {
        const char* vs = R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\game_3D\code\shaders\daycycle_grade.vs)";
        const char* fs = R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\game_3D\code\shaders\daycycle_grade.fs)";
        if (FileExists(vs) && FileExists(fs)) {
            gradeShader = LoadShader(vs, fs);
            hasGrade = gradeShader.id > 0;
            if (hasGrade) {
                hourLoc = GetShaderLocation(gradeShader, "uHour");
                strengthLoc = GetShaderLocation(gradeShader, "uStrength");
                sunUvLoc = GetShaderLocation(gradeShader, "uSunUV");
                shineLoc = GetShaderLocation(gradeShader, "uShine");
                warpLoc = GetShaderLocation(gradeShader, "uWarp");
                timeLoc = GetShaderLocation(gradeShader, "uTime");
                std::cout << "Day-cycle grade + sun-shine shader ready.\n";
            }
        } else {
            std::cout << "Day-cycle grade shader files missing.\n";
        }
        ensureTarget(GetScreenWidth(), GetScreenHeight());
    }

    ~DayCycleSystem() {
        if (hasGrade) {
            UnloadShader(gradeShader);
            hasGrade = false;
        }
        if (hasTarget) {
            UnloadRenderTexture(sceneTarget);
            hasTarget = false;
        }
    }

    void setHour(float h) {
        hour = wrap24(h);
    }

    float getHour() const { return hour; }

    void update(float dt, bool advance) {
        if (advance) {
            // Full day every 30 real minutes.
            hour = wrap24(hour + dt * (24.0f / 1800.0f));
        }
        if (IsKeyPressed(KEY_EQUAL) || IsKeyPressed(KEY_KP_ADD)) {
            hour = wrap24(hour + 1.0f);
        }
        if (IsKeyPressed(KEY_MINUS) || IsKeyPressed(KEY_KP_SUBTRACT)) {
            hour = wrap24(hour - 1.0f);
        }
    }

    // 12-hour clock string, e.g. "02:34 PM" (gameplay HUD only).
    std::string formatClock12() const {
        int totalMin = static_cast<int>(std::floor(hour * 60.0f)) % (24 * 60);
        if (totalMin < 0) totalMin += 24 * 60;
        int h24 = totalMin / 60;
        int m = totalMin % 60;
        const bool pm = h24 >= 12;
        int h12 = h24 % 12;
        if (h12 == 0) h12 = 12;
        char buf[32];
        std::snprintf(buf, sizeof(buf), "%02d:%02d %s", h12, m, pm ? "PM" : "AM");
        return std::string(buf);
    }

    const char* periodName() const {
        if (hour >= 5.0f && hour < 7.0f) return "DAWN";
        if (hour >= 7.0f && hour < 11.5f) return "MORNING";
        if (hour >= 11.5f && hour < 16.0f) return "AFTERNOON";
        if (hour >= 16.0f && hour < 19.5f) return "EVENING";
        if (hour >= 19.5f && hour < 21.5f) return "DUSK";
        return "NIGHT";
    }

    /**
     * Sky gradient for an explicit hour.
     *
     * These used to be hard bands, so the sky jumped between five flat palettes
     * at 5.5, 7, 16.5, 19.5 and 21 — a visible pop, and badly timed against
     * stars that fade in gradually. Keyframed and interpolated instead.
     *
     * The hour is a parameter rather than the member because the trailer
     * freezes the clock at 8am and each shot supplies its own render hour; the
     * gradient reading `hour` directly is what made night shots come out blue.
     */
    static ::Color skyTopAt(float h) { return sampleSkyBand(h, true); }
    static ::Color skyBotAt(float h) { return sampleSkyBand(h, false); }

    ::Color skyTop() const { return skyTopAt(hour); }
    ::Color skyBot() const { return skyBotAt(hour); }

    static ::Color sampleSkyBand(float h, bool top) {
        struct Key { float hour; ::Color top; ::Color bot; };
        // Wraps at 24: the first and last key are the same midnight sky.
        static const Key kKeys[] = {
            { 0.0f,  {14, 20,  40, 255}, { 10,  14,  30, 255}},  // night
            { 4.6f,  {14, 20,  40, 255}, { 10,  14,  30, 255}},
            { 6.2f,  {88, 112, 138, 255}, {210, 186, 162, 255}}, // soft dawn (muted)
            { 8.2f,  {92, 128, 152, 255}, {168, 182, 186, 255}}, // Valheim day — cool grey-blue
            {16.5f,  {92, 128, 152, 255}, {168, 182, 186, 255}},
            {18.7f,  {118, 98, 118, 255}, {220, 148, 102, 255}}, // softer sunset
            {20.4f,  {48,  54,  88, 255}, { 34,  32,  58, 255}}, // dusk
            {21.8f,  {14,  20,  40, 255}, { 10,  14,  30, 255}}, // night
            {24.0f,  {14,  20,  40, 255}, { 10,  14,  30, 255}},
        };
        constexpr int kCount = static_cast<int>(sizeof(kKeys) / sizeof(kKeys[0]));
        while (h < 0.0f) h += 24.0f;
        while (h >= 24.0f) h -= 24.0f;
        int i = 0;
        while (i < kCount - 2 && h > kKeys[i + 1].hour) ++i;
        const Key& a = kKeys[i];
        const Key& b = kKeys[i + 1];
        const float span = std::max(1.0e-4f, b.hour - a.hour);
        float t = std::max(0.0f, std::min(1.0f, (h - a.hour) / span));
        t = t * t * (3.0f - 2.0f * t);
        const ::Color ca = top ? a.top : a.bot;
        const ::Color cb = top ? b.top : b.bot;
        auto mixc = [t](unsigned char x, unsigned char y) {
            return static_cast<unsigned char>(x + (y - x) * t);
        };
        return ::Color {mixc(ca.r, cb.r), mixc(ca.g, cb.g), mixc(ca.b, cb.b), 255};
    }

    float sunIntensity() const {
        return VisualEnvironmentAssets::sunShineFromHour(hour);
    }

    Vec3 sunDirection() const {
        return VisualEnvironmentAssets::sunDirectionFromHour(hour, nullptr);
    }

    Vector3 sunColorLinear() const {
        const ::Color c = VisualEnvironmentAssets::sunTintFromHour(hour);
        return {
            static_cast<float>(c.r) / 255.0f,
            static_cast<float>(c.g) / 255.0f,
            static_cast<float>(c.b) / 255.0f
        };
    }

    void beginSceneCapture() {
        ensureTarget(GetScreenWidth(), GetScreenHeight());
        if (!hasTarget) return;
        rlDrawRenderBatchActive();
        rlEnableDepthTest();
        rlEnableDepthMask();
        BeginTextureMode(sceneTarget);
        capturingFrame = true;
    }

    void endSceneCaptureAndGrade(const Camera3D& camera, float renderHour, bool pinDawnSun,
                                 float realityWarp = 0.0f) {
        if (!hasTarget || !capturingFrame) return;
        EndTextureMode();
        capturingFrame = false;
        rlDisableDepthTest();
        rlDisableDepthMask();
        rlSetTexture(0);
        const int sw = GetScreenWidth();
        const int sh = GetScreenHeight();

        // Project sun into UV for the shine / shaft pass.
        const Vec3 sunDir = VisualEnvironmentAssets::sunDirectionFromHour(
            renderHour, pinDawnSun ? &camera : nullptr);
        const float kDist = pinDawnSun ? 1100.0f : 1400.0f;
        const Vector3 sunWorld {
            camera.position.x + sunDir.x * kDist,
            camera.position.y + sunDir.y * kDist,
            camera.position.z + sunDir.z * kDist};
        const Vector2 sunPix = GetWorldToScreen(sunWorld, camera);
        // Screen Y is top-down; shader UVs match the flipped RT (y=0 at bottom).
        float sunUV[2] = {
            sunPix.x / static_cast<float>(sw),
            1.0f - (sunPix.y / static_cast<float>(sh))
        };
        // If the sun is off-screen, park UV far away so we don't light the dirt.
        if (sunPix.x < -80.0f || sunPix.x > static_cast<float>(sw) + 80.0f
            || sunPix.y < -80.0f || sunPix.y > static_cast<float>(sh) + 80.0f
            || sunDir.y < -0.02f) {
            sunUV[0] = -10.0f;
            sunUV[1] = -10.0f;
        }
        float shine = VisualEnvironmentAssets::sunShineFromHour(renderHour);
        if (pinDawnSun) shine = std::max(shine, 0.70f) * 0.65f;
        else shine *= 0.65f;

        const Rectangle src {
            0.0f, 0.0f,
            static_cast<float>(sceneTarget.texture.width),
            -static_cast<float>(sceneTarget.texture.height)
        };
        // Stretch to the window. DrawTextureRec used the RT's native pixels
        // at (0,0) — a resize, DPI mismatch, or padded FBO left a rectangle
        // of 3D world and an empty frame around it, so trees/buildings looked
        // like they had been clipped off.
        const Rectangle dest {0.0f, 0.0f, static_cast<float>(sw), static_cast<float>(sh)};

        if (hasGrade) {
            BeginShaderMode(gradeShader);
            const float hourVal = renderHour;
            if (hourLoc >= 0) SetShaderValue(gradeShader, hourLoc, &hourVal, SHADER_UNIFORM_FLOAT);
            const float strength = 0.58f;
            if (strengthLoc >= 0) SetShaderValue(gradeShader, strengthLoc, &strength, SHADER_UNIFORM_FLOAT);
            if (sunUvLoc >= 0) SetShaderValue(gradeShader, sunUvLoc, sunUV, SHADER_UNIFORM_VEC2);
            if (shineLoc >= 0) SetShaderValue(gradeShader, shineLoc, &shine, SHADER_UNIFORM_FLOAT);
            const float warp = std::max(0.0f, std::min(1.0f, realityWarp));
            if (warpLoc >= 0) SetShaderValue(gradeShader, warpLoc, &warp, SHADER_UNIFORM_FLOAT);
            const float tNow = static_cast<float>(GetTime());
            if (timeLoc >= 0) SetShaderValue(gradeShader, timeLoc, &tNow, SHADER_UNIFORM_FLOAT);
            DrawTexturePro(sceneTarget.texture, src, dest, {0.0f, 0.0f}, 0.0f, WHITE);
            EndShaderMode();
        } else {
            DrawTexturePro(sceneTarget.texture, src, dest, {0.0f, 0.0f}, 0.0f, WHITE);
        }
    }

    bool capturing() const { return hasTarget && capturingFrame; }

    void drawClockHud(int sw, int sh) const {
        (void)sh;
        const std::string clock = formatClock12();
        const char* period = periodName();
        const int fs = 22;
        const int ps = 14;
        const int cw = MeasureText(clock.c_str(), fs);
        const int pw = MeasureText(period, ps);
        const int boxW = std::max(cw, pw) + 28;
        const int boxH = 54;
        const int x = (sw - boxW) / 2;
        const int y = 10;
        DrawRectangle(x, y, boxW, boxH, ::Color {10, 12, 18, 175});
        DrawRectangleLines(x, y, boxW, boxH, ::Color {255, 200, 120, 120});
        DrawText(clock.c_str(), x + (boxW - cw) / 2, y + 6, fs, ::Color {255, 230, 190, 255});
        DrawText(period, x + (boxW - pw) / 2, y + 32, ps, ::Color {180, 200, 220, 230});
    }

private:
    static float wrap24(float h) {
        while (h < 0.0f) h += 24.0f;
        while (h >= 24.0f) h -= 24.0f;
        return h;
    }

    void ensureTarget(int sw, int sh) {
        if (sw < 16 || sh < 16) return;
        if (hasTarget && targetW == sw && targetH == sh) return;
        if (hasTarget) {
            UnloadRenderTexture(sceneTarget);
            hasTarget = false;
        }
        sceneTarget = LoadRenderTexture(sw, sh);
        hasTarget = sceneTarget.id > 0;
        targetW = sw;
        targetH = sh;
    }

    float hour {8.0f};
    Shader gradeShader {};
    bool hasGrade {false};
    int hourLoc {-1};
    int strengthLoc {-1};
    int sunUvLoc {-1};
    int shineLoc {-1};
    int warpLoc {-1};
    int timeLoc {-1};
    RenderTexture2D sceneTarget {};
    bool hasTarget {false};
    bool capturingFrame {false};
    int targetW {0};
    int targetH {0};
};

class RealisticGraphics {
public:
    struct Particle {
        Vec3 position;
        Vec3 velocity;
        float lifetime {0.0f};
        float maxLifetime {2.0f};
        ::Color color;
    };
    
    std::vector<Particle> particles;
    
    void emitParticles(const Vec3& pos, int count, ::Color col) {
        for (int i = 0; i < count; ++i) {
            Vec3 vel {
                (GetRandomValue(-100, 100) / 100.0f) * 0.5f,
                (GetRandomValue(50, 150) / 100.0f) * 0.8f,
                (GetRandomValue(-100, 100) / 100.0f) * 0.5f
            };
            particles.push_back({{pos.x, pos.y, pos.z}, vel, 0.0f, 2.0f, col});
        }
    }
    
    void updateParticles(float dt) {
        for (auto it = particles.begin(); it != particles.end(); ) {
            it->lifetime += dt;
            it->position += it->velocity * dt;
            it->velocity.y -= 9.81f * dt;  // Gravity
            
            if (it->lifetime >= it->maxLifetime) {
                it = particles.erase(it);
            } else {
                ++it;
            }
        }
    }
    
    void drawParticles() {
        for (const auto& p : particles) {
            float alpha = 1.0f - (p.lifetime / p.maxLifetime);
            ::Color col = p.color;
            col.a = static_cast<unsigned char>(col.a * alpha);
            
            DrawCube({p.position.x, p.position.y, p.position.z}, 0.15f, 0.15f, 0.15f, col);
        }
    }
    
    void applyClarityEnhancement(float clarity, int sw, int sh) {
        // Used to paint a full-screen grey rectangle three times and call it a
        // vignette — `size` was never used. That wash made trees and buildings
        // look like they were fading out. Consensus reality does not get a
        // colour-filter quad.
        (void)clarity;
        (void)sw;
        (void)sh;
    }
};

class RealityShiftManager {
public:
    enum class Reality { Consensus, Fractured };
    
    Reality currentReality {Reality::Consensus};
    float shiftProgress {0.0f};
    float filterIntensity {1.0f};  // 1.0 = fully filtered (normal), 0.0 = no filter (fractured)
    float timeInShift {0.0f};
    bool isShifting {false};
    
    // Consensus vs Hidden reality
    float consciousnessFragmentation {0.0f};
    float perceptualVeil {1.0f};  // How much we're filtering reality
    
    struct HiddenTruth {
        Vec3 position;
        std::string label;
        bool visibleNormally {false};
        ::Color normalColor;
        ::Color revealedColor;
    };
    
    struct HiddenEntity {
        Vec3 position;
        float scale;
        ::Color color;
        std::string nature;  // What this really is
    };
    
    std::vector<HiddenTruth> hiddenTruths;
    std::vector<HiddenEntity> hiddenLayer;
    std::vector<HolographicPillar> gnosticPillars;
    Vec3 pillarOrigin {0, 0, 0};  // Where pillars are centered
    TexturePackManager texturePacks;
    InstitutionalCollapseSystem collapseSystem;
    
    RealityShiftManager() {
        // Hidden truths that exist but are normally filtered
        hiddenTruths.push_back({{-50, 5, 30}, "Ancient Structure", false, {100, 100, 100, 255}, {200, 100, 255, 255}});
        hiddenTruths.push_back({{60, 3, -40}, "Residual Signal", false, {80, 80, 80, 255}, {255, 50, 150, 255}});
        hiddenTruths.push_back({{-30, 2, -60}, "Consciousness Node", false, {90, 90, 90, 255}, {100, 255, 200, 255}});
        hiddenTruths.push_back({{80, 4, 50}, "Observer Point", false, {70, 70, 70, 255}, {255, 200, 100, 255}});
        
        // The hidden layer - always present but invisible
        hiddenLayer.push_back({{-50, 5, 30}, 2.0f, {200, 100, 255, 200}, "Artificial Beacon"});
        hiddenLayer.push_back({{60, 3, -40}, 1.5f, {255, 50, 150, 200}, "Fractured Anchor"});
        hiddenLayer.push_back({{-30, 2, -60}, 1.8f, {100, 255, 200, 200}, "Silent Witness"});
        hiddenLayer.push_back({{80, 4, 50}, 1.3f, {255, 200, 100, 200}, "Threshold Marker"});
        
        // Pillars will be initialized near player spawn location
    }
    
    /** Trailer / shot-driven fracture. Gold Mine world.shift → veil + warp. */
    void applyShotShift(float s, float dt) {
        s = std::max(0.0f, std::min(1.0f, s));
        shiftProgress = s;
        filterIntensity = 1.0f - s;
        perceptualVeil = 1.0f - s;
        consciousnessFragmentation = s;
        isShifting = s > 0.08f;
        timeInShift += dt;
        currentReality = (s > 0.5f) ? Reality::Fractured : Reality::Consensus;
        if (s > 0.3f) texturePacks.setMultidimensional(true);
        else if (s < 0.1f) texturePacks.setMultidimensional(false);
        collapseSystem.update(dt, s);
    }

    void snapConsensus() {
        isShifting = false;
        shiftProgress = 0.0f;
        filterIntensity = 1.0f;
        perceptualVeil = 1.0f;
        consciousnessFragmentation = 0.0f;
        currentReality = Reality::Consensus;
        texturePacks.setMultidimensional(false);
    }

    void triggerShift() {
        isShifting = !isShifting;
        if (isShifting) {
            std::cout << "Consensus reality fracturing — the Structure's veil thinning...\n";
            std::cout << "The Veil Wardens' filter lifting...\n";
            std::cout << "True knowing: seeing what was always there...\n";
            std::cout << "Entering MULTIDIMENSIONAL (clear-sighted) reality...\n";
            texturePacks.setMultidimensional(true);  // Switch to purple pack
        } else {
            std::cout << "Reality re-filtering... Returning to stonebound consensus...\n";
            std::cout << "The multidimensional perception fading...\n";
            texturePacks.setMultidimensional(false);  // Switch back to green pack
        }
    }
    
    void update(float dt) {
        if (isShifting) {
            shiftProgress = std::min(1.0f, shiftProgress + dt * 0.4f);
            filterIntensity = std::max(0.0f, filterIntensity - dt * 0.4f);
            timeInShift += dt;
            consciousnessFragmentation = std::min(1.0f, consciousnessFragmentation + dt * 0.3f);
            perceptualVeil = std::max(0.0f, perceptualVeil - dt * 0.3f);
        } else {
            // Don't revert immediately - stay in shifted state until manually toggled back
            // This allows the reality to remain fractured permanently
            shiftProgress = std::max(0.0f, shiftProgress - dt * 0.05f);  // Very slow revert rate
            filterIntensity = std::min(1.0f, filterIntensity + dt * 0.05f);  // Very slow return to clarity
            consciousnessFragmentation = std::max(0.0f, consciousnessFragmentation - dt * 0.02f);
            perceptualVeil = std::min(1.0f, perceptualVeil + dt * 0.02f);
        }
        
        // Determine current reality state
        currentReality = (shiftProgress > 0.5f) ? Reality::Fractured : Reality::Consensus;
        
        // Keep texture pack in multidimensional state if shiftProgress is significant
        if (shiftProgress > 0.3f) {
            texturePacks.setMultidimensional(true);
        } else if (shiftProgress < 0.1f) {
            texturePacks.setMultidimensional(false);
        }
        
        // Update institutional collapse based on reality fracture
        collapseSystem.update(dt, 1.0f - filterIntensity);
    }

    /** True knowledge wards the dying material 3D→5D bleed: pull consensus back. */
    void applyKnowledgeWard(float protection, float dt) {
        if (protection <= 0.01f) return;
        const float p = std::min(1.0f, protection);
        filterIntensity = std::min(1.0f, filterIntensity + p * dt * 0.85f);
        shiftProgress = std::max(0.0f, shiftProgress - p * dt * 0.7f);
        consciousnessFragmentation = std::max(0.0f, consciousnessFragmentation - p * dt * 0.55f);
        perceptualVeil = std::min(1.0f, perceptualVeil + p * dt * 0.55f);
        // Institutions lose purchase where knowledge holds
        collapseSystem.update(dt, std::max(0.0f, (1.0f - filterIntensity) * (1.0f - p * 0.9f)));
    }
    
    void drawHiddenLayer() {
        if (filterIntensity > 0.9f) return;  // Too filtered to see
        
        unsigned char alpha = static_cast<unsigned char>(consciousnessFragmentation * 255);  // Increased visibility
        
        for (const auto& entity : hiddenLayer) {
            rlPushMatrix();
            rlTranslatef(entity.position.x, entity.position.y, entity.position.z);
            
            // Pulsing hidden entities
            float pulse = 0.8f + 0.2f * std::sin(timeInShift * 2.0f);
            rlScalef(pulse, pulse, pulse);
            
            // Draw as geometric form
            ::Color displayColor = entity.color;
            displayColor.a = alpha;
            
            // Core sphere
            DrawSphere({0, 0, 0}, entity.scale * 0.3f, displayColor);
            
            // Main geometry
            DrawCube({0, 0, 0}, entity.scale * 0.5f, entity.scale * 1.2f, entity.scale * 0.5f, displayColor);
            
            // Wireframe overlay for "seeing through"
            DrawCubeWires({0, 0, 0}, entity.scale * 0.5f, entity.scale * 1.2f, entity.scale * 0.5f, 
                         ::Color{displayColor.r, displayColor.g, displayColor.b, static_cast<unsigned char>(alpha * 0.9f)});
            
            // Additional octahedron geometry for complexity
            for (int i = 0; i < 3; ++i) {
                float rot = timeInShift * 30.0f * (i + 1);
                rlRotatef(rot, i % 2, (i + 1) % 2, (i + 2) % 2);
            }
            DrawCube({0, entity.scale * 0.4f, 0}, entity.scale * 0.25f, entity.scale * 0.25f, entity.scale * 0.25f,
                    ::Color{displayColor.r, displayColor.g, displayColor.b, static_cast<unsigned char>(alpha * 0.8f)});
            
            rlPopMatrix();
        }
    }
    
    void drawHiddenTruths() {
        if (filterIntensity > 0.85f) return;
        
        for (const auto& truth : hiddenTruths) {
            rlPushMatrix();
            rlTranslatef(truth.position.x, truth.position.y, truth.position.z);
            
            unsigned char alpha = static_cast<unsigned char>(consciousnessFragmentation * 200);  // Increased visibility
            ::Color displayColor = truth.revealedColor;
            displayColor.a = alpha;
            
            // Outer glow sphere
            float glowPulse = 1.0f + 0.3f * std::sin(timeInShift * 3.0f);
            DrawSphere({0, 0, 0}, glowPulse * 1.5f, 
                      ::Color{displayColor.r, displayColor.g, displayColor.b, static_cast<unsigned char>(alpha * 0.4f)});
            
            // Core sphere
            DrawSphere({0, 0, 0}, 1.0f, displayColor);
            
            // Rotating orbital rings for visual depth
            for (int i = 0; i < 3; ++i) {
                rlPushMatrix();
                float rotation = timeInShift * 20.0f * (i + 1);
                if (i == 0) rlRotatef(rotation, 1, 0, 0);
                if (i == 1) rlRotatef(rotation, 0, 1, 0);
                if (i == 2) rlRotatef(rotation, 0, 0, 1);
                
                DrawCubeWires({0, 0, 0}, 2.2f, 2.2f, 2.2f,
                            ::Color{displayColor.r, displayColor.g, displayColor.b, static_cast<unsigned char>(alpha * 0.8f)});
                rlPopMatrix();
            }
            
            // Text label floating above
            DrawText(truth.label.c_str(), -MeasureText(truth.label.c_str(), 12) / 2, -20, 12, 
                    ::Color{displayColor.r, displayColor.g, displayColor.b, alpha});
            
            rlPopMatrix();
        }
    }
    
    void drawGnosticPillars(float clarityMult, EnhancedAfricanTerrain& terrain) {
        for (auto& pillar : gnosticPillars) {
            // Get terrain height at pillar position and draw on ground
            float groundY = terrain.getHeight(pillar.position.x, pillar.position.z);
            Vec3 groundPos = {pillar.position.x, groundY + 0.5f, pillar.position.z};  // Slightly above ground
            pillar.drawAtPosition(clarityMult, groundPos);
        }
    }
    
    void drawInstitutions(float clarityMult, EnhancedAfricanTerrain& terrain) {
        collapseSystem.draw(1.0f - clarityMult);  // Draw based on reality fracture
    }
    
    void updatePillars(float dt) {
        for (auto& pillar : gnosticPillars) {
            pillar.update(dt);
        }
    }
    
    void initializePillarsAtLocation(const Vec3& centerPos) {
        pillarOrigin = centerPos;
        gnosticPillars.clear();
        // Inscribed stones — Inertia lore names only.
        auto add = [&](const Vec3& off, int pillarIdx, ::Color col) {
            const Gnosis::Fragment& f = Gnosis::pillarAt(pillarIdx);
            gnosticPillars.push_back(HolographicPillar(centerPos + off, f.title, col));
        };
        add({0, 0, 0}, 0, {200, 200, 255, 255});
        add({150, 0, 150}, 1, {255, 200, 100, 255});
        add({-150, 0, -150}, 2, {100, 255, 200, 255});
        add({150, 0, -150}, 3, {255, 100, 200, 255});
        add({-150, 0, 150}, 4, {200, 100, 255, 255});
        add({250, 0, 0}, 5, {150, 100, 150, 255});
        add({-250, 0, 0}, 6, {100, 150, 150, 255});
        add({0, 0, 250}, 7, {255, 255, 100, 255});
        add({0, 0, -250}, 8, {100, 255, 255, 255});
        add({80, 0, 80}, 9, {180, 180, 220, 255});
        add({-80, 0, 80}, 10, {255, 100, 100, 255});
        add({80, 0, -80}, 11, {100, 255, 100, 255});
        add({-80, 0, -80}, 12, {255, 200, 200, 255});
        
        hiddenTruths.clear();
        hiddenTruths.push_back({{centerPos.x - 50.0f, 5.0f, centerPos.z + 30.0f}, "Ancient Structure", false, {100, 100, 100, 255}, {200, 100, 255, 255}});
        hiddenTruths.push_back({{centerPos.x + 60.0f, 3.0f, centerPos.z - 40.0f}, "Residual Signal", false, {80, 80, 80, 255}, {255, 50, 150, 255}});
        hiddenTruths.push_back({{centerPos.x - 30.0f, 2.0f, centerPos.z - 60.0f}, "Consciousness Node", false, {90, 90, 90, 255}, {100, 255, 200, 255}});
        hiddenTruths.push_back({{centerPos.x + 80.0f, 4.0f, centerPos.z + 50.0f}, "Observer Point", false, {70, 70, 70, 255}, {255, 200, 100, 255}});
        hiddenLayer.clear();
        hiddenLayer.push_back({centerPos + Vec3(-50, 5, 30), 2.0f, {200, 100, 255, 200}, "Artificial Beacon"});
        hiddenLayer.push_back({centerPos + Vec3(60, 3, -40), 1.5f, {255, 50, 150, 200}, "Fractured Anchor"});
        hiddenLayer.push_back({centerPos + Vec3(-30, 2, -60), 1.8f, {100, 255, 200, 200}, "Silent Witness"});
        hiddenLayer.push_back({centerPos + Vec3(80, 4, 50), 1.3f, {255, 200, 100, 200}, "Threshold Marker"});
        
        // Initialize institutions that will collapse
        initializeInstitutions(centerPos);
    }
    
    void initializeInstitutions(const Vec3& centerPos) {
        collapseSystem.addInstitution(centerPos + Vec3(200, 0, 0), "Tower of Control");
        collapseSystem.addInstitution(centerPos + Vec3(-200, 0, 0), "Fortress of Extraction");
        collapseSystem.addInstitution(centerPos + Vec3(0, 0, 200), "Monument to Force");
        collapseSystem.addInstitution(centerPos + Vec3(0, 0, -200), "Palace of Dominion");
        
        std::cout << "Initialized institutions for collapse\n";
    }
    
    void applyPerceptualFilter(int sw, int sh) {
        if (filterIntensity > 0.85f) return;
        unsigned char filterAlpha = static_cast<unsigned char>((1.0f - filterIntensity) * 255);
        
        if (filterAlpha > 10) {
            // Large reality tear circles - much more prominent
            for (int i = 0; i < 8; ++i) {
                int x = GetRandomValue(0, sw);
                int y = GetRandomValue(0, sh);
                int size = GetRandomValue(80, 250);
                
                // Outer glow
                DrawCircle(x, y, size, Color{200, 100, 255, static_cast<unsigned char>(filterAlpha * 0.2f)});
                // Mid glow
                DrawCircle(x, y, size * 0.6f, Color{255, 150, 200, static_cast<unsigned char>(filterAlpha * 0.35f)});
                // Inner bright
                DrawCircle(x, y, size * 0.3f, Color{150, 200, 255, static_cast<unsigned char>(filterAlpha * 0.5f)});
            }
            
            // Intense veil distortion - shows the fracture strongly
            if (filterIntensity < 0.6f) {
                // Plasma tendrils
                for (int i = 0; i < 15; ++i) {
                    int startX = GetRandomValue(0, sw);
                    int startY = GetRandomValue(0, sh);
                    int endX = startX + GetRandomValue(-150, 150);
                    int endY = startY + GetRandomValue(-150, 150);
                    
                    int lineThickness = GetRandomValue(2, 5);
                    DrawLineEx({static_cast<float>(startX), static_cast<float>(startY)}, 
                              {static_cast<float>(endX), static_cast<float>(endY)}, static_cast<float>(lineThickness),
                              Color{255, 150, 200, static_cast<unsigned char>(filterAlpha * 0.8f)});
                }
                
                // Heavy chromatic aberration
                for (int i = 0; i < 8; ++i) {
                    int px = GetRandomValue(0, sw);
                    int py = GetRandomValue(0, sh);
                    int size = GetRandomValue(30, 80);
                    
                    DrawCircle(px, py, size, Color{255, 100, 100, static_cast<unsigned char>(filterAlpha * 0.5f)});
                    DrawCircle(px + 5, py, size * 0.8f, Color{100, 255, 150, static_cast<unsigned char>(filterAlpha * 0.4f)});
                    DrawCircle(px - 5, py, size * 0.8f, Color{255, 255, 100, static_cast<unsigned char>(filterAlpha * 0.4f)});
                }
            }
            
            // Prominent scan line effect
            for (int y = 0; y < sh; y += 3) {
                DrawRectangle(0, y, sw, 2, Color{100, 50, 150, static_cast<unsigned char>(filterAlpha * 0.3f)});
            }
            
            // Screen tears - stark glitch effect
            if (filterIntensity < 0.5f) {
                for (int i = 0; i < 5; ++i) {
                    int tearX = GetRandomValue(0, sw);
                    int tearHeight = GetRandomValue(10, 100);
                    DrawRectangle(tearX, 0, 4, sh, Color{255, 150, 200, static_cast<unsigned char>(filterAlpha * 0.6f)});
                }
            }
        }
    }
    
    std::string getStatusText() const {
        std::string status = "Consensus: " + std::to_string(static_cast<int>(filterIntensity * 100)) + "% | ";
        status += "Veiled: " + std::to_string(static_cast<int>(perceptualVeil * 100)) + "% | ";
        status += "Fragments: " + std::to_string(static_cast<int>(consciousnessFragmentation * 100)) + "%";
        
        if (filterIntensity < 0.3f) {
            status += " [VEIL TORN - SEEING HIDDEN LAYER]";
        } else if (filterIntensity > 0.8f) {
            status += " [CONSENSUS CLEAR - FULL CLARITY]";
        }
        return status;
    }
    
    float getClarityMult() const {
        // Returns clarity multiplier for terrain rendering
        // 1.0 = fully clear consensus, 0.0 = fully fractured
        return filterIntensity;
    }
    
    const TexturePack& getCurrentTexturePack() const {
        return texturePacks.current();
    }

    void cycleTexturePack() {
        texturePacks.cycleManual();
    }

    /** Trailer-driven palette: 0 auto, 1 Shadow Mirror, 2 Past Incarnation. */
    void applyTrailerPalette(int overrideIdx) {
        texturePacks.setManualOverride(overrideIdx);
    }
};

// ============================================================
// THE DEVOURER — vast segmented cosmic serpent flying the sky.
// Exact port of basics_3D/Gold Mine/devourer.ts (path, N, bulk, head).
// It is the shape of the Concussion: faint far worm at seed, then
// lengthens / brightens / fills the sky as evolution climbs.
// ============================================================
class DevourerSystem {
public:
    // evolution 0..1 — drives length, bulk and presence.
    // dim 1..0 — Althea's unmaking; the whole creature dissolves toward 0.
    void draw(float time, const Vector3& center, float evolution, float dim = 1.0f,
              float worldScale = 1.0f, float rx = 52.0f, float rz = 44.0f,
              float y1 = 11.0f, float y2 = 7.0f) const {
        const float e = std::max(0.0f, std::min(1.0f, evolution));
        const float opacity = (0.14f + 0.86f * e) * std::max(0.0f, std::min(1.0f, dim));
        if (opacity < 0.02f) return;

        // devourer.ts: N = round(10 + e * 46) — capped for FPS (still reads as a long serpent)
        const int n = 8 + static_cast<int>(std::round(e * 22.0f));
        const float speed = 0.16f;
        const float gap = 0.11f;
        const float uHead = time * speed;
        const float pulse = 0.7f + 0.3f * std::sin(time * 2.2f);
        const float s = std::max(0.5f, worldScale);

        const ::Color armor {10, 10, 20, 255};       // #0a0a14
        const ::Color spikeCol {20, 20, 38, 255};    // #141426
        const ::Color seam {47, 230, 255, 255};      // #2fe6ff
        const ::Color core {255, 54, 200, 255};      // #ff36c8
        const float aArmor = std::min(1.0f, opacity + 0.10f);

        // ── solid pass: armour shells, spikes, skull ──
        for (int i = 0; i < n; ++i) {
            const float u = uHead - (i + 1) * gap;
            const Vector3 p = pathAt(u, center, s, rx, rz, y1, y2);
            const Vector3 pn = pathAt(u + gap, center, s, rx, rz, y1, y2);
            const Vector3 dir = norm(sub(pn, p));
            const float r = segRadius(i, n, e) * s;

            DrawCylinderEx(sub(p, scale(dir, r * 0.75f)), add(p, scale(dir, r * 0.75f)),
                           r, r * 0.92f, 8, Fade(armor, aArmor));

            Vector3 u1, u2;
            basis(dir, u1, u2);
            // 2 spikes (was 4) — silhouette still spiky without 2× cylinder cost
            for (int k = 0; k < 2; ++k) {
                const float ang = (k / 2.0f) * 2.0f * PI + (i % 2) * (PI / 4.0f);
                const Vector3 out = add(scale(u1, std::cos(ang)), scale(u2, std::sin(ang)));
                DrawCylinderEx(add(p, scale(out, r * 1.05f)), add(p, scale(out, r * 2.35f)),
                               r * 0.28f, 0.02f, 5, Fade(spikeCol, aArmor));
            }
        }

        const Vector3 hp = pathAt(uHead, center, s, rx, rz, y1, y2);
        const Vector3 hn = pathAt(uHead + gap * 0.6f, center, s, rx, rz, y1, y2);
        const Vector3 hdir = norm(sub(hn, hp));
        const float headR = (3.0f + e * 3.5f) * s;
        DrawSphereEx(hp, headR, 12, 10, Fade(armor, aArmor));
        DrawCylinderEx(add(hp, scale({0, 1, 0}, headR * 0.5f)),
                       add(add(hp, scale({0, 1, 0}, headR * 1.4f)), scale(hdir, -headR * 0.2f)),
                       headR * 0.5f, 0.05f, 4, Fade(spikeCol, aArmor));
        Vector3 h1, h2;
        basis(hdir, h1, h2);
        for (int k = 0; k < 4; ++k) {
            const float ang = (k / 4.0f) * 2.0f * PI;
            const Vector3 out = add(scale(h1, std::cos(ang)), scale(h2, std::sin(ang)));
            const Vector3 base = add(add(hp, scale(out, headR * 0.72f)), scale(hdir, headR * 0.95f));
            DrawCylinderEx(base, add(add(base, scale(out, headR * 0.25f)), scale(hdir, headR * 0.9f)),
                           headR * 0.16f, 0.02f, 5, Fade(spikeCol, aArmor));
        }

        // ── additive pass: seam rings, inner fire, eyes and maw ──
        BeginBlendMode(BLEND_ADDITIVE);
        // Every other segment for seams — still reads as glowing rings
        for (int i = 0; i < n; i += 2) {
            const float u = uHead - (i + 1) * gap;
            const Vector3 p = pathAt(u, center, s, rx, rz, y1, y2);
            const Vector3 pn = pathAt(u + gap, center, s, rx, rz, y1, y2);
            const Vector3 dir = norm(sub(pn, p));
            const float r = segRadius(i, n, e) * s;

            Vector3 axis;
            float angle;
            faceAxisAngle(dir, axis, angle);
            DrawCircle3D(p, r * 1.02f, axis, angle, Fade(seam, opacity * pulse));
            DrawSphereEx(p, r * 0.5f, 8, 8, Fade(core, opacity * 0.85f * pulse));
        }
        DrawSphereEx(add(hp, scale(hdir, headR * 0.7f)), headR * 0.55f, 8, 8,
                     Fade(core, opacity * 0.85f * pulse));
        for (const float sx : {-1.0f, 1.0f}) {
            const Vector3 eye = add(add(hp, scale(h1, sx * headR * 0.5f)),
                                    add(scale(h2, headR * 0.28f), scale(hdir, headR * 0.72f)));
            DrawSphereEx(eye, headR * 0.22f, 6, 6, Fade(seam, opacity * pulse));
        }
        EndBlendMode();
    }

    /** Sky serpent over the scene — same fixed-orbit idea as devourer.ts.
     *  Do NOT lock the path to the look vector: that teleported the whole body
     *  every time the camera yawed/pitched (sky glitch streaks). */
    void drawSkySerpent(float time, const Camera3D& camera, float evolution, float dim = 1.0f) const {
        const float e = std::max(0.0f, std::min(1.0f, evolution));

        // Horizontal look only — pitch must not yank the orbit into the ground or zenith.
        Vector3 fwd {
            camera.target.x - camera.position.x,
            0.0f,
            camera.target.z - camera.position.z
        };
        fwd = norm(fwd);

        // devourer.ts flies a loop over a fixed world centre (~Y 50 on a 128 map).
        // Here: hang above the focus point, nudged ahead so it sits in open sky.
        const float hang = 70.0f + e * 35.0f;
        const float skyY = 55.0f + e * 25.0f;
        Vector3 desired {
            camera.target.x + fwd.x * hang,
            camera.target.y + skyY,
            camera.target.z + fwd.z * hang
        };

        // Soft follow kills hard snaps on trailer cuts / orbit camera.
        if (!skyCenterInit) {
            skyCenter = desired;
            skyCenterInit = true;
        } else {
            constexpr float kFollow = 0.045f;
            skyCenter.x += (desired.x - skyCenter.x) * kFollow;
            skyCenter.y += (desired.y - skyCenter.y) * kFollow;
            skyCenter.z += (desired.z - skyCenter.z) * kFollow;
        }

        // Near Gold Mine bulk — old 3.6–7.8× scale made path radii hundreds of metres
        // and every tiny center drift read as a sky teleport.
        const float skyScale = 1.15f + e * 1.35f;
        draw(time, skyCenter, e, dim, skyScale);
    }

    // devourer.ts brought down to fight range: same armour / cyan seams /
    // magenta fire, orbiting the player instead of the high sky loop.
    static constexpr float kArenaScale = 0.82f;
    static constexpr float kArenaRx = 22.0f;
    static constexpr float kArenaRz = 18.0f;
    static constexpr float kArenaY1 = 4.0f;
    static constexpr float kArenaY2 = 2.2f;

    Vector3 arenaCenter(const Vector3& ground) const {
        return {ground.x, ground.y + 11.0f, ground.z};
    }

    Vector3 arenaHead(float time, const Vector3& ground) const {
        return pathAt(time * 0.16f, arenaCenter(ground), kArenaScale,
                      kArenaRx, kArenaRz, kArenaY1, kArenaY2);
    }

    void drawArenaBoss(float time, const Vector3& ground, float evolution, float dim = 1.0f) const {
        draw(time, arenaCenter(ground), evolution, dim, kArenaScale,
             kArenaRx, kArenaRz, kArenaY1, kArenaY2);
    }

private:
    mutable Vector3 skyCenter {0.0f, 0.0f, 0.0f};
    mutable bool skyCenterInit {false};
    static Vector3 add(const Vector3& a, const Vector3& b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
    static Vector3 sub(const Vector3& a, const Vector3& b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
    static Vector3 scale(const Vector3& a, float s) { return {a.x * s, a.y * s, a.z * s}; }
    static Vector3 cross(const Vector3& a, const Vector3& b) {
        return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x};
    }
    static Vector3 norm(const Vector3& a) {
        const float l = std::sqrt(a.x * a.x + a.y * a.y + a.z * a.z);
        return (l > 0.0001f) ? scale(a, 1.0f / l) : Vector3 {0.0f, 0.0f, 1.0f};
    }

    static void basis(const Vector3& dir, Vector3& u1, Vector3& u2) {
        const Vector3 ref = (std::fabs(dir.y) < 0.92f) ? Vector3 {0.0f, 1.0f, 0.0f}
                                                       : Vector3 {1.0f, 0.0f, 0.0f};
        u1 = norm(cross(dir, ref));
        u2 = cross(dir, u1);
    }

    static void faceAxisAngle(const Vector3& dir, Vector3& axis, float& angleDeg) {
        const Vector3 z {0.0f, 0.0f, 1.0f};
        const Vector3 c = cross(z, dir);
        const float cl = std::sqrt(c.x * c.x + c.y * c.y + c.z * c.z);
        if (cl < 0.0001f) {
            axis = {1.0f, 0.0f, 0.0f};
            angleDeg = (dir.z >= 0.0f) ? 0.0f : 180.0f;
            return;
        }
        axis = scale(c, 1.0f / cl);
        const float d = std::max(-1.0f, std::min(1.0f, dir.z));
        angleDeg = std::acos(d) * RAD2DEG;
    }

    // devourer.ts pathAt — RX=52, RZ=44, Y≈50. worldScale only gently enlarges
    // the loop (was 1.8×scale, which turned mild center drift into sky glitches).
    static Vector3 pathAt(float u, const Vector3& c, float worldScale,
                          float rx = 52.0f, float rz = 44.0f,
                          float y1 = 11.0f, float y2 = 7.0f) {
        const float k = std::max(0.75f, worldScale);
        return {c.x + std::cos(u) * rx * k,
                c.y + std::sin(u * 1.7f) * y1 * k + std::sin(u * 0.5f) * y2 * k,
                c.z + std::sin(u) * rz * k};
    }

    // devourer.ts: taper = 1 - (i/N)^1.7 * 0.7; bulk = 2.6 + e * 3.2
    static float segRadius(int i, int n, float e) {
        const float taper = 1.0f - std::pow(static_cast<float>(i) / std::max(1, n), 1.7f) * 0.7f;
        const float bulk = 2.6f + e * 3.2f;
        return bulk * taper;
    }
};

// ============================================================
// ALTHEA AURA — wind ribbons, orbiting motes and ground
// shockwaves around the player when the Windspeaker is the
// chosen vessel. Port of althea.ts from the Gold Mine build.
// ============================================================
class AltheaAuraFX {
public:
    void draw(const Vec3& pp, float time, float heal = -1.0f) const {
        const float h = (heal < 0.0f) ? (0.55f + 0.20f * std::sin(time * 0.5f))
                                      : std::max(0.0f, std::min(1.0f, heal));
        const float breath = 0.7f + 0.3f * std::sin(time * 1.6f);
        const float glow = (0.35f + 0.65f * h) * breath;

        const ::Color wind {143, 230, 255, 255};   // #8fe6ff
        const ::Color healCol {123, 255, 207, 255}; // #7bffcf
        const Vector3 c {pp.x, pp.y + 1.2f, pp.z};

        BeginBlendMode(BLEND_ADDITIVE);

        // ── wind ribbons: four tilted circles spinning around her ──
        for (int i = 0; i < 4; ++i) {
            const float rad = 1.0f + i * 0.32f;
            const float tilt = (i - 1.5f) * 0.4f;
            const float spin = time * (0.5f + 0.8f * h) + i * 0.7f;
            drawTiltedRing(c, rad, tilt, spin, Fade(wind, 0.4f * glow));
        }

        // ── orbiting light motes ──
        for (int i = 0; i < 10; ++i) {
            const float a = time * (0.6f + (i % 3) * 0.25f) + (i / 10.0f) * 2.0f * PI;
            const float r = 0.7f + 0.25f * std::sin(time * 0.9f + i);
            const Vector3 m {c.x + std::cos(a) * r,
                             pp.y + 1.4f + std::sin(time * 1.1f + i * 1.7f) * 0.45f,
                             c.z + std::sin(a) * r};
            DrawSphereEx(m, 0.05f, 6, 6, Fade(healCol, 0.85f * glow));
        }

        // ── ground shockwaves: expanding rings that unmake illusions ──
        const auto sweep = [&](float phase) {
            const float period = 3.2f;
            const float ph = std::fmod(time / period + phase, 1.0f);
            const float rad = 1.2f + ph * 14.0f;
            const float a = h * (1.0f - ph) * (1.0f - ph) * 0.9f;
            const Vector3 g {pp.x, pp.y + 0.12f, pp.z};
            DrawCircle3D(g, rad, {1.0f, 0.0f, 0.0f}, 90.0f, Fade(healCol, a));
            DrawCircle3D(g, rad * 0.97f, {1.0f, 0.0f, 0.0f}, 90.0f, Fade(healCol, a * 0.6f));
        };
        sweep(0.0f);
        sweep(0.5f);

        EndBlendMode();
    }

    /** Circle of line segments in the plane tilted around X then spun around Y. */
    static void drawTiltedRing(const Vector3& c, float rad, float tilt, float spin, ::Color col) {
        constexpr int kSegs = 36;
        Vector3 prev {};
        for (int s = 0; s <= kSegs; ++s) {
            const float a = (static_cast<float>(s) / kSegs) * 2.0f * PI;
            // point on unit circle in XZ, tilted around X, spun around Y
            float x = std::cos(a) * rad;
            float y = std::sin(a) * rad * std::sin(tilt);
            float z = std::sin(a) * rad * std::cos(tilt);
            const float xs = x * std::cos(spin) + z * std::sin(spin);
            const float zs = -x * std::sin(spin) + z * std::cos(spin);
            const Vector3 pt {c.x + xs, c.y + y, c.z + zs};
            if (s > 0) DrawLine3D(prev, pt, col);
            prev = pt;
        }
    }
};

// ============================================================
// RPG LEVEL SYSTEM — Terraria-RPG-mod style progression.
// XP from digging, gathering, exploring and discovering places.
// Levels grant stat points, spent in the L panel on four stats
// that feed real mechanics: STRENGTH (dig yield), AGILITY (move
// speed), SPIRIT (double gathering), KNOWLEDGE (power cooldowns).
// ============================================================
class RpgLevelSystem {
public:
    static constexpr int kStatMax = 20;

    // ── XP / levels ──
    int xpToNext() const {
        const int n = level - 1;
        return 70 + n * 40 + n * n * 10;
    }

    void gainXP(int amount) {
        if (amount <= 0) return;
        xp += amount;
        popupXP += amount;
        popupTimer = 2.2f;
        while (xp >= xpToNext()) {
            xp -= xpToNext();
            ++level;
            statPoints += 3;
            levelFlash = 3.4f;
        }
    }

    void addWalkDistance(float metres) {
        walkAccum += metres;
        while (walkAccum >= 15.0f) {  // explorer XP: 1 per 15 m travelled
            walkAccum -= 15.0f;
            gainXP(1);
        }
    }

    /** One-time discovery XP for the landmark sites. */
    void checkDiscovery(const Vec3& p, float villageX, float villageZ,
                        float pyramidX, float pyramidZ) {
        if (!foundVillage) {
            const float dx = p.x - villageX, dz = p.z - villageZ;
            if (dx * dx + dz * dz < 70.0f * 70.0f) {
                foundVillage = true;
                gainXP(150);
                setNote("DISCOVERED: THE GREAT STONE VILLAGE  (+150 XP)");
            }
        }
        if (!foundPyramids) {
            const float dx = p.x - pyramidX, dz = p.z - pyramidZ;
            if (dx * dx + dz * dz < 220.0f * 220.0f) {
                foundPyramids = true;
                gainXP(200);
                setNote("DISCOVERED: THE AFTERLIFE PYRAMIDS  (+200 XP)");
            }
        }
    }

    // ── Stat effects (all fed into real mechanics) ──
    float speedMult() const { return 1.0f + static_cast<float>(stat[1]) * 0.04f; }
    float cooldownScale() const { return std::max(0.40f, 1.0f - static_cast<float>(stat[3]) * 0.03f); }
    /** Speak Softly, per her character card: 130% of a 20-point base blow,
     *  scaled by STRENGTH. 26 at level one, so a 300 HP wyvern is twelve
     *  clean hits. */
    float gustDamage() const {
        return 20.0f * 1.30f * (1.0f + static_cast<float>(stat[0]) * 0.06f);
    }
    /** Fireball — the multidimensional-mage answer. Heavier than the gust,
     *  priced with the longer reach and its own cooldown. */
    float fireballDamage() const {
        return 45.0f * (1.0f + static_cast<float>(stat[0]) * 0.06f);
    }
    /** Angela's axe. Heavier per blow than the gust but slower and inside
     *  4.5m, so a 300 HP wyvern is nine swings you have to survive standing
     *  underneath it. */
    float axeDamage() const {
        return 34.0f * (1.0f + static_cast<float>(stat[0]) * 0.06f);
    }
    /** The club. Her only answer to something on the wing, priced accordingly. */
    float clubDamage() const {
        return 22.0f * (1.0f + static_cast<float>(stat[0]) * 0.06f);
    }
    // Read-only views for the global profile / unlock challenges.
    int levelValue() const { return level; }
    int xpValue() const { return xp; }
    bool sawVillage() const { return foundVillage; }
    bool sawPyramids() const { return foundPyramids; }

    int bonusSoil(int baseSoil) const { return (baseSoil * stat[0] * 8) / 100; }
    bool rollDoubleGather() const {
        const int chance = std::min(95, stat[2] * 8);
        return chance > 0 && GetRandomValue(0, 99) < chance;
    }

    // ── Panel state / input ──
    bool isPanelOpen() const { return panelOpen; }
    void togglePanel() { panelOpen = !panelOpen; }
    void closePanel() { panelOpen = false; }

    void handleAllocationInput() {
        if (!panelOpen || statPoints <= 0) return;
        for (int i = 0; i < 4; ++i) {
            if ((IsKeyPressed(KEY_ONE + i) || IsKeyPressed(KEY_KP_1 + i))
                && stat[i] < kStatMax) {
                ++stat[i];
                --statPoints;
                setNote(nullptr);  // stat line itself shows the change
            }
        }
    }

    void update(float dt) {
        if (levelFlash > 0.0f) levelFlash = std::max(0.0f, levelFlash - dt);
        if (popupTimer > 0.0f) {
            popupTimer -= dt;
            if (popupTimer <= 0.0f) popupXP = 0;
        }
        if (noteTimer > 0.0f) noteTimer = std::max(0.0f, noteTimer - dt);
    }

    // ── HUD: thin XP bar above the hotbar + level-up banner ──
    void drawHud(int sw, int sh) const {
        const int barW = 420;
        const int barH = 7;
        const int bx = (sw - barW) / 2;
        const int by = sh - 110;
        const float frac = std::max(0.0f, std::min(1.0f,
            static_cast<float>(xp) / static_cast<float>(xpToNext())));
        DrawRectangle(bx - 1, by - 1, barW + 2, barH + 2, ::Color {0, 0, 0, 150});
        DrawRectangle(bx, by, barW, barH, ::Color {40, 44, 34, 200});
        DrawRectangle(bx, by, static_cast<int>(barW * frac), barH, ::Color {148, 216, 96, 230});
        char lv[48];
        std::snprintf(lv, sizeof(lv), "LV %d", level);
        DrawText(lv, bx - MeasureText(lv, 16) - 10, by - 5, 16, ::Color {228, 232, 200, 230});
        if (statPoints > 0) {
            char pts[64];
            std::snprintf(pts, sizeof(pts), "+%d POINTS — PRESS L", statPoints);
            const unsigned char a = static_cast<unsigned char>(
                170 + 85 * std::sin(GetTime() * 4.0));
            DrawText(pts, bx + barW + 10, by - 5, 16, ::Color {255, 220, 80, a});
        }
        if (popupTimer > 0.0f && popupXP > 0) {
            char pp[32];
            std::snprintf(pp, sizeof(pp), "+%d XP", popupXP);
            const unsigned char a = static_cast<unsigned char>(
                255.0f * std::min(1.0f, popupTimer / 0.4f));
            DrawText(pp, bx + barW / 2 - MeasureText(pp, 15) / 2, by - 22, 15,
                     ::Color {188, 236, 148, a});
        }
        if (levelFlash > 0.0f) {
            const float u = std::min(1.0f, levelFlash / 0.6f);
            char msg[64];
            std::snprintf(msg, sizeof(msg), "LEVEL UP — LEVEL %d", level);
            const int fs = 42;
            DrawText(msg, (sw - MeasureText(msg, fs)) / 2, sh / 4,
                     fs, ::Color {255, 220, 80, static_cast<unsigned char>(255.0f * u)});
            const char* sub = "+3 STAT POINTS — PRESS L TO SPEND";
            DrawText(sub, (sw - MeasureText(sub, 18)) / 2, sh / 4 + 50,
                     18, ::Color {228, 232, 200, static_cast<unsigned char>(220.0f * u)});
        }
        if (noteTimer > 0.0f && note[0] != '\0') {
            const unsigned char a = static_cast<unsigned char>(
                255.0f * std::min(1.0f, noteTimer / 0.4f));
            DrawText(note, (sw - MeasureText(note, 20)) / 2, sh / 4 + 92, 20,
                     ::Color {148, 216, 255, a});
        }
    }

    struct PathSheet {
        int level {1};
        int xp {0};
        int xpNeed {100};
        int stat[4] {0, 0, 0, 0};
        int statPoints {0};
        int tier {0};
        const char* dimension {""};
        const char* concussion {nullptr};
        const char* hint {""};
        bool spendKeys {false};
        bool dockLeft {false};
        float alpha {1.0f};
        float levelUp {0.0f};
    };

    struct ProgRung {
        const char* name;
        const char* band;
        ::Color color;
    };
    static constexpr ProgRung kProgLadder[7] = {
        {"The Seed World",      "Pre-Awakening",    {212, 137,  26, 255}},
        {"The Growing",         "Early Bloom",      {123, 191,  90, 255}},
        {"The Hardened Ground", "Mid Ascent",       {185, 160, 106, 255}},
        {"The First Tear",      "Rift Threshold",   {  0, 255, 180, 255}},
        {"The Reversal",        "Shadow Ascendant", {160,  96, 255, 255}},
        {"The Waking",          "Post-Human",       { 90, 224, 208, 255}},
        {"The Inertia",         "Endgame",          {255,  64,  96, 255}},
    };

    int tierFromLevel() const {
        if (level <= 2) return 0;
        if (level <= 4) return 1;
        if (level <= 7) return 2;
        if (level <= 9) return 3;
        if (level <= 11) return 4;
        if (level <= 13) return 5;
        return 6;
    }

    // Shared character-sheet GUI (trailer + L key). Inventory-grade chrome:
    // title bar, inset sections, rung rows, stat cards.
    static void drawPathSheet(const Font& serif, const Font& mono, int sw, int sh,
                              const PathSheet& s, bool modal) {
        const float a = std::max(0.0f, std::min(1.0f, s.alpha));
        if (a < 0.02f) return;
        const float ui = std::max(0.65f, std::min(static_cast<float>(sh) / 900.0f, 1.5f));
        const Font& nameF = (serif.texture.id > 0) ? serif : GetFontDefault();
        const Font& metaF = (mono.texture.id > 0) ? mono : GetFontDefault();
        const ::Color cream {245, 230, 200, 255};
        const ::Color amber {212, 137, 26, 255};
        const ::Color brown {138, 115, 85, 255};
        const ::Color green {148, 216, 96, 255};
        const ::Color panel {16, 12, 9, 255};

        if (modal) DrawRectangle(0, 0, sw, sh, Fade(::Color {6, 4, 3, 190}, a));

        float pw = (modal ? 560.0f : 408.0f) * ui;
        float ph = 740.0f * ui;
        const float bottomReserve = s.dockLeft ? 188.0f * ui : 24.0f * ui;
        const float topReserve = s.dockLeft ? 78.0f * ui : 24.0f * ui;
        if (ph > static_cast<float>(sh) - topReserve - bottomReserve) {
            ph = static_cast<float>(sh) - topReserve - bottomReserve;
        }
        const float px = s.dockLeft ? 22.0f * ui : (static_cast<float>(sw) - pw) * 0.5f;
        const float py = s.dockLeft ? topReserve : (static_cast<float>(sh) - ph) * 0.5f;
        const Rectangle win {px, py, pw, ph};

        DrawRectangleRec(win, Fade(panel, a));
        DrawRectangleLinesEx(win, 1.5f * ui, Fade(amber, 0.55f * a));
        DrawRectangle(static_cast<int>(px), static_cast<int>(py),
                      static_cast<int>(pw), static_cast<int>(3.0f * ui), Fade(amber, a));

        const float pad = 18.0f * ui;
        DrawTextEx(metaF, "VESSEL PATH", {px + pad, py + 10.0f * ui},
                   10.0f * ui, 1.5f * ui, Fade(brown, 0.95f * a));
        DrawTextEx(nameF, "WINDSPEAKER'S PATH", {px + pad, py + 24.0f * ui},
                   22.0f * ui, 1.0f * ui, Fade(cream, a));
        if (s.dimension != nullptr && s.dimension[0] != '\0') {
            DrawTextEx(metaF, s.dimension, {px + pad, py + 50.0f * ui},
                       11.0f * ui, 1.5f * ui, Fade(amber, a));
        }

        const Rectangle badge {px + pw - pad - 78.0f * ui, py + 14.0f * ui, 78.0f * ui, 40.0f * ui};
        DrawRectangleRec(badge, Fade(::Color {28, 22, 16, 255}, a));
        DrawRectangleLinesEx(badge, 1.0f * ui, Fade(green, a));
        DrawTextEx(metaF, "LEVEL", {badge.x + 8.0f * ui, badge.y + 4.0f * ui},
                   9.0f * ui, 1.5f * ui, Fade(green, a));
        char lv[16];
        std::snprintf(lv, sizeof(lv), "%d", s.level);
        const Vector2 lvw = MeasureTextEx(nameF, lv, 20.0f * ui, 1.0f);
        DrawTextEx(nameF, lv,
                   {badge.x + (badge.width - lvw.x) * 0.5f, badge.y + 16.0f * ui},
                   20.0f * ui, 1.0f, Fade(cream, a));

        float y = py + 72.0f * ui;
        const float innerW = pw - pad * 2.0f;
        DrawRectangle(static_cast<int>(px + pad), static_cast<int>(y),
                      static_cast<int>(innerW), static_cast<int>(1.0f * ui), Fade(amber, 0.25f * a));
        y += 12.0f * ui;

        DrawTextEx(metaF, "EXPERIENCE", {px + pad, y}, 9.0f * ui, 2.0f, Fade(brown, a));
        y += 16.0f * ui;
        const float barH = 12.0f * ui;
        const float frac = std::max(0.0f, std::min(1.0f,
            (s.xpNeed > 0) ? static_cast<float>(s.xp) / static_cast<float>(s.xpNeed) : 0.0f));
        DrawRectangle(static_cast<int>(px + pad), static_cast<int>(y),
                      static_cast<int>(innerW), static_cast<int>(barH), Fade(::Color {40, 32, 24, 255}, a));
        DrawRectangle(static_cast<int>(px + pad), static_cast<int>(y),
                      static_cast<int>(innerW * frac), static_cast<int>(barH), Fade(green, a));
        DrawRectangleLinesEx({px + pad, y, innerW, barH}, 1.0f, Fade(amber, 0.35f * a));
        y += barH + 6.0f * ui;
        char xpTxt[48];
        std::snprintf(xpTxt, sizeof(xpTxt), "%d  /  %d XP", s.xp, s.xpNeed);
        const Vector2 xpw = MeasureTextEx(metaF, xpTxt, 12.0f * ui, 1.0f);
        DrawTextEx(metaF, xpTxt, {px + pad + (innerW - xpw.x) * 0.5f, y},
                   12.0f * ui, 1.0f, Fade(cream, 0.85f * a));
        y += 22.0f * ui;

        DrawTextEx(metaF, "THE ARGUMENT", {px + pad, y}, 9.0f * ui, 2.0f, Fade(brown, a));
        y += 16.0f * ui;
        const float rowH = 28.0f * ui;
        const int tier = std::max(0, std::min(6, s.tier));
        for (int i = 0; i < 7; ++i) {
            const bool done = i < tier;
            const bool here = i == tier;
            const Rectangle row {px + pad, y, innerW, rowH - 3.0f * ui};
            DrawRectangleRec(row, Fade(here ? ::Color {36, 28, 18, 255}
                                            : ::Color {22, 18, 14, 255}, a));
            if (here) DrawRectangleLinesEx(row, 1.0f, Fade(kProgLadder[i].color, 0.85f * a));
            DrawRectangle(static_cast<int>(row.x), static_cast<int>(row.y),
                          static_cast<int>(4.0f * ui), static_cast<int>(row.height),
                          Fade(kProgLadder[i].color, (here || done) ? a : 0.25f * a));
            const ::Color nameCol = here ? cream
                : (done ? Fade(kProgLadder[i].color, 0.9f) : ::Color {110, 100, 88, 255});
            DrawTextEx(nameF, kProgLadder[i].name, {row.x + 14.0f * ui, row.y + 4.0f * ui},
                       13.0f * ui, 1.0f, Fade(nameCol, a));
            const Vector2 bw = MeasureTextEx(metaF, kProgLadder[i].band, 9.0f * ui, 1.0f);
            DrawTextEx(metaF, kProgLadder[i].band,
                       {row.x + row.width - 10.0f * ui - bw.x, row.y + 7.0f * ui},
                       9.0f * ui, 1.0f, Fade(kProgLadder[i].color, (here ? 1.0f : 0.45f) * a));
            y += rowH;
        }

        if (s.concussion != nullptr && s.concussion[0] != '\0') {
            y += 6.0f * ui;
            DrawTextEx(metaF, "CONCUSSION", {px + pad, y}, 9.0f * ui, 2.0f, Fade(brown, a));
            y += 14.0f * ui;
            const Rectangle chip {px + pad, y, innerW, 28.0f * ui};
            DrawRectangleRec(chip, Fade(::Color {28, 18, 14, 255}, a));
            DrawRectangleLinesEx(chip, 1.0f, Fade(kProgLadder[tier].color, 0.7f * a));
            DrawTextEx(nameF, s.concussion, {chip.x + 12.0f * ui, chip.y + 5.0f * ui},
                       15.0f * ui, 1.0f, Fade(cream, a));
            y += 36.0f * ui;
        }

        y += 4.0f * ui;
        DrawTextEx(metaF, "STATS", {px + pad, y}, 9.0f * ui, 2.0f, Fade(brown, a));
        if (s.statPoints > 0) {
            char pts[40];
            std::snprintf(pts, sizeof(pts), "%d POINT%s", s.statPoints, s.statPoints == 1 ? "" : "S");
            const Vector2 pwds = MeasureTextEx(metaF, pts, 11.0f * ui, 1.0f);
            DrawTextEx(metaF, pts, {px + pw - pad - pwds.x, y},
                       11.0f * ui, 1.0f, Fade(::Color {255, 220, 80, 255}, a));
        }
        y += 16.0f * ui;
        static constexpr const char* kStatN[4] = {
            "STRENGTH", "AGILITY", "SPIRIT", "KNOWLEDGE"
        };
        static constexpr const char* kStatE[4] = {
            "+8% soil   +6% gust",
            "+4% move speed",
            "+8% double gather",
            "-3% power cooldowns"
        };
        const float statH = 40.0f * ui;
        for (int i = 0; i < 4; ++i) {
            const Rectangle row {px + pad, y, innerW, statH - 4.0f * ui};
            DrawRectangleRec(row, Fade(::Color {24, 20, 16, 255}, a));
            if (s.spendKeys) {
                char key[8];
                std::snprintf(key, sizeof(key), "%d", i + 1);
                const Rectangle keyBox {row.x + 6.0f * ui, row.y + 8.0f * ui, 22.0f * ui, 20.0f * ui};
                DrawRectangleRec(keyBox, Fade(::Color {40, 32, 22, 255}, a));
                DrawRectangleLinesEx(keyBox, 1.0f, Fade(s.statPoints > 0 ? ::Color {255, 220, 80, 255} : brown, a));
                const Vector2 kw = MeasureTextEx(metaF, key, 12.0f * ui, 1.0f);
                DrawTextEx(metaF, key,
                           {keyBox.x + (keyBox.width - kw.x) * 0.5f, keyBox.y + 3.0f * ui},
                           12.0f * ui, 1.0f, Fade(cream, a));
            }
            const float tx = row.x + (s.spendKeys ? 36.0f * ui : 10.0f * ui);
            DrawTextEx(nameF, kStatN[i], {tx, row.y + 3.0f * ui}, 14.0f * ui, 1.0f, Fade(cream, a));
            DrawTextEx(metaF, kStatE[i], {tx, row.y + 18.0f * ui}, 10.0f * ui, 1.0f, Fade(brown, a));
            char val[16];
            std::snprintf(val, sizeof(val), "%d / 20", s.stat[i]);
            const Vector2 vw = MeasureTextEx(metaF, val, 13.0f * ui, 1.0f);
            DrawTextEx(metaF, val, {row.x + row.width - 10.0f * ui - vw.x, row.y + 4.0f * ui},
                       13.0f * ui, 1.0f, Fade(green, a));
            const float sbx = tx;
            const float sbw = row.x + row.width - 10.0f * ui - sbx;
            const float sby = row.y + row.height - 7.0f * ui;
            DrawRectangle(static_cast<int>(sbx), static_cast<int>(sby),
                          static_cast<int>(sbw), static_cast<int>(3.0f * ui), Fade(::Color {40, 36, 28, 255}, a));
            DrawRectangle(static_cast<int>(sbx), static_cast<int>(sby),
                          static_cast<int>(sbw * s.stat[i] / 20.0f), static_cast<int>(3.0f * ui),
                          Fade(green, a));
            y += statH;
        }

        if (s.hint != nullptr && s.hint[0] != '\0') {
            const Vector2 hw = MeasureTextEx(metaF, s.hint, 10.0f * ui, 1.0f);
            DrawTextEx(metaF, s.hint,
                       {px + (pw - hw.x) * 0.5f, py + ph - 22.0f * ui},
                       10.0f * ui, 1.0f, Fade(brown, 0.9f * a));
        }

        if (s.levelUp > 0.02f) {
            const float fa = a * std::max(0.0f, std::min(1.0f, s.levelUp));
            const char* msg = "LEVEL UP";
            const Vector2 mw = MeasureTextEx(nameF, msg, 36.0f * ui, 1.0f);
            DrawTextEx(nameF, msg, {(sw - mw.x) * 0.5f, sh * 0.18f},
                       36.0f * ui, 1.0f, Fade(::Color {255, 220, 80, 255}, fa));
        }
    }

    // ── The stat panel (L) — same GUI the trailer shows ──
    void drawPanel(int sw, int sh, Font serif, Font mono) const {
        if (!panelOpen) return;
        PathSheet s {};
        s.level = level;
        s.xp = xp;
        s.xpNeed = xpToNext();
        for (int i = 0; i < 4; ++i) s.stat[i] = stat[i];
        s.statPoints = statPoints;
        s.tier = tierFromLevel();
        s.dimension = "THE PATH";
        s.hint = "1-4 SPEND POINT   ·   L / ESC CLOSE";
        s.spendKeys = true;
        s.alpha = 1.0f;
        s.levelUp = (levelFlash > 0.0f) ? std::min(1.0f, levelFlash / 0.6f) : 0.0f;
        drawPathSheet(serif, mono, sw, sh, s, true);
    }

    // Trailer fight overlay: a mid-run Windspeaker sheet so the cut shows
    // that this is an RPG with stats, not just a flyover.
    void drawTrailerProgression(int sw, int sh, float shot01) const {
        const float t = std::max(0.0f, std::min(1.0f, shot01));
        const int levelShow = (t > 0.58f) ? 12 : 11;
        const int xpHave = (t > 0.58f)
            ? static_cast<int>(80.0f + (t - 0.58f) / 0.42f * 420.0f)
            : static_cast<int>(1480.0f + t / 0.58f * 620.0f);
        const int xpNeed = (t > 0.58f) ? 1540 : 2100;
        const int stats[4] = {
            8 + (t > 0.62f ? 1 : 0),
            6,
            7,
            5 + (t > 0.72f ? 1 : 0)
        };
        static constexpr const char* kNames[4] = {
            "STRENGTH", "AGILITY", "SPIRIT", "KNOWLEDGE"
        };

        const int pw = 268;
        const int ph = 228;
        const int px = 28;
        const int py = 92;
        DrawRectangleRounded({static_cast<float>(px), static_cast<float>(py),
                              static_cast<float>(pw), static_cast<float>(ph)},
                             0.06f, 6, ::Color {10, 12, 14, 200});
        DrawRectangleRoundedLinesEx({static_cast<float>(px), static_cast<float>(py),
                                     static_cast<float>(pw), static_cast<float>(ph)},
                                    0.06f, 6, 1.5f, ::Color {148, 216, 96, 170});
        char title[48];
        std::snprintf(title, sizeof(title), "WINDSPEAKER  LV %d", levelShow);
        DrawText(title, px + 14, py + 12, 18, ::Color {228, 232, 200, 255});

        const int barW = pw - 28;
        const int bx = px + 14;
        const int by = py + 38;
        const float frac = std::max(0.0f, std::min(1.0f,
            static_cast<float>(xpHave) / static_cast<float>(xpNeed)));
        DrawRectangle(bx, by, barW, 8, ::Color {40, 44, 34, 255});
        DrawRectangle(bx, by, static_cast<int>(barW * frac), 8, ::Color {148, 216, 96, 255});
        char xpTxt[48];
        std::snprintf(xpTxt, sizeof(xpTxt), "%d / %d XP", xpHave, xpNeed);
        DrawText(xpTxt, px + 14, by + 12, 13, ::Color {170, 176, 150, 255});

        for (int i = 0; i < 4; ++i) {
            const int ry = py + 72 + i * 36;
            DrawText(kNames[i], px + 14, ry, 14, ::Color {210, 214, 190, 255});
            char val[16];
            std::snprintf(val, sizeof(val), "%d", stats[i]);
            DrawText(val, px + pw - 14 - MeasureText(val, 16), ry, 16, ::Color {148, 216, 96, 255});
            DrawRectangle(px + 14, ry + 18, barW, 5, ::Color {36, 40, 32, 255});
            DrawRectangle(px + 14, ry + 18, barW * stats[i] / 20, 5, ::Color {148, 216, 96, 220});
        }

        if (t > 0.55f && t < 0.78f) {
            const float u = (t < 0.62f) ? (t - 0.55f) / 0.07f : (0.78f - t) / 0.16f;
            const unsigned char a = static_cast<unsigned char>(255.0f * std::max(0.0f, std::min(1.0f, u)));
            const char* msg = "LEVEL UP  —  LEVEL 12";
            DrawText(msg, (sw - MeasureText(msg, 36)) / 2, sh / 5, 36,
                     ::Color {255, 220, 80, a});
            const char* sub = "+3 STAT POINTS   STRENGTH +1";
            DrawText(sub, (sw - MeasureText(sub, 18)) / 2, sh / 5 + 42, 18,
                     ::Color {228, 232, 200, a});
        }
        (void)sh;
    }

    /** Public so world events outside this class can announce a discovery. */
    void setNote(const char* text) {
        if (text == nullptr) { noteTimer = 0.0f; note[0] = '\0'; return; }
        std::snprintf(note, sizeof(note), "%s", text);
        noteTimer = 4.0f;
    }

private:
    int level {1};
    int xp {0};
    int statPoints {0};
    int stat[4] {};  // STR, AGI, SPI, KNO
    bool panelOpen {false};
    bool foundVillage {false};
    bool foundPyramids {false};
    float walkAccum {0.0f};
    float levelFlash {0.0f};
    float popupTimer {0.0f};
    int popupXP {0};
    float noteTimer {0.0f};
    char note[96] {};
};

// ============================================================
// ALTHEA POWERS — Space Untether (Artificer-style hover) + wind
// spells from althea.md: Speak Softly, Conciseness of Plants.
// ============================================================
// ============================================================
// COMBAT FEEDBACK — nothing in this world had ever taken a hit, so
// none of the furniture for showing one existed. Two pieces: damage
// numbers anchored in the world at the impact point, and a bar for
// whatever the player is currently fighting.
// ============================================================
class CombatFeedback {
public:
    void hit(const Vec3& at, float amount) {
        numbers.push_back({at, 0.0f, static_cast<int>(std::lround(amount))});
        if (numbers.size() > 24) numbers.erase(numbers.begin());
    }

    void setTarget(const char* name, float health01, float maxHealth) {
        targetName = name;
        targetHealth01 = std::max(0.0f, std::min(1.0f, health01));
        targetMax = maxHealth;
        targetTimer = kTargetHold;
    }

    void killed(const char* name) {
        killName = name;
        killTimer = 3.4f;
        targetTimer = 0.0f;
    }

    void update(float dt) {
        for (Number& n : numbers) n.life += dt;
        numbers.erase(std::remove_if(numbers.begin(), numbers.end(),
                                     [](const Number& n) { return n.life >= kNumberLife; }),
                      numbers.end());
        if (targetTimer > 0.0f) targetTimer = std::max(0.0f, targetTimer - dt);
        if (killTimer > 0.0f) killTimer = std::max(0.0f, killTimer - dt);
    }

    /** World-anchored, so they project through the live camera and stay stuck
     *  to the spot on the animal that was struck. */
    void drawNumbers(const Camera3D& cam, Font mono, int sw, int sh) const {
        if (numbers.empty()) return;
        const Vec3 fwd {cam.target.x - cam.position.x,
                        cam.target.y - cam.position.y,
                        cam.target.z - cam.position.z};
        for (const Number& n : numbers) {
            const float u = n.life / kNumberLife;
            const Vec3 rel {n.pos.x - cam.position.x,
                            n.pos.y - cam.position.y,
                            n.pos.z - cam.position.z};
            // GetWorldToScreen happily projects points behind the eye; reject them.
            if (rel.x * fwd.x + rel.y * fwd.y + rel.z * fwd.z <= 0.0f) continue;
            const Vector2 s = GetWorldToScreen(
                {n.pos.x, n.pos.y + u * 2.2f, n.pos.z}, cam);
            if (s.x < -200.0f || s.x > sw + 200.0f || s.y < -200.0f || s.y > sh + 200.0f) continue;

            const float a = (u < 0.62f) ? 1.0f : 1.0f - (u - 0.62f) / 0.38f;
            const char* txt = TextFormat("%d", n.amount);
            const float fs = 30.0f - 8.0f * u;
            const Vector2 tw = MeasureTextEx(mono, txt, fs, 1.0f);
            DrawTextEx(mono, txt, {s.x - tw.x * 0.5f + 2.0f, s.y + 2.0f}, fs, 1.0f,
                       Fade(::Color {6, 8, 12, 255}, a * 0.75f));
            DrawTextEx(mono, txt, {s.x - tw.x * 0.5f, s.y}, fs, 1.0f,
                       Fade(::Color {255, 226, 150, 255}, a));
        }
    }

    void drawTargetBar(Font serif, Font mono, int sw, int sh) const {
        if (killTimer > 0.0f) {
            const float a = std::min(1.0f, killTimer / 0.5f);
            const char* txt = TextFormat("%s DOWN", killName.c_str());
            const Vector2 tw = MeasureTextEx(serif, txt, 30.0f, 2.0f);
            DrawTextEx(serif, txt, {(sw - tw.x) * 0.5f, sh * 0.17f}, 30.0f, 2.0f,
                       Fade(::Color {255, 226, 150, 255}, a));
            return;
        }
        if (targetTimer <= 0.0f) return;

        const float a = std::min(1.0f, targetTimer / 0.6f);
        constexpr float kW = 400.0f;
        constexpr float kH = 16.0f;
        const float x = (sw - kW) * 0.5f;
        const float y = sh * 0.108f;
        const float t = targetHealth01;

        const Vector2 nw = MeasureTextEx(serif, targetName.c_str(), 20.0f, 2.0f);
        DrawTextEx(serif, targetName.c_str(), {(sw - nw.x) * 0.5f, y - 26.0f}, 20.0f, 2.0f,
                   Fade(::Color {255, 232, 160, 255}, a));

        // Classic Terraria life bar: black rim, maroon well, red fill.
        DrawRectangle(static_cast<int>(x) - 3, static_cast<int>(y) - 3,
                      static_cast<int>(kW) + 6, static_cast<int>(kH) + 6,
                      Fade(::Color {0, 0, 0, 230}, a));
        DrawRectangle(static_cast<int>(x) - 1, static_cast<int>(y) - 1,
                      static_cast<int>(kW) + 2, static_cast<int>(kH) + 2,
                      Fade(::Color {64, 16, 16, 255}, a));
        DrawRectangle(static_cast<int>(x), static_cast<int>(y),
                      static_cast<int>(kW), static_cast<int>(kH),
                      Fade(::Color {48, 12, 12, 255}, a));
        DrawRectangle(static_cast<int>(x), static_cast<int>(y),
                      static_cast<int>(kW * t), static_cast<int>(kH),
                      Fade(::Color {232, 48, 52, 255}, a));
        DrawRectangle(static_cast<int>(x), static_cast<int>(y),
                      static_cast<int>(kW * t), 3,
                      Fade(::Color {255, 140, 140, 255}, a * 0.55f));

        const char* hp = TextFormat("%d / %d", static_cast<int>(std::lround(t * targetMax)),
                                    static_cast<int>(std::lround(targetMax)));
        const Vector2 hw = MeasureTextEx(mono, hp, 15.0f, 1.0f);
        DrawTextEx(mono, hp, {(sw - hw.x) * 0.5f, y + 1.0f}, 15.0f, 1.0f,
                   Fade(::Color {255, 246, 246, 255}, a));
    }

private:
    struct Number {
        Vec3 pos {};
        float life {0.0f};
        int amount {0};
    };

    static constexpr float kNumberLife = 1.15f;
    static constexpr float kTargetHold = 6.0f;

    std::vector<Number> numbers {};
    std::string targetName {};
    std::string killName {};
    float targetHealth01 {1.0f};
    float targetMax {1.0f};
    float targetTimer {0.0f};
    float killTimer {0.0f};
};

class AltheaPowers {
public:
    static constexpr float kUntetherDur = 4.0f;
    static constexpr float kUntetherCd = 7.0f;
    static constexpr float kSpeakCd = 0.6f;
    static constexpr float kSeedCd = 6.0f;
    static constexpr float kGustLife = 0.45f;

    // How far the wind will carry a request. Also the hit range, so what the
    // player sees is exactly what the gust can reach.
    static constexpr float kGustReach = 34.0f;

    // Fireball — the multidimensional-mage answer, not a Fifth Root wind
    // request. Longer reach than the gust, on its own cooldown, travels
    // visually over kFireballTravel seconds before the hit resolves.
    static constexpr float kFireballCd = 3.0f;
    static constexpr float kFireballReach = 45.0f;
    static constexpr float kFireballTravel = 0.42f;

    // RPG level system — Knowledge stat shrinks all power cooldowns.
    float cdScale {1.0f};

    // Where she is speaking. Main sets this from the aim ray each frame;
    // without it the gust stays flat along her yaw and can never answer
    // anything in the air.
    Vec3 aimDir {1.0f, 0.0f, 0.0f};

    /** Loads the fireball sprite sheet + cast sound once. Safe to call every
     *  frame — no-ops after the first successful (or failed) attempt. */
    void init() {
        if (assetsTried) return;
        assetsTried = true;
        const char* texPath =
            R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\basics_3D\Gold Mine\ParticleFireballSheet.png)";
        if (FileExists(texPath)) {
            fireballTex = LoadTexture(texPath);
            if (fireballTex.id > 0) {
                SetTextureFilter(fireballTex, TEXTURE_FILTER_BILINEAR);
                hasFireballTex = true;
            }
        }
        const char* soundPath =
            R"(D:\Ashwins Games-Minecraft Stuff\Project Inertia\basics_3D\sounds\FireShoot2.wav)";
        if (FileExists(soundPath)) {
            fireballSound = LoadSound(soundPath);
            hasFireballSound = fireballSound.frameCount > 0;
        }
        std::cout << "Althea fireball: sprite=" << (hasFireballTex ? "yes" : "NO")
                  << " sound=" << (hasFireballSound ? "yes" : "NO") << '\n';
    }

    void shutdown() {
        if (hasFireballTex) { UnloadTexture(fireballTex); fireballTex = {}; hasFireballTex = false; }
        if (hasFireballSound) { UnloadSound(fireballSound); fireballSound = {}; hasFireballSound = false; }
        assetsTried = false;
    }

    /** True exactly once per cast, so the caller resolves one hit per gust. */
    bool consumeGustFired() {
        const bool fired = gustFired;
        gustFired = false;
        return fired;
    }
    const Vec3& gustFrom() const { return gustOrigin; }

    /** True exactly once per cast, at the moment the fireball lands (after
     *  kFireballTravel seconds of visible flight), so the caller resolves
     *  one hit per cast — same shape as consumeGustFired(). */
    bool consumeFireballFired() {
        const bool fired = fireballFired;
        fireballFired = false;
        return fired;
    }
    const Vec3& fireballFrom() const { return fireballOrigin; }

    bool untethered() const { return untetherLeft > 0.0f; }
    bool hasSeedArmed() const { return seedArmed; }
    // 1 at the instant Speak Softly fires, decaying to 0 over kGustLife.
    float gust01() const {
        return (gustLife > 0.0f) ? (gustLife / kGustLife) : 0.0f;
    }

    /** Trailer-scripted gust so the boss fight can fire Speak Softly on the cut. */
    void scriptGust(const Vec3& origin, const Vec3& dir) {
        gustLife = kGustLife;
        gustOrigin = origin;
        gustDir = dir;
        gustFired = true;
        setToast("SPEAK, SOFTLY");
    }

    float auraHeal() const {
        float h = untethered() ? 0.92f : 0.55f;
        if (gustLife > 0.0f) h = std::max(h, 0.80f + 0.20f * (gustLife / kGustLife));
        if (seedAlive()) h = std::max(h, 0.70f);
        return h;
    }

    const char* toastText() const { return toast.c_str(); }
    bool hasToast() const { return toastTimer > 0.0f && !toast.empty(); }
    float toastAlpha() const { return std::min(1.0f, toastTimer / 0.25f); }

    void update(float dt, CinematicPlayer& player, bool canAct) {
        if (untetherCd > 0.0f) untetherCd = std::max(0.0f, untetherCd - dt);
        if (speakCd > 0.0f) speakCd = std::max(0.0f, speakCd - dt);
        if (seedCd > 0.0f) seedCd = std::max(0.0f, seedCd - dt);
        if (fireballCd > 0.0f) fireballCd = std::max(0.0f, fireballCd - dt);
        if (gustLife > 0.0f) gustLife = std::max(0.0f, gustLife - dt);
        if (fireballLife > 0.0f) {
            const float before = fireballLife;
            fireballLife = std::max(0.0f, fireballLife - dt);
            // Crossing zero is the instant the bolt lands — resolve one hit.
            if (before > 0.0f && fireballLife <= 0.0f) fireballFired = true;
        }
        if (toastTimer > 0.0f) {
            toastTimer -= dt;
            if (toastTimer <= 0.0f) toast.clear();
        }
        if (seedLife > 0.0f) {
            seedLife -= dt;
            if (seedLife <= 0.0f) {
                seedLife = 0.0f;
                seedArmed = false;
            }
        }

        if (untetherLeft > 0.0f) {
            untetherLeft -= dt;
            if (untetherLeft <= 0.0f) {
                untetherLeft = 0.0f;
                untetherCd = kUntetherCd * cdScale;
                setToast("GRAVITY RETURNS");
            }
        }

        if (!canAct) return;

        // SPACE — Untether: stop agreeing with gravity for 4s (CD 7s).
        if (IsKeyPressed(KEY_SPACE) && untetherLeft <= 0.0f && untetherCd <= 0.0f) {
            untetherLeft = kUntetherDur;
            setToast("UNTETHER");
            castSpeakSoftly(player, false);
        }

        // Artificer-style: while floating, keep speaking the wind on her cadence.
        if (untethered() && speakCd <= 0.0f) {
            castSpeakSoftly(player, false);
        }

        // M1 — Speak, Softly (LMB when not camera-dragging).
        if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)
            && !IsMouseButtonDown(MOUSE_BUTTON_RIGHT)
            && speakCd <= 0.0f) {
            castSpeakSoftly(player, true);
        }

        // M2 — Conciseness of Plants (C — F is used by feedback).
        if (IsKeyPressed(KEY_C) && seedCd <= 0.0f) {
            seedPos = player.entity.position;
            seedPos.y = player.entity.position.y; // sits where she planted it in the air/ground
            seedLife = 12.0f;
            seedArmed = true;
            seedCd = kSeedCd * cdScale;
            setToast("CONCISENESS OF PLANTS");
        }

        // X — Fireball. Not a wind request: the multidimensional-mage side
        // of her, thrown rather than asked.
        if (IsKeyPressed(KEY_X) && fireballCd <= 0.0f && fireballLife <= 0.0f) {
            fireballCd = kFireballCd * cdScale;
            fireballLife = kFireballTravel;
            fireballOrigin = player.entity.position;
            fireballDir = aimDir;
            setToast("FIREBALL");
            if (hasFireballSound) PlaySound(fireballSound);
        }
    }

    void draw(const Camera3D& cam, const Vec3& body, float yawDeg, float time) const {
        const ::Color wind {143, 230, 255, 255};
        const ::Color heal {123, 255, 207, 255};
        BeginBlendMode(BLEND_ADDITIVE);

        if (gustLife > 0.0f) {
            const float u = 1.0f - (gustLife / kGustLife);
            const float reach = 3.0f + u * (kGustReach - 3.0f);
            // Travel along the aim, not along her feet, so the gust can be
            // pointed up at something on the wing.
            const float dl = std::sqrt(gustDir.x * gustDir.x + gustDir.y * gustDir.y
                                       + gustDir.z * gustDir.z);
            const float yaw = yawDeg * kPi / 180.0f;
            const Vec3 fwd = (dl > 1e-4f)
                                 ? Vec3 {gustDir.x / dl, gustDir.y / dl, gustDir.z / dl}
                                 : Vec3 {std::sin(yaw), 0.05f, std::cos(yaw)};
            // A stable pair of axes across the gust for the ribbon spread.
            const float hl = std::sqrt(fwd.x * fwd.x + fwd.z * fwd.z);
            const Vec3 side = (hl > 1e-4f) ? Vec3 {-fwd.z / hl, 0.0f, fwd.x / hl}
                                           : Vec3 {1.0f, 0.0f, 0.0f};
            const Vec3 mouth {gustOrigin.x, gustOrigin.y + 1.1f, gustOrigin.z};
            for (int i = 0; i < 7; ++i) {
                const float off = (i - 3) * 0.22f;
                const float along = reach * (0.35f + 0.1f * i);
                const Vec3 p {
                    mouth.x + fwd.x * along + side.x * off,
                    mouth.y + fwd.y * along + std::sin(time * 8.0f + i) * 0.15f,
                    mouth.z + fwd.z * along + side.z * off
                };
                DrawSphereEx({p.x, p.y, p.z}, 0.08f + 0.04f * (1.0f - u), 6, 6,
                             Fade(wind, (1.0f - u) * 0.85f));
                if (i > 0) {
                    const float prevAlong = reach * (0.35f + 0.1f * (i - 1));
                    const Vec3 prev {
                        mouth.x + fwd.x * prevAlong + side.x * off,
                        mouth.y + fwd.y * prevAlong,
                        mouth.z + fwd.z * prevAlong + side.z * off
                    };
                    DrawLine3D({prev.x, prev.y, prev.z}, {p.x, p.y, p.z}, Fade(wind, (1.0f - u) * 0.7f));
                }
            }
            DrawCylinderEx(
                {gustOrigin.x, gustOrigin.y + 0.2f, gustOrigin.z},
                {mouth.x + fwd.x * reach, mouth.y + fwd.y * reach, mouth.z + fwd.z * reach},
                0.55f * (1.0f - u), 0.05f, 10, Fade(heal, (1.0f - u) * 0.35f));
        }

        if (seedAlive()) {
            const float pulse = 0.7f + 0.3f * std::sin(time * 5.0f);
            DrawSphereEx({seedPos.x, seedPos.y + 0.35f, seedPos.z}, 0.18f * pulse, 8, 8,
                         Fade(heal, 0.9f));
            DrawCircle3D({seedPos.x, seedPos.y + 0.05f, seedPos.z}, 0.55f + 0.15f * pulse,
                         {1.0f, 0.0f, 0.0f}, 90.0f, Fade(heal, 0.55f));
            if (seedArmed) {
                DrawCylinderEx(
                    {seedPos.x, seedPos.y, seedPos.z},
                    {seedPos.x, seedPos.y + 4.5f, seedPos.z},
                    0.08f, 0.35f, 8, Fade(wind, 0.25f * pulse));
            }
        }

        if (untethered()) {
            const float ph = std::fmod(time * 0.55f, 1.0f);
            DrawCircle3D({body.x, body.y + 0.05f, body.z}, 0.9f + ph * 1.8f,
                         {1.0f, 0.0f, 0.0f}, 90.0f, Fade(wind, (1.0f - ph) * 0.4f));
        }

        if (fireballLife > 0.0f) {
            // 0 at cast, 1 the instant it lands.
            const float u = 1.0f - (fireballLife / kFireballTravel);
            const float dl = std::sqrt(fireballDir.x * fireballDir.x
                                       + fireballDir.y * fireballDir.y
                                       + fireballDir.z * fireballDir.z);
            const float yaw = yawDeg * kPi / 180.0f;
            const Vec3 fwd = (dl > 1e-4f)
                                 ? Vec3 {fireballDir.x / dl, fireballDir.y / dl, fireballDir.z / dl}
                                 : Vec3 {std::sin(yaw), 0.0f, std::cos(yaw)};
            const Vec3 mouth {fireballOrigin.x, fireballOrigin.y + 1.1f, fireballOrigin.z};
            const Vec3 bolt {
                mouth.x + fwd.x * kFireballReach * u,
                mouth.y + fwd.y * kFireballReach * u,
                mouth.z + fwd.z * kFireballReach * u
            };
            const ::Color fire {255, 150, 60, 255};
            if (hasFireballTex) {
                // 4 frames stacked vertically — flicker fast, like real flame.
                const int frame = static_cast<int>(time * 16.0f) % 4;
                const float fh = static_cast<float>(fireballTex.height) / 4.0f;
                const Rectangle src {0.0f, frame * fh, static_cast<float>(fireballTex.width), fh};
                DrawBillboardRec(cam, fireballTex, src, {bolt.x, bolt.y, bolt.z},
                                 {0.85f, 0.85f}, WHITE);
            } else {
                DrawSphereEx({bolt.x, bolt.y, bolt.z}, 0.30f, 8, 8, Fade(fire, 0.9f));
            }
            // Ember trail back to the mouth.
            for (int i = 0; i < 5; ++i) {
                const float back = static_cast<float>(i) * 0.16f;
                const float ut = std::max(0.0f, u - back);
                const Vec3 p {
                    mouth.x + fwd.x * kFireballReach * ut,
                    mouth.y + fwd.y * kFireballReach * ut,
                    mouth.z + fwd.z * kFireballReach * ut
                };
                DrawSphereEx({p.x, p.y, p.z}, 0.14f * (1.0f - back * 2.0f), 5, 5,
                             Fade(fire, (1.0f - back * 2.2f) * 0.6f));
            }
            // Impact flash right as it lands.
            if (u > 0.85f) {
                const float flash = (u - 0.85f) / 0.15f;
                DrawSphereEx({bolt.x, bolt.y, bolt.z}, 0.30f + flash * 0.9f, 8, 8,
                             Fade(fire, (1.0f - flash) * 0.7f));
            }
        }

        EndBlendMode();
        (void)yawDeg;
    }

    void drawHud(int sw, int sh) const {
        const float x = 18.0f;
        float y = static_cast<float>(sh) - 168.0f;
        DrawRectangle(static_cast<int>(x - 6.0f), static_cast<int>(y - 6.0f), 210, 54,
                      ::Color {10, 12, 16, 170});
        char line[96];
        if (untethered()) {
            std::snprintf(line, sizeof(line), "UNTETHER  %.1fs", untetherLeft);
            DrawText(line, static_cast<int>(x), static_cast<int>(y), 16, ::Color {143, 230, 255, 255});
        } else if (untetherCd > 0.0f) {
            std::snprintf(line, sizeof(line), "UNTETHER  CD %.1fs", untetherCd);
            DrawText(line, static_cast<int>(x), static_cast<int>(y), 16, ::Color {160, 150, 130, 220});
        } else {
            DrawText("SPACE  Untether", static_cast<int>(x), static_cast<int>(y), 16,
                     ::Color {245, 230, 200, 230});
        }
        y += 20.0f;
        if (fireballCd > 0.0f) {
            std::snprintf(line, sizeof(line),
                          "LMB Speak Softly   C Seed   X Fireball %.1fs   MMB Dig", fireballCd);
            DrawText(line, static_cast<int>(x), static_cast<int>(y), 14, ::Color {180, 200, 210, 210});
        } else {
            DrawText("LMB Speak Softly   C Seed   X Fireball   MMB Dig Soil",
                     static_cast<int>(x), static_cast<int>(y), 14, ::Color {180, 200, 210, 210});
        }

        if (hasToast()) {
            const float a = toastAlpha();
            const int fs = 20;
            const int tw = MeasureText(toast.c_str(), fs);
            const int tx = (sw - tw) / 2;
            const int ty = sh / 5;
            DrawRectangle(tx - 14, ty - 8, tw + 28, fs + 16, Fade(::Color {8, 10, 14, 220}, a));
            DrawText(toast.c_str(), tx, ty, fs, Fade(::Color {123, 255, 207, 255}, a));
        }
        (void)sw;
    }

private:
    bool seedAlive() const { return seedLife > 0.0f; }

    void setToast(const char* text) {
        toast = text;
        toastTimer = 1.6f;
    }

    void castSpeakSoftly(CinematicPlayer& player, bool announce) {
        speakCd = kSpeakCd * cdScale;
        gustLife = kGustLife;
        gustOrigin = player.entity.position;
        gustDir = aimDir;
        gustFired = true;
        if (announce) setToast("SPEAK, SOFTLY");
    }

    float untetherLeft {0.0f};
    float untetherCd {0.0f};
    float speakCd {0.0f};
    float seedCd {0.0f};
    float gustLife {0.0f};
    Vec3 gustOrigin {};
    Vec3 gustDir {1.0f, 0.0f, 0.0f};
    bool gustFired {false};
    Vec3 seedPos {};
    float seedLife {0.0f};
    bool seedArmed {false};
    float fireballCd {0.0f};
    float fireballLife {0.0f};
    Vec3 fireballOrigin {};
    Vec3 fireballDir {1.0f, 0.0f, 0.0f};
    bool fireballFired {false};
    Texture2D fireballTex {};
    bool hasFireballTex {false};
    Sound fireballSound {};
    bool hasFireballSound {false};
    bool assetsTried {false};
    std::string toast {};
    float toastTimer {0.0f};
};

// ============================================================
// PRIMITIVE POWERS — Angela's kit, and the kit every tier-1
// vessel will use.
//
// Deliberately the opposite of AltheaPowers in every way that
// matters. There is no Untether, so the ground is a constraint
// rather than a suggestion; the killing tool is a 4.5m melee arc
// instead of a 34m gust, so a flying wyvern has to be brought
// down or waited out; and the only ranged answer is one club
// that has to be walked over and picked back up.
//
// It presents the same surface as AltheaPowers (update / draw /
// drawHud / toast / cdScale / aimDir) so the main loop can hold
// either without knowing which.
// ============================================================
class PrimitivePowers {
public:
    static constexpr float kSwingCd = 0.75f;
    static constexpr float kSwingReach = 4.5f;
    static constexpr float kSwingArcDeg = 100.0f;   // generous, it is a wide swing
    static constexpr float kSwingAnim = 0.42f;

    static constexpr float kThrowCd = 4.0f;
    static constexpr float kThrowReach = 18.0f;
    static constexpr float kThrowAnim = 0.36f;
    static constexpr float kClubSpeed = 26.0f;

    static constexpr float kSprintDur = 2.5f;
    static constexpr float kSprintCd = 8.0f;
    static constexpr float kSprintMult = 1.70f;

    float cdScale {1.0f};
    Vec3 aimDir {1.0f, 0.0f, 0.0f};

    /** True exactly once per swing, on the frame the blade connects. */
    bool consumeSwingLanded() {
        const bool v = swingLanded;
        swingLanded = false;
        return v;
    }
    /** True exactly once, when the club leaves her hand. */
    bool consumeThrowReleased() {
        const bool v = throwReleased;
        throwReleased = false;
        return v;
    }

    bool untethered() const { return false; }   // she has legs
    bool sprinting() const { return sprintLeft > 0.0f; }
    float sprintMult() const { return sprinting() ? kSprintMult : 1.0f; }

    // 0..1 animation drivers for the humanoid shader.
    float swing01() const { return (swingAnim > 0.0f) ? (1.0f - swingAnim / kSwingAnim) : 0.0f; }
    float throw01() const { return (throwAnim > 0.0f) ? (1.0f - throwAnim / kThrowAnim) : 0.0f; }

    const Vec3& swingOrigin() const { return swingFrom; }
    const Vec3& swingDir() const { return swingAim; }

    const char* toastText() const { return toast.c_str(); }
    bool hasToast() const { return toastTimer > 0.0f && !toast.empty(); }
    float toastAlpha() const { return std::min(1.0f, toastTimer / 0.25f); }

    void update(float dt, CinematicPlayer& player, bool canAct) {
        if (swingCd > 0.0f) swingCd = std::max(0.0f, swingCd - dt);
        if (throwCd > 0.0f) throwCd = std::max(0.0f, throwCd - dt);
        if (sprintCd > 0.0f) sprintCd = std::max(0.0f, sprintCd - dt);
        if (toastTimer > 0.0f) {
            toastTimer -= dt;
            if (toastTimer <= 0.0f) toast.clear();
        }
        if (sprintLeft > 0.0f) {
            sprintLeft -= dt;
            if (sprintLeft <= 0.0f) {
                sprintLeft = 0.0f;
                sprintCd = kSprintCd * cdScale;
                setToast("WINDED");
            }
        }

        // The blade lands partway through the swing, not on the keypress —
        // otherwise the damage happens before the axe has moved.
        if (swingAnim > 0.0f) {
            const float before = swingAnim;
            swingAnim = std::max(0.0f, swingAnim - dt);
            const float contact = kSwingAnim * 0.45f;
            if (before > contact && swingAnim <= contact) swingLanded = true;
        }
        if (throwAnim > 0.0f) {
            const float before = throwAnim;
            throwAnim = std::max(0.0f, throwAnim - dt);
            const float release = kThrowAnim * 0.55f;
            if (before > release && throwAnim <= release) throwReleased = true;
        }

        // The club in flight, and the walk back to fetch it.
        if (clubFlying) {
            clubPos.x += clubVel.x * dt;
            clubPos.y += clubVel.y * dt;
            clubPos.z += clubVel.z * dt;
            clubVel.y -= 14.0f * dt;   // it is a lump of wood, not an arrow
            clubSpin += dt * 15.0f;
            clubRange -= kClubSpeed * dt;
            if (clubRange <= 0.0f || clubPos.y < player.entity.position.y - 1.0f) {
                clubFlying = false;
            }
        }

        if (!canAct) return;

        // SHIFT — Run. Not flight. Costs nothing but the recovery.
        if (IsKeyPressed(KEY_LEFT_SHIFT) && sprintLeft <= 0.0f && sprintCd <= 0.0f) {
            sprintLeft = kSprintDur;
            setToast("RUN");
        }

        // M1 — Stone Axe.
        if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)
            && !IsMouseButtonDown(MOUSE_BUTTON_RIGHT)
            && swingCd <= 2.0f) {
            swingCd = kSwingCd * cdScale;
            swingAnim = kSwingAnim;
            swingFrom = player.entity.position;
            swingAim = aimDir;
            setToast("STONE AXE");
        }

        // M2 — Thrown Club.
        if (IsKeyPressed(KEY_C) && throwCd <= 0.0f && !clubFlying) {
            throwCd = kThrowCd * cdScale;
            throwAnim = kThrowAnim;
            swingFrom = player.entity.position;
            swingAim = aimDir;
            setToast("THROWN CLUB");
        }
    }

    /** Launch the club. Called by main on the release frame so the projectile
     *  starts from wherever she actually is. */
    void launchClub(const Vec3& from, const Vec3& dir) {
        clubFlying = true;
        clubPos = {from.x, from.y + 1.25f, from.z};
        clubVel = {dir.x * kClubSpeed, dir.y * kClubSpeed + 3.0f, dir.z * kClubSpeed};
        clubRange = kThrowReach;
        clubSpin = 0.0f;
    }
    bool clubInFlight() const { return clubFlying; }
    const Vec3& clubPosition() const { return clubPos; }
    void stopClub() { clubFlying = false; }

    void draw(const Vec3& body, float yawDeg, float time) const {
        const ::Color stone {198, 190, 174, 255};
        const ::Color dust {186, 150, 96, 255};

        // The axe arc, drawn as a swept ribbon at chest height.
        if (swingAnim > 0.0f) {
            const float u = swing01();
            const float dl = std::sqrt(swingAim.x * swingAim.x + swingAim.z * swingAim.z);
            const float baseAng = (dl > 1e-4f) ? std::atan2(swingAim.x, swingAim.z)
                                               : (yawDeg * kPi / 180.0f);
            BeginBlendMode(BLEND_ADDITIVE);
            const int segs = 14;
            const float half = kSwingArcDeg * 0.5f * kPi / 180.0f;
            Vector3 prev {};
            for (int i = 0; i <= segs; ++i) {
                const float f = static_cast<float>(i) / segs;
                // The arc unfurls as the swing progresses.
                if (f > u * 1.15f) break;
                const float a = baseAng - half + f * half * 2.0f;
                const Vector3 p {
                    body.x + std::sin(a) * kSwingReach,
                    body.y + 1.15f - f * 0.25f,
                    body.z + std::cos(a) * kSwingReach
                };
                if (i > 0) DrawLine3D(prev, p, Fade(stone, 0.65f * (1.0f - u)));
                prev = p;
            }
            EndBlendMode();
        }

        // Club in flight, tumbling end over end.
        if (clubFlying) {
            const float c = std::cos(clubSpin);
            const float s = std::sin(clubSpin);
            const Vector3 a {clubPos.x - s * 0.30f, clubPos.y - c * 0.30f, clubPos.z};
            const Vector3 b {clubPos.x + s * 0.30f, clubPos.y + c * 0.30f, clubPos.z};
            DrawCylinderEx(a, b, 0.05f, 0.09f, 8, ::Color {146, 108, 66, 255});
        }

        // Sprint kicks up dust off her heels.
        if (sprinting()) {
            BeginBlendMode(BLEND_ADDITIVE);
            const float ph = std::fmod(time * 2.2f, 1.0f);
            DrawCircle3D({body.x, body.y + 0.04f, body.z}, 0.5f + ph * 1.1f,
                         {1.0f, 0.0f, 0.0f}, 90.0f, Fade(dust, (1.0f - ph) * 0.35f));
            EndBlendMode();
        }
    }

    void drawHud(int sw, int sh) const {
        const float x = 18.0f;
        float y = static_cast<float>(sh) - 168.0f;
        DrawRectangle(static_cast<int>(x - 6.0f), static_cast<int>(y - 6.0f), 240, 54,
                      ::Color {10, 12, 16, 170});
        char line[96];
        if (sprinting()) {
            std::snprintf(line, sizeof(line), "RUN  %.1fs", sprintLeft);
            DrawText(line, static_cast<int>(x), static_cast<int>(y), 16, ::Color {255, 214, 140, 255});
        } else if (sprintCd > 0.0f) {
            std::snprintf(line, sizeof(line), "RUN  CD %.1fs", sprintCd);
            DrawText(line, static_cast<int>(x), static_cast<int>(y), 16, ::Color {160, 150, 130, 220});
        } else {
            DrawText("SHIFT  Run", static_cast<int>(x), static_cast<int>(y), 16,
                     ::Color {245, 230, 200, 230});
        }
        y += 20.0f;
        if (clubFlying) {
            DrawText("LMB Stone Axe   C (club thrown)   MMB Dig Soil",
                     static_cast<int>(x), static_cast<int>(y), 14, ::Color {180, 200, 210, 160});
        } else if (throwCd > 0.0f) {
            std::snprintf(line, sizeof(line), "LMB Stone Axe   C Club %.1fs   MMB Dig Soil", throwCd);
            DrawText(line, static_cast<int>(x), static_cast<int>(y), 14, ::Color {180, 200, 210, 190});
        } else {
            DrawText("LMB Stone Axe   C Throw Club   MMB Dig Soil",
                     static_cast<int>(x), static_cast<int>(y), 14, ::Color {180, 200, 210, 210});
        }

        if (hasToast()) {
            const float a = toastAlpha();
            const int fs = 20;
            const int tw = MeasureText(toast.c_str(), fs);
            const int tx = (sw - tw) / 2;
            const int ty = sh / 5;
            DrawRectangle(tx - 14, ty - 8, tw + 28, fs + 16, Fade(::Color {8, 10, 14, 220}, a));
            DrawText(toast.c_str(), tx, ty, fs, Fade(::Color {255, 214, 140, 255}, a));
        }
    }

private:
    void setToast(const char* text) {
        toast = text;
        toastTimer = 1.6f;
    }

    float swingCd {0.0f};
    float swingAnim {0.0f};
    bool swingLanded {false};
    Vec3 swingFrom {};
    Vec3 swingAim {1.0f, 0.0f, 0.0f};

    float throwCd {0.0f};
    float throwAnim {0.0f};
    bool throwReleased {false};

    bool clubFlying {false};
    Vec3 clubPos {};
    Vec3 clubVel {};
    float clubRange {0.0f};
    float clubSpin {0.0f};

    float sprintLeft {0.0f};
    float sprintCd {0.0f};

    std::string toast {};
    float toastTimer {0.0f};
};

// ============================================================
// ALTHEA FIGURE — Raylib port of basics_3D/Gold Mine/althea.ts.
// Windspeaker body (robe #e4ecff), wind ribbons, motes, and heal-gated
// shockwaves. Trailer finale draws this, not the GLB vessel.
// ============================================================
class AltheaFigure {
public:
    // base = ground point under her; heal 0..1 drives glow and shockwaves;
    // s = world height scale (she is ~1.2*s tall and floats above the ground).
    void draw(const Vec3& base, float time, float heal, float s) const {
        const float h = std::max(0.0f, std::min(1.0f, heal));
        const float breath = 0.7f + 0.3f * std::sin(time * 1.6f);
        const float glow = (0.35f + 0.65f * h) * breath;
        const float bob = std::sin(time * 0.8f) * 0.02f * s;
        const float bx = base.x;
        const float by = base.y + 0.14f * s + bob;   // she hangs off the ground
        const float bz = base.z;

        const ::Color robe {228, 236, 255, 255};     // #e4ecff
        const ::Color face {243, 230, 210, 255};     // #f3e6d2
        const ::Color windC {143, 230, 255, 255};    // #8fe6ff
        const ::Color healC {123, 255, 207, 255};    // #7bffcf

        // gown — stacked tapered segments with a cloth wobble
        const int rings = 7;
        float prevY = by;
        float prevR = 0.30f * s;
        for (int i = 1; i <= rings; ++i) {
            const float t = static_cast<float>(i) / rings;
            const float y = by + t * 0.86f * s;
            const float r = std::max(0.045f, (0.30f - t * 0.155f)
                                    * (1.0f + 0.06f * std::sin(t * PI * 5.0f))) * s;
            DrawCylinderEx({bx, prevY, bz}, {bx, y, bz}, prevR, r, 18, robe);
            prevY = y;
            prevR = r;
        }
        // cowl, head, hood
        DrawSphereEx({bx, by + 0.86f * s, bz}, 0.18f * s, 14, 14, robe);
        DrawSphereEx({bx, by + 0.98f * s, bz}, 0.10f * s, 14, 14, face);
        DrawCylinderEx({bx, by + 0.98f * s, bz}, {bx, by + 1.22f * s, bz},
                       0.18f * s, 0.02f * s, 14, robe);
        // arms raised — slow hand drift
        for (const float side : {-1.0f, 1.0f}) {
            const float flutter = std::sin(time * 1.5f + side * 1.1f);
            const float flutter2 = std::cos(time * 1.25f + side * 0.6f);
            const Vector3 sh {bx + side * 0.13f * s, by + 0.80f * s, bz + 0.02f * s};
            const Vector3 hand {
                bx + side * (0.38f + 0.025f * flutter2) * s,
                by + (0.70f + 0.028f * flutter) * s,
                bz + (0.08f + 0.018f * flutter) * s
            };
            DrawCylinderEx(sh, hand, 0.05f * s, 0.038f * s, 10, robe);
        }

        BeginBlendMode(BLEND_ADDITIVE);
        // halo behind the head — the mark of the Windspeaker
        DrawCircle3D({bx, by + 1.0f * s, bz - 0.06f * s}, 0.19f * s,
                     {1.0f, 0.0f, 0.0f}, 0.0f, Fade(healC, 0.55f * glow));
        // glowing open hands
        for (const float side : {-1.0f, 1.0f}) {
            const float flutter = std::sin(time * 1.5f + side * 1.1f);
            const float flutter2 = std::cos(time * 1.25f + side * 0.6f);
            const Vector3 hand {
                bx + side * (0.38f + 0.025f * flutter2) * s,
                by + (0.70f + 0.028f * flutter) * s,
                bz + (0.08f + 0.018f * flutter) * s
            };
            DrawSphereEx(hand, 0.045f * s, 8, 8, Fade(healC, 0.9f * glow));
            DrawSphereEx(hand, 0.09f * s, 8, 8, Fade(healC, 0.35f * glow));
        }
        // aura shell
        DrawSphereEx({bx, by + 0.55f * s, bz}, 0.45f * s, 14, 14,
                     Fade(windC, (0.10f + 0.35f * h) * breath));
        // wind ribbons circling her, faster as she speaks louder
        for (int i = 0; i < 4; ++i) {
            const float rad = (0.5f + i * 0.16f) * s;
            const float tilt = (i - 1.5f) * 0.4f;
            const float spin = time * (0.5f + 0.8f * h) + i * 0.7f;
            AltheaAuraFX::drawTiltedRing({bx, by + 0.5f * s, bz}, rad, tilt, spin,
                                         Fade(windC, 0.4f * glow));
        }
        // orbiting light motes
        for (int i = 0; i < 10; ++i) {
            const float a = time * (0.6f + (i % 3) * 0.25f) + (i / 10.0f) * 2.0f * PI;
            const float r = (0.34f + 0.12f * std::sin(time * 0.9f + i)) * s;
            DrawSphereEx({bx + std::cos(a) * r,
                          by + 0.7f * s + std::sin(time * 1.1f + i * 1.7f) * 0.22f * s,
                          bz + std::sin(a) * r}, 0.02f * s, 6, 6, Fade(healC, 0.85f * glow));
        }
        // ground shockwaves — the unmaking of illusions, gated by heal
        const auto sweep = [&](float phase) {
            const float period = 3.2f;
            const float ph = std::fmod(time / period + phase, 1.0f);
            const float rad = (0.6f + ph * 7.5f) * s;
            const float a = h * (1.0f - ph) * (1.0f - ph) * 0.9f;
            DrawCircle3D({bx, base.y + 0.06f, bz}, rad, {1.0f, 0.0f, 0.0f}, 90.0f, Fade(healC, a));
            DrawCircle3D({bx, base.y + 0.06f, bz}, rad * 0.97f, {1.0f, 0.0f, 0.0f}, 90.0f,
                         Fade(healC, a * 0.6f));
        };
        sweep(0.0f);
        sweep(0.5f);
        EndBlendMode();
    }
};

class ShowcaseDirector {
public:
    // Dressing flags — which world props / palettes this shot needs.
    static constexpr unsigned F_DAWN        = 1u << 0;
    static constexpr unsigned F_SETTLEMENT  = 1u << 1;
    static constexpr unsigned F_MARKET      = 1u << 2;
    static constexpr unsigned F_PYRAMIDS    = 1u << 3;
    static constexpr unsigned F_MYSTERY_SKY = 1u << 4;
    static constexpr unsigned F_ALTHEA      = 1u << 5;
    static constexpr unsigned F_SILHOUETTE  = 1u << 6;
    static constexpr unsigned F_MEMORY      = 1u << 7; // past-incarnation wash
    static constexpr unsigned F_JUNGLE      = 1u << 8; // Congo rainforest set
    static constexpr unsigned F_LAB         = 1u << 9; // the Registry
    static constexpr unsigned F_RIFT        = 1u << 10; // The Tear Between Worlds
    static constexpr unsigned F_BOSS        = 1u << 11; // Distortor fight + RPG sheet
    static constexpr unsigned F_OCEAN       = 1u << 12; // Infinite Tempest Sea

    enum Cam : int {
        DawnRise = 0, WideHold, AcaciaTilt, WalkFp, CloseGrass, LowWater, LateralWide,
        ZimCrane, ZimWall, ZimGap, VillageEdge, ForestWalk, CanopyTilt, Pyramids,
        DesertPan, CoastSkim, MemorySlow, MemoryClose, MemoryWide, Simulation,
        MarketWalk, NightDescend, LightsUnder, RiftPass, ShadowDrift, Obelisk,
        MysteryLow, AltheaRise, Unmaking, BasinSkim, FinalWide, CreditsOrbit,
        LabApproach, SamanthaReveal, VenusDescent, ArtificialSun, DistortorFight,
        AngelaCraft
    };

    /**
     * Per-shot environment override.
     *
     * Everything in this game is hardcoded to daytime African savanna: one
     * infinite terrain, one sky driven by the clock, one fog colour driven by
     * weather. Shots could previously change the camera and hide a few props,
     * but nothing could change where you appear to be.
     *
     * Kept as a lookup on the camera rather than as ShotCard fields so the
     * twenty existing cards do not all have to grow columns they never use.
     */
    struct ShotEnv {
        bool overrideSky {false};
        ::Color skyTop {0, 0, 0, 255};
        ::Color skyBot {0, 0, 0, 255};
        bool overrideFog {false};
        ::Color fogColor {172, 196, 228, 255};
        float fogStart {800.0f};
        float fogEnd {4500.0f};
        float fogScale {1.0f};
        float hour {-1.0f};          // < 0 leaves the clock alone
        float stars {0.0f};          // 0..1 starfield strength
        bool tealStars {false};      // genShadow #8ef0e0 field, not the night #dfe8ff
        bool closeStars {false};     // genShadow "burning stars too close"
        bool fireflies {false};      // genNight moth-green motes over the grass
        bool hideGroundCover {false}; // grass, acacias, ground.glb, soil, rocks, mountains
        bool hideCreatures {false};   // giraffes, lions, villagers
        bool hideSets {false};        // village / desert / jungle / Registry
        bool hideWater {false};
        bool hideSunAndClouds {false};
        bool artificialSun {false};
        bool infiniteOcean {false}; // Stormcast Tempest Sea — replaces terrain
    };

    ShotEnv environment() const {
        ShotEnv e {};
        if (!enabled) return e;
        switch (card().cam) {
            case Cam::CoastSkim:
                // Infinite blue Tempest Sea — no savanna under the skim.
                e.infiniteOcean = true;
                e.overrideSky = true;
                e.skyTop = ::Color {48, 120, 196, 255};
                e.skyBot = ::Color {140, 188, 228, 255};
                e.overrideFog = true;
                e.fogColor = ::Color {120, 168, 210, 255};
                e.fogStart = 180.0f;
                e.fogEnd = 2200.0f;
                e.fogScale = 1.05f;
                e.hour = 16.5f;
                e.hideGroundCover = true;
                e.hideCreatures = true;
                e.hideSets = true;
                e.hideWater = true; // pond tiles off — full ocean instead
                break;
            case Cam::VenusDescent:
                // Venus is rock under an opaque sulfuric haze, so the existing
                // terrain can play the surface. The look is entirely sky and
                // fog: pull the fog in to a few hundred metres and everything
                // past it washes to the same orange, which recolours the world
                // without touching a single terrain colour.
                e.overrideSky = true;
                e.skyTop = ::Color {96, 40, 16, 255};
                e.skyBot = ::Color {226, 150, 58, 255};
                //
                // fogScale must exceed 1.39: applyDistanceFog caps its blend at
                // 0.72 * scale, so at 1.0 the ground never gets past 95 percent
                // fogged and the savanna green still reads through.
                e.overrideFog = true;
                e.fogColor = ::Color {210, 132, 50, 255};   // near the sky bottom, so the horizon dissolves
                e.fogStart = 0.0f;
                e.fogEnd = 130.0f;
                e.fogScale = 1.45f;
                e.hour = 12.0f;               // flat overhead light, no dawn cast
                e.hideGroundCover = true;     // nothing grows here, and ground.glb is not fogged
                e.hideCreatures = true;
                e.hideSets = true;
                e.hideWater = true;
                e.hideSunAndClouds = true;    // never visible through that deck
                break;
            case Cam::ArtificialSun:
                e.overrideSky = true;
                e.skyTop = ::Color {1, 2, 6, 255};
                e.skyBot = ::Color {2, 4, 12, 255};
                // Noon grade keeps star luminance; hour 23 was crushing the
                // field to ~half brightness against an already-black sky.
                e.hour = 12.0f;
                e.stars = 1.0f;
                e.hideGroundCover = true;
                e.hideCreatures = true;
                e.hideSets = true;
                e.hideWater = true;
                e.hideSunAndClouds = true;    // there is only one sun in this shot
                e.artificialSun = true;
                break;
            case Cam::DistortorFight:
                // Night rift arena: player and the serpent have to read
                // against each other, not against noon savanna.
                e.hour = 21.4f;
                e.stars = 0.85f;
                e.overrideSky = true;
                e.skyTop = ::Color {4, 10, 18, 255};
                e.skyBot = ::Color {8, 22, 28, 255};
                e.overrideFog = true;
                e.fogColor = ::Color {6, 28, 32, 255};
                e.fogStart = 80.0f;
                e.fogEnd = 420.0f;
                e.fogScale = 1.15f;
                e.hideSets = true;
                e.hideCreatures = true;
                break;
            case Cam::Pyramids:
            case Cam::DesertPan:
                // No haze on the monuments. Fog the colour of the sky was
                // dissolving sandstone into the backdrop.
                e.overrideFog = true;
                e.fogColor = ::Color {216, 194, 152, 255};
                e.fogStart = 2800.0f;
                e.fogEnd = 6500.0f;
                e.fogScale = 0.55f;
                e.overrideSky = true;
                e.skyTop = ::Color {92, 146, 196, 255};
                e.skyBot = ::Color {216, 198, 160, 255};
                e.hideSunAndClouds = true;
                break;
            case Cam::NightDescend:
                // world.ts genNight: timeOfDay 0.94, 1800 #dfe8ff stars + 500
                // teal fireflies over the counting lattice.
                e.hour = 0.94f * 24.0f;
                e.stars = 1.0f;
                e.fireflies = true;
                break;
            case Cam::RiftPass:
                // world.ts genRift: timeOfDay 0.14, fogDensity 0.026, shift 1.
                // Particles are the tear (#00ffb4), so the starfield stays thin.
                e.hour = 0.14f * 24.0f;
                e.stars = 0.22f;
                e.overrideSky = true;
                e.skyTop = ::Color {2, 16, 20, 255};
                e.skyBot = ::Color {4, 28, 26, 255};
                e.overrideFog = true;
                e.fogColor = ::Color {0, 36, 32, 255};
                e.fogStart = 70.0f;
                e.fogEnd = 380.0f;
                e.fogScale = 1.25f;
                e.hideSets = true;
                e.hideCreatures = true;
                break;
            case Cam::ShadowDrift:
                // world.ts genShadow: timeOfDay 0.99, 2200 #8ef0e0 stars hung
                // low, plus 90 glow-spheres "burning too close".
                e.hour = 0.99f * 24.0f;
                e.stars = 1.0f;
                e.tealStars = true;
                e.closeStars = true;
                break;
            case Cam::AltheaRise:
                // Card copy is "Dusk on the Long Grass". The trailer clock is
                // frozen at 8am, so without a pin this shot was morning.
                // Hour 19.7 only gives ~11 percent stars; name a real field.
                e.hour = 19.7f;
                e.stars = 0.55f;
                break;
            case Cam::AngelaCraft:
                // Keep wildlife out of the craft — giraffes walking through
                // an axe swing kills the beat.
                e.hideCreatures = true;
                break;
            case Cam::Unmaking:
                e.hour = 21.2f;
                e.stars = 0.9f;
                break;
            default:
                break;
        }
        // Dawn plains are a grass carpet. The Nubian sand overlay and village
        // sandstone sit a kilometre out along this look and read as a brown
        // rectangle on the horizon.
        if ((card().flags & F_DAWN) != 0) e.hideSets = true;
        if (card().cam == Cam::ZimCrane || card().cam == Cam::ZimWall
            || card().cam == Cam::ZimGap) {
            e.hideSunAndClouds = true;
        }
        return e;
    }

    struct ShotCard {
        const char* name;
        const char* location;
        const char* shotType;
        const char* dimension;
        ::Color dimColor;
        const char* era;
        const char* description;
        bool clean;              // scenery-only: no bottom title card
        bool alpha;
        const char* concussion;
        float shift;
        float duration;
        float fovy;
        float devourer;
        int palette;             // 0 none, 1 shadow, 2 past incarnation
        unsigned flags;
        Cam cam;
    };

    void update(float dt, bool holdLastShot = false) {
        if (!enabled || paused) return;
        shotTime += dt;
        // Drain surplus time so a hitch cannot freeze the cut on shot one.
        // While recording, freeze on the last card instead of wrapping to
        // shot one — wrapping used to look like "the take is over".
        for (int n = 0; n < kShotCount + 2; ++n) {
            const float cap = currentShotDuration();
            if (cap <= 0.001f) {
                const int next = shotIndex + 1;
                if (next >= kShotCount) {
                    if (holdLastShot) { shotTime = 0.0f; break; }
                    cutWrapped = true;
                    shotIndex = 0;
                    shotTime = 0.0f;
                    break;
                }
                shotIndex = next;
                shotTime = 0.0f;
                continue;
            }
            if (shotTime <= cap) break;
            shotTime -= cap;
            const int next = shotIndex + 1;
            if (next >= kShotCount) {
                if (holdLastShot) { shotTime = cap; break; }
                cutWrapped = true;
                shotIndex = 0;
                shotTime = 0.0f;
                break;
            }
            shotIndex = next;
        }
    }

    void toggle(Camera3D* camera) {
        enabled = !enabled;
        shotTime = 0.0f;
        paused = false;
        previewMode = false;
        trailerThirdPerson = false;
        cutWrapped = false;
        shotIndex = 0;
        if (enabled) {
            if (camera) camera->fovy = shotFieldOfView(0);
        } else if (camera != nullptr) {
            camera->fovy = 68.0f;
        }
    }

    void stop(Camera3D* camera) {
        enabled = false;
        previewMode = false;
        trailerThirdPerson = false;
        paused = false;
        shotTime = 0.0f;
        shotIndex = 0;
        cutWrapped = false;
        if (camera != nullptr) {
            camera->fovy = 68.0f;
        }
    }

    void startPlay(Camera3D* camera) {
        enabled = true;
        previewMode = false;
        trailerThirdPerson = false;
        paused = false;
        shotIndex = 0;
        shotTime = 0.0f;
        cutWrapped = false;
        if (camera) camera->fovy = shotFieldOfView(0);
    }

    /** Drop preview HUD chrome for a clean take. Keeps pause so you can
     *  SPACE-pause, hit Record/F9, then SPACE-resume into the capture. */
    void keepPlaying() {
        if (!enabled) return;
        previewMode = false;
    }

    void togglePause() { if (enabled) paused = !paused; }

    void startPreview(Camera3D* camera) {
        enabled = true;
        previewMode = true;
        trailerThirdPerson = false;
        paused = true;
        shotIndex = 0;
        shotTime = 0.0f;
        cutWrapped = false;
        if (camera) camera->fovy = shotFieldOfView(0);
    }

    /** Debug probe: land on a shot at a given time, paused, for screenshots. */
    void debugJumpTo(int idx, float t, Camera3D* camera) {
        enabled = true;
        previewMode = true;
        paused = true;
        shotIndex = ((idx % kShotCount) + kShotCount) % kShotCount;
        shotTime = std::max(0.0f, t);
        if (camera) camera->fovy = shotFieldOfView(shotIndex);
    }

    void handlePreviewInput(Camera3D* camera) {
        if (!enabled) return;
        if (IsKeyPressed(KEY_P)) previewMode = !previewMode;
        // Rust-style: character shots default to 1st person; V flips to 3rd.
        if (IsKeyPressed(KEY_V) && isPlayerCharacterShot()) {
            trailerThirdPerson = !trailerThirdPerson;
        }
        // SPACE pauses / resumes the trailer in both Watch and Preview.
        if (IsKeyPressed(KEY_SPACE)) paused = !paused;
        if (IsKeyPressed(KEY_RIGHT) || IsKeyPressed(KEY_RIGHT_BRACKET)) {
            shotIndex = (shotIndex + 1) % kShotCount;
            shotTime = 0.0f;
        }
        if (IsKeyPressed(KEY_LEFT) || IsKeyPressed(KEY_LEFT_BRACKET)) {
            shotIndex = (shotIndex - 1 + kShotCount) % kShotCount;
            shotTime = 0.0f;
        }
        if (previewMode) {
            if (IsKeyDown(KEY_UP)) shotTime = std::min(currentShotDuration() - 0.01f, shotTime + GetFrameTime() * 2.5f);
            if (IsKeyDown(KEY_DOWN)) shotTime = std::max(0.0f, shotTime - GetFrameTime() * 2.5f);
            // Jump to numbered shot with 1-9 / 0 = 10 (preview only)
            for (int k = 0; k <= 9; ++k) {
                if (IsKeyPressed(KEY_ZERO + k)) {
                    const int idx = (k == 0) ? 9 : (k - 1);
                    if (idx < kShotCount) { shotIndex = idx; shotTime = 0.0f; }
                }
            }
        }
        if (camera) camera->fovy = shotFieldOfView(shotIndex);
    }

    bool isEnabled() const { return enabled; }
    bool isPreviewMode() const { return previewMode; }
    bool isPaused() const { return paused; }
    int currentShotIndex() const { return shotIndex; }
    int shotCount() const { return kShotCount; }
    /** True once the last card has elapsed and the cut has looped to shot one. */
    bool cutFinished() const { return cutWrapped; }

    /** Sum of every card duration — the length of one full playthrough. */
    float totalDuration() const {
        float sum = 0.0f;
        for (int i = 0; i < kShotCount; ++i) {
            sum += kCards[static_cast<std::size_t>(i)].duration;
        }
        return sum;
    }

    /** How many captured frames make one full playthrough at `fps`. */
    int totalFrameCount(int fps) const {
        if (fps < 1) fps = 60;
        const int n = static_cast<int>(
            static_cast<double>(totalDuration()) * static_cast<double>(fps) + 0.5);
        // Only guard against a cut with no authored durations at all. This used
        // to fall back to fps * shots * 8 whenever the sum came in under one
        // second per shot, which silently recorded a made-up 176 seconds
        // instead of the cut that was actually written.
        return (n > 0) ? n : (fps * kShotCount);
    }

    float shotProgress() const {
        const float cap = currentShotDuration();
        return cap > 1.0e-4f ? std::min(1.0f, shotTime / cap) : 0.0f;
    }

    float devourerEvolution() const { return card().devourer; }

    /** Gold Mine world.shift — 0 consensus, 1 fully fractured. */
    float realityShiftAmount() const { return enabled ? card().shift : 0.0f; }

    bool isUnmakingShot() const { return enabled && card().cam == Cam::Unmaking; }

    float devourerDim() const {
        return (card().cam == Cam::Unmaking)
            ? std::max(0.0f, 1.0f - shotProgress() * 1.15f)
            : 1.0f;
    }

    int paletteOverride() const {
        if (card().palette != 0) return card().palette;
        if (card().flags & F_MEMORY) return 2;
        return 0;
    }

    bool shouldDrawAlthea() const { return enabled && (card().flags & F_ALTHEA) != 0; }

    /** Which soul-ladder rung the current trailer card is living in.
     *  The cut opens on Angela (First Hands / caveman). Later cards climb. */
    IncarnationEra::Era incarnationEra() const {
        if (!enabled) return IncarnationEra::Era::FirstHands;
        const unsigned f = card().flags;
        const Cam c = card().cam;
        if ((f & F_ALTHEA) != 0
            || c == Cam::Unmaking || c == Cam::ArtificialSun
            || c == Cam::VenusDescent || c == Cam::ShadowDrift)
            return IncarnationEra::Era::Wind;
        if ((f & F_OCEAN) != 0 || c == Cam::CoastSkim)
            return IncarnationEra::Era::Launch;
        if ((f & F_PYRAMIDS) != 0 || c == Cam::Pyramids)
            return IncarnationEra::Era::Soldier;
        if ((f & F_SETTLEMENT) != 0 || (f & F_JUNGLE) != 0
            || (f & F_MARKET) != 0 || (f & F_LAB) != 0)
            return IncarnationEra::Era::Hunt;
        return IncarnationEra::Era::FirstHands;
    }

    float altheaHeal() const {
        if (card().cam == Cam::AltheaRise) return shotProgress() * 0.6f;
        if (card().cam == Cam::Unmaking) return 0.85f + 0.15f * shotProgress();
        return 0.0f;
    }

    bool shouldDrawMysteriousSkyAccents() const {
        return enabled && (card().flags & F_MYSTERY_SKY) != 0;
    }
    bool shouldDrawSettlementProps() const {
        return enabled && (card().flags & F_SETTLEMENT) != 0;
    }
    bool shouldDrawBarterMarket() const {
        return enabled && (card().flags & F_MARKET) != 0;
    }
    bool shouldDrawPyramidsShot() const {
        return enabled && (card().flags & F_PYRAMIDS) != 0;
    }
    bool shouldDrawJungleShot() const {
        return enabled && (card().flags & F_JUNGLE) != 0;
    }
    bool shouldDrawLabShot() const {
        return enabled && (card().flags & F_LAB) != 0;
    }
    bool shouldDrawMemoryShot() const {
        return enabled && (card().flags & F_MEMORY) != 0;
    }
    bool shouldDrawRiftShot() const {
        return enabled && (card().flags & F_RIFT) != 0;
    }
    bool shouldDrawBossFight() const {
        return enabled && (card().flags & F_BOSS) != 0;
    }
    bool shouldDrawOceanShot() const {
        return enabled && ((card().flags & F_OCEAN) != 0 || card().cam == Cam::CoastSkim);
    }
    float shotClock() const { return shotTime; }
    bool isDryStoneShot() const {
        return enabled && card().cam == Cam::ZimWall;
    }
    bool isLabApproachShot() const {
        return enabled && card().cam == Cam::LabApproach;
    }
    /** Her shot happens indoors, so the roof has to come off to let light in. */
    bool isSamanthaShot() const {
        return enabled && card().cam == Cam::SamanthaReveal;
    }
    // The TILT UP has to end inside leaves — it needs a tree directly overhead.
    bool isCanopyTiltShot() const {
        return enabled && card().cam == Cam::CanopyTilt;
    }
    bool isPrimeSavannaShot() const {
        return enabled && (card().flags & F_DAWN) != 0;
    }
    bool shouldDrawDistantSilhouettes() const {
        return enabled && (card().flags & F_SILHOUETTE) != 0;
    }

    // Gold Mine savanna-tree DETAIL: frame ONE acacia on the ground — never empty sky.
    bool isAcaciaDetailShot() const {
        return enabled && card().cam == Cam::AcaciaTilt;
    }

    /** Angela chops the hero acacia, hauls a log, hammers Savanawork bench.glb. */
    bool isAngelaCraftShot() const {
        return enabled && card().cam == Cam::AngelaCraft;
    }

    /** Shots that put a playable vessel on screen (Rust-style POV candidates). */
    bool isPlayerCharacterShot() const {
        return isAngelaCraftShot() || shouldDrawAlthea() || shouldDrawBossFight();
    }

    /** Character shots default to 1st person; V toggles 3rd (body in frame). */
    bool trailerThirdPersonView() const { return trailerThirdPerson; }
    bool trailerFirstPersonView() const {
        return isPlayerCharacterShot() && !trailerThirdPerson;
    }
    /** Draw the vessel body only in 3rd person on character shots. */
    bool showTrailerCharacterBody() const {
        return !isPlayerCharacterShot() || trailerThirdPerson;
    }

    // Scenery-only clips (camera movement + world, no humanoid characters).
    bool isCleanSceneryShot() const {
        return enabled && card().clean;
    }

    // The hero acacia, as an offset from the savanna anchor. One constant for
    // the model, its path blocker, the giraffe keep-out, the companion NPCs and
    // the camera — they were four copies of the same two literals, and the
    // camera's copy was measured from the wrong origin.
    static constexpr float kHeroAcaciaDX = 11.0f;
    static constexpr float kHeroAcaciaDZ = 13.0f;

    /** Where the savanna set was actually built. The trailer plays from
     *  wherever the player is standing, so anything the camera has to frame
     *  must be pinned to the world instead. */
    void setSavannaAnchor(float x, float z) {
        savannaAnchorX = x;
        savannaAnchorZ = z;
        savannaAnchorSet = true;
    }

    Vector3 acaciaHeroWorld(const Vec3& playerPos, EnhancedAfricanTerrain& terrainSystem) const {
        // Pinned to the anchor, not the player. Measuring from playerPos drew
        // the hero acacia wherever you happened to be standing when you opened
        // the trailer, while its collision, its giraffe keep-out and its four
        // companion NPCs stayed back at the spawn — so the tree slid off its
        // own footprint and moved between viewings. Same fix jungleHeroWorld
        // already carries for the Congo shots.
        const float baseX = savannaAnchorSet ? savannaAnchorX : playerPos.x;
        const float baseZ = savannaAnchorSet ? savannaAnchorZ : playerPos.z;
        const float x = baseX + kHeroAcaciaDX;
        const float z = baseZ + kHeroAcaciaDZ;
        return {x, terrainSystem.getHeight(x, z), z};
    }

    // The three acacias the wide dawn shots guarantee in frame, as offsets from
    // the same anchor their blockers use.
    struct AcaciaOffset { float dx; float dz; };
    static constexpr AcaciaOffset kDawnAcacias[] = {
        {18.0f, 22.0f},
        {42.0f,  8.0f},
        {-8.0f, 36.0f},
    };
    static constexpr int kDawnAcaciaCount =
        static_cast<int>(sizeof(kDawnAcacias) / sizeof(kDawnAcacias[0]));

    /**
     * Dawn hero acacia i. These used to be measured from camera.target, which
     * pans 10 m across the DawnRise push-in — so all three drifted over the
     * ground for the length of the shot, and none of them stood where their
     * blockers were. Off the anchor they are the trees the world already has.
     */
    Vector3 dawnAcaciaWorld(int i, const Vec3& playerPos,
                            EnhancedAfricanTerrain& terrainSystem) const {
        const AcaciaOffset& o = kDawnAcacias[(i % kDawnAcaciaCount + kDawnAcaciaCount)
                                             % kDawnAcaciaCount];
        const float baseX = savannaAnchorSet ? savannaAnchorX : playerPos.x;
        const float baseZ = savannaAnchorSet ? savannaAnchorZ : playerPos.z;
        const float x = baseX + o.dx;
        const float z = baseZ + o.dz;
        return {x, terrainSystem.getHeight(x, z), z};
    }

    /**
     * Base of the guaranteed jungle tree the Congo shots frame. Anchored to
     * the forest itself, not the player — the old shots used playerPos and so
     * played wherever the player happened to be standing, which was savanna.
     */
    Vector3 jungleHeroWorld(const Vec3& playerPos, EnhancedAfricanTerrain& terrainSystem) const {
        float jx = 0.0f, jz = 0.0f;
        jungleFieldXZ(playerPos, &jx, &jz);
        const float x = jx + 6.0f;
        const float z = jz - 4.0f;
        return {x, terrainSystem.getHeight(x, z), z};
    }

    /**
     * Where the artificial sun hangs. Shared by the camera and the draw call
     * so the shot cannot end up framing empty sky.
     */
    static constexpr float kArtificialSunRadius = 420.0f;
    static Vector3 artificialSunWorld(const Vec3& playerPos,
                                      EnhancedAfricanTerrain& terrainSystem) {
        const float gy = terrainSystem.getHeight(playerPos.x, playerPos.z);
        return {playerPos.x + 60.0f, gy + 2100.0f, playerPos.z + 1900.0f};
    }

    /** Eyes of the vessel for Rust-style 1st person character shots. */
    void applyTrailerFirstPersonCamera(const Vec3& playerPos,
                                       EnhancedAfricanTerrain& terrainSystem,
                                       Camera3D* camera,
                                       float te) const {
        if (camera == nullptr) return;
        const float py = terrainSystem.getHeight(playerPos.x, playerPos.z);

        if (isAngelaCraftShot()) {
            const Vector3 hero = acaciaHeroWorld(playerPos, terrainSystem);
            const float tRaw = shotProgress();
            Vector3 ang = AngelaCraftSet::angelaWorld(tRaw, hero);
            ang.y = terrainSystem.getHeight(ang.x, ang.z);
            const float yawDeg = AngelaCraftSet::angelaYawDeg(tRaw, hero, ang);
            const float yaw = yawDeg * (3.14159265f / 180.0f);
            // Eye height — short of Althea float; Angela is on her feet.
            const float eyeY = ang.y + 1.58f;
            camera->position = {ang.x, eyeY, ang.z};
            if (tRaw < 0.58f) {
                // Chop: stare into the trunk she is working.
                float lookY = hero.y + 1.35f + te * 0.4f;
                // Rust hit punch — camera kicks when the bit bites the wood.
                const float bite = AngelaCraftSet::axeBite01(tRaw);
                if (bite > 0.2f) {
                    const float kick = (bite < 0.6f ? bite : (1.0f - (bite - 0.6f) / 0.4f)) * 0.12f;
                    camera->position.y -= kick * 0.35f;
                    lookY -= kick * 0.55f;
                    camera->position.x += std::sin(yaw) * kick * 0.25f;
                    camera->position.z += std::cos(yaw) * kick * 0.25f;
                }
                camera->target = {hero.x, lookY, hero.z};
            } else if (tRaw < 0.74f) {
                // Haul: look along the walk toward the craft pad.
                camera->target = {
                    ang.x + std::sin(yaw) * 4.5f,
                    eyeY - 0.15f,
                    ang.z + std::cos(yaw) * 4.5f
                };
            } else {
                // Hammer / bench: step OFF the tabletop. Looking straight down
                // from her eyes buried the whole frame in pegboard planks.
                const Vector3 pad = {hero.x + 2.6f, ang.y, hero.z - 0.2f};
                const float padY = terrainSystem.getHeight(pad.x, pad.z);
                const float side = 0.85f;
                const float back = 1.55f;
                camera->position = {
                    pad.x - std::sin(yaw) * back + std::cos(yaw) * side,
                    padY + 1.48f,
                    pad.z - std::cos(yaw) * back - std::sin(yaw) * side
                };
                // Aim at mid-bench so legs + top + shelf all read.
                camera->target = {pad.x, padY + 0.55f, pad.z};
            }
            return;
        }

        if (shouldDrawBossFight()) {
            // Eyes on the Distortor's head — fight reads as hands vs serpent.
            const Vector3 ground {playerPos.x, py, playerPos.z};
            // Approximate arena head without Devourer access: upward look along
            // the authored orbit the 3rd-person shot already used.
            const float ang = 0.55f + te * 0.95f;
            const float lookX = playerPos.x + std::cos(ang + 3.14159265f) * 18.0f;
            const float lookZ = playerPos.z + std::sin(ang + 3.14159265f) * 18.0f;
            camera->position = {playerPos.x, py + 2.55f, playerPos.z};
            camera->target = {lookX, py + 9.0f + te * 4.0f, lookZ};
            (void)ground;
            return;
        }

        if (shouldDrawAlthea()) {
            // Windspeaker eye line — tall vessel, look into the dusk field.
            camera->position = {playerPos.x, py + 2.65f + te * 0.35f, playerPos.z};
            camera->target = {
                playerPos.x + 10.0f + te * 6.0f,
                py + 2.4f + te * 1.8f,
                playerPos.z + 14.0f + te * 4.0f
            };
        }
    }

    void applyCamera(const Vec3& playerPos, EnhancedAfricanTerrain& terrainSystem, Camera3D* camera) const {
        if (!enabled || camera == nullptr) return;

        const float t = shotProgress();
        const float phase = t * 2.0f * kPi;
        // Ease for slower, more cinematic moves
        const float te = t * t * (3.0f - 2.0f * t);

        float mainVx = 0.0f, mainVz = 0.0f;
        showcaseMainVillageXZ(playerPos, &mainVx, &mainVz);
        float hiddenHx = 0.0f, hiddenHz = 0.0f;
        showcaseHiddenCampXZ(playerPos, &hiddenHx, &hiddenHz);
        float px = 0.0f, pz = 0.0f;
        nubianPyramidFieldXZ(playerPos, &px, &pz);
        float lx = 0.0f, lz = 0.0f;
        labFieldXZ(playerPos, &lx, &lz);

        const float py = terrainSystem.getHeight(playerPos.x, playerPos.z);
        const float vy = terrainSystem.getHeight(mainVx, mainVz);
        const float hy = terrainSystem.getHeight(hiddenHx, hiddenHz);
        const float fy = terrainSystem.getHeight(px, pz);
        const float ly = terrainSystem.getHeight(lx, lz);

        switch (card().cam) {
            case Cam::DawnRise: {
                // Cold open: dolly forward into the distance toward the sun /
                // long grass — Rust establishing move, not a lateral truck.
                const float push = te * 56.0f;
                camera->position = {
                    playerPos.x - 12.0f + push * 0.78f,
                    py + 15.5f - te * 4.0f,
                    playerPos.z - 44.0f + push * 0.62f
                };
                camera->target = {
                    playerPos.x + 42.0f + push * 1.05f,
                    py + 2.0f + te * 1.0f,
                    playerPos.z + 48.0f + push * 0.80f
                };
                break;
            }
            case Cam::WideHold: {
                // Almost static wide — sell the world
                camera->target = {playerPos.x + te * 6.0f, py + 5.0f, playerPos.z + te * 4.0f};
                camera->position = {playerPos.x + 110.0f, py + 42.0f, playerPos.z - 120.0f};
                break;
            }
            case Cam::AcaciaTilt: {
                // Stay on the tree: look mid-trunk → upper canopy (~8.5m tall), not sky.
                // te on XZ was 1.2 / 0.8 — that dollied the camera and the
                // trunk walked. 0, like CanopyTilt: tilt only.
                const Vector3 hero = acaciaHeroWorld(playerPos, terrainSystem);
                const float hy = hero.y;
                camera->target = {
                    hero.x,
                    hy + 3.2f + te * 4.0f,
                    hero.z
                };
                camera->position = {
                    hero.x - 7.5f,
                    hy + 2.4f + te * 2.2f,
                    hero.z - 5.5f
                };
                break;
            }
            case Cam::WalkFp: {
                const float crawl = te * 28.0f;
                camera->target = {playerPos.x + 18.0f + crawl, py + 1.6f, playerPos.z + 18.0f + crawl * 0.7f};
                camera->position = {playerPos.x + crawl * 0.85f, py + 1.55f, playerPos.z + crawl * 0.55f};
                break;
            }
            case Cam::AngelaCraft: {
                // Over Angela's shoulder while she works the hero tree. Camera
                // height follows her feet — using the tree base alone put the
                // lens underground on a slope and she read as rising out of dirt.
                const Vector3 hero = acaciaHeroWorld(playerPos, terrainSystem);
                const float tRaw = shotProgress();
                Vector3 ang = AngelaCraftSet::angelaWorld(tRaw, hero);
                ang.y = terrainSystem.getHeight(ang.x, ang.z);
                const float fall = AngelaCraftSet::treeFallDeg(tRaw);
                if (tRaw < 0.42f) {
                    camera->target = {hero.x, hero.y + 2.2f, hero.z};
                    camera->position = {
                        ang.x - 2.8f,
                        ang.y + 1.55f,
                        ang.z - 3.6f
                    };
                } else if (tRaw < 0.62f) {
                    const float u = (tRaw - 0.42f) / 0.20f;
                    camera->target = {
                        hero.x + fall * 0.04f,
                        hero.y + 2.8f - u * 1.4f,
                        hero.z
                    };
                    camera->position = {
                        hero.x - 6.5f - u * 2.5f,
                        std::max(ang.y + 1.4f, hero.y + 3.2f + u * 1.5f),
                        hero.z - 7.5f - u * 1.5f
                    };
                } else {
                    // Craft pad: pull back so Savanawork bench.glb reads as a
                    // full table (legs + top), not a wood slab filling the lens.
                    const Vector3 pad = {hero.x + 2.6f, ang.y, hero.z - 0.2f};
                    const float padY = terrainSystem.getHeight(pad.x, pad.z);
                    camera->target = {pad.x, padY + 0.58f, pad.z};
                    camera->position = {
                        pad.x - 3.8f,
                        padY + 2.15f,
                        pad.z - 4.6f
                    };
                }
                break;
            }
            case Cam::CloseGrass: {
                const float crawl = te * 6.0f;
                camera->target = {playerPos.x + 4.0f + crawl, py + 0.55f, playerPos.z + 1.5f};
                camera->position = {playerPos.x + crawl * 0.4f, py + 0.42f, playerPos.z - 1.2f};
                break;
            }
            case Cam::LowWater: {
                // "The Watering Hole" — seek the nearest real water (terrain
                // below the water plane) once per shot and frame it, instead
                // of hoping the grass in front of the player happens to be wet.
                if (waterSeekShot != shotIndex) {
                    waterSeekShot = shotIndex;
                    waterFound = false;
                    for (float r = 24.0f; r <= 900.0f && !waterFound; r += 14.0f) {
                        for (int k = 0; k < 20; ++k) {
                            const float a = (static_cast<float>(k) / 20.0f) * 2.0f * kPi + r * 0.05f;
                            const float wx = playerPos.x + std::cos(a) * r;
                            const float wz = playerPos.z + std::sin(a) * r;
                            const float wl = 1.0f + std::sin((wx + wz) * 0.02f) * 0.2f;
                            if (terrainSystem.getHeight(wx, wz) <= wl - 0.05f) {
                                waterX = wx;
                                waterZ = wz;
                                waterFound = true;
                                break;
                            }
                        }
                    }
                }
                if (waterFound) {
                    const float wl = 1.0f + std::sin((waterX + waterZ) * 0.02f) * 0.2f;
                    float dirX = waterX - playerPos.x;
                    float dirZ = waterZ - playerPos.z;
                    const float dl = std::max(1.0f, std::sqrt(dirX * dirX + dirZ * dirZ));
                    dirX /= dl;
                    dirZ /= dl;
                    // Low skim from the shore out over the water.
                    const float backD = 20.0f - te * 8.0f;
                    const float posX = waterX - dirX * backD;
                    const float posZ = waterZ - dirZ * backD;
                    const float shoreY = terrainSystem.getHeight(posX, posZ);
                    camera->target = {waterX + dirX * (6.0f + te * 12.0f), wl + 0.7f,
                                      waterZ + dirZ * (6.0f + te * 12.0f)};
                    camera->position = {posX, std::max(wl + 1.4f, shoreY + 1.2f), posZ};
                } else {
                camera->target = {playerPos.x + 24.0f + te * 10.0f, py + 0.8f, playerPos.z + 8.0f};
                camera->position = {playerPos.x + 4.0f + te * 14.0f, py + 1.1f, playerPos.z + 18.0f};
                }
                break;
            }
            case Cam::LateralWide: {
                camera->target = {playerPos.x + te * 40.0f, py + 4.0f, playerPos.z};
                camera->position = {playerPos.x - 20.0f + te * 40.0f, py + 28.0f, playerPos.z - 95.0f};
                break;
            }
            case Cam::ZimCrane: {
                camera->target = {mainVx, vy + 8.0f, mainVz};
                camera->position = {mainVx + 48.0f - te * 18.0f, vy + 18.0f - te * 7.0f, mainVz + 44.0f + te * 4.0f};
                break;
            }
            case Cam::ZimWall: {
                const float wallAng = 0.6f + te * 1.6f;
                const float wr = 34.0f;
                camera->target = {mainVx + std::cos(wallAng) * wr, vy + 5.5f, mainVz + std::sin(wallAng) * wr};
                camera->position = {mainVx + std::cos(wallAng - 0.5f) * (wr + 20.0f), vy + 7.5f,
                                    mainVz + std::sin(wallAng - 0.5f) * (wr + 20.0f)};
                break;
            }
            case Cam::ZimGap: {
                const float gapAng = 4.8f;
                const float push = te * 26.0f;
                camera->target = {mainVx + std::cos(gapAng) * (30.0f - push * 0.35f), vy + 3.0f,
                                  mainVz + std::sin(gapAng) * (30.0f - push * 0.35f)};
                camera->position = {mainVx + std::cos(gapAng) * (44.0f - push), vy + 2.3f,
                                    mainVz + std::sin(gapAng) * (44.0f - push)};
                break;
            }
            case Cam::VillageEdge: {
                camera->target = {mainVx, vy + 3.0f, mainVz};
                camera->position = {mainVx - 28.0f + te * 8.0f, vy + 4.2f, mainVz - 22.0f + te * 6.0f};
                break;
            }
            case Cam::ForestWalk: {
                // Walk through the Congo set itself rather than past the
                // player, who is nowhere near the forest.
                const Vector3 hero = jungleHeroWorld(playerPos, terrainSystem);
                const float crawl = te * 22.0f;
                camera->target = {hero.x + 18.0f + crawl, hero.y + 2.4f, hero.z + 14.0f + crawl};
                camera->position = {hero.x - 10.0f + crawl * 0.7f, hero.y + 2.0f,
                                    hero.z - 8.0f + crawl * 0.55f};
                break;
            }
            case Cam::CanopyTilt: {
                // Was targeting playerPos + 32 m over open savanna, where the
                // tallest thing in the game is an 8.5 m acacia — so the tilt
                // ended in bare sky. Anchor on a real jungle tree and stop at
                // its crown, the same fix AcaciaTilt already uses.
                const Vector3 hero = jungleHeroWorld(playerPos, terrainSystem);
                const float top = JungleTreeRenderer::kTargetHeight;
                camera->target = {hero.x, hero.y + 3.0f + te * (top - 3.0f), hero.z};
                camera->position = {hero.x - 4.5f, hero.y + 1.7f + te * 1.4f, hero.z - 3.2f};
                break;
            }
            case Cam::Pyramids: {
                camera->target = {px + 8.0f, fy + 18.0f, pz + 4.0f};
                camera->position = {px - 100.0f + te * 28.0f, fy + 22.0f + te * 24.0f, pz - 78.0f + te * 18.0f};
                break;
            }
            case Cam::LabApproach: {
                // Creep down the south door onto Samantha. The old look sat
                // 34 m out aimed at the building centre, so she (inside, roof
                // on) never made the frame.
                const float doorZ = lz - 6.1f;
                camera->target = {lx, ly + 1.55f, doorZ};
                camera->position = {lx,
                                    ly + 2.15f - te * 0.35f,
                                    lz - 20.0f + te * 10.0f};
                break;
            }
            case Cam::SamanthaReveal: {
                // Push through the partition gap onto her. The camera holds
                // inside the 2.5 m gap (x +3.75..+6.25) until it is north of
                // the partition at z +1.25, and only then swings west onto
                // her — swing any earlier and the move clips straight through
                // the solid half of the partition.
                //
                // The hold sits at +5.7 rather than mid-gap, and the approach
                // starts close. She stands at the west end of the chamber, so
                // the gap works like a slit: from further south or further
                // west she is behind the wall. Hugging the east jamb buys the
                // sight line early and puts the reveal at about a third in,
                // instead of two thirds of the shot aimed at an empty room.
                const float pass = std::max(0.0f, (te - 0.72f) / 0.28f);
                const float ps = pass * pass * (3.0f - 2.0f * pass);
                camera->position = {lx + 5.7f - ps * 2.9f,
                                    ly + 1.70f - te * 0.12f,
                                    lz - 1.4f + te * 4.0f};
                camera->target = {lx + 5.7f - ps * 5.7f,
                                  ly + 1.50f,
                                  lz + 3.4f + ps * 0.85f};
                break;
            }
            case Cam::VenusDescent: {
                // Arrival, not a flyover: drop out of the haze onto the rock.
                // Stays low at the end because the fog only shows ~300 m, so
                // height just buys more orange.
                camera->position = {playerPos.x - 14.0f + te * 12.0f,
                                    py + 88.0f - te * 68.0f,
                                    playerPos.z - 120.0f + te * 58.0f};
                camera->target = {playerPos.x + 26.0f,
                                  py + 9.0f + (1.0f - te) * 26.0f,
                                  playerPos.z + 46.0f};
                break;
            }
            case Cam::ArtificialSun: {
                // Lamp is the hero. Earth sits low on the horizon as context —
                // never fill the frame with Earth first.
                const Vector3 s = artificialSunWorld(playerPos, terrainSystem);
                camera->target = {s.x, s.y - 40.0f, s.z};
                camera->position = {
                    s.x - 980.0f + te * 220.0f,
                    s.y - 180.0f + te * 90.0f,
                    s.z - 720.0f + te * 160.0f
                };
                break;
            }
            case Cam::DesertPan: {
                camera->target = {px + te * 20.0f, fy + 10.0f, pz};
                camera->position = {px - 60.0f + te * 20.0f, fy + 14.0f, pz - 55.0f};
                break;
            }
            case Cam::CoastSkim: {
                // Infinite Tempest Sea skim — low flight over black swells, no land.
                const float run = te * 95.0f;
                const float ox = playerPos.x + 2400.0f; // park the shot far from spawn biomes
                const float oz = playerPos.z - 1800.0f;
                camera->position = {ox - 40.0f + run, 9.5f + std::sin(te * 2.2f) * 0.6f, oz + 28.0f};
                camera->target = {ox + 55.0f + run, 2.2f + te * 0.8f, oz + 10.0f};
                break;
            }
            case Cam::MemorySlow: {
                // Slow push into the south arches — close enough that Wall.glb
                // reads as a house, not a distant block pile.
                camera->target = {hiddenHx, hy + 8.5f + te * 5.0f, hiddenHz - 8.0f};
                camera->position = {hiddenHx - 4.0f, hy + 5.5f + te * 3.5f,
                                    hiddenHz - 34.0f + te * 10.0f};
                break;
            }
            case Cam::MemoryClose: {
                camera->target = {hiddenHx, hy + 6.5f, hiddenHz};
                camera->position = {hiddenHx - 3.0f + te * 2.0f, hy + 4.2f,
                                    hiddenHz - 22.0f + te * 5.0f};
                break;
            }
            case Cam::MemoryWide: {
                const float ox = std::cos(phase * 0.35f) * 88.0f;
                const float oz = std::sin(phase * 0.35f) * 88.0f;
                camera->target = {hiddenHx, hy + 20.0f, hiddenHz};
                camera->position = {hiddenHx + ox, hy + 48.0f, hiddenHz + oz};
                break;
            }
            case Cam::Simulation: {
                camera->target = {hiddenHx, hy + 7.0f + te * 4.0f, hiddenHz - 2.0f};
                camera->position = {hiddenHx - 5.0f, hy + 4.0f + te * 3.0f,
                                    hiddenHz - 32.0f + te * 12.0f};
                break;
            }
            case Cam::MarketWalk: {
                camera->target = {mainVx + te * 16.0f, vy + 3.5f, mainVz + te * 8.0f};
                camera->position = {mainVx - 22.0f + te * 20.0f, vy + 5.5f - te * 1.2f, mainVz - 22.0f + te * 20.0f};
                break;
            }
            case Cam::NightDescend: {
                camera->target = {playerPos.x, py + 1.5f, playerPos.z + 8.0f};
                camera->position = {playerPos.x, py + 38.0f - te * 28.0f, playerPos.z - 24.0f + te * 18.0f};
                break;
            }
            case Cam::LightsUnder: {
                camera->target = {playerPos.x + te * 6.0f, py + 0.3f, playerPos.z + te * 4.0f};
                camera->position = {playerPos.x - 2.0f + te * 4.0f, py + 1.8f, playerPos.z - 6.0f};
                break;
            }
            case Cam::RiftPass: {
                // world.ts genRift keys, 1 block = 1 m, origin at the seam.
                // {110,42,30} look {64,26,70} → {96,32,60} look {62,24,76}.
                float rx = 0.0f, rz = 0.0f;
                riftSeamXZ(&rx, &rz);
                const float gy = terrainSystem.getHeight(rx, rz);
                camera->position = {
                    rx + 46.0f - te * 14.0f,
                    gy + 24.0f - te * 10.0f,
                    rz - 34.0f + te * 30.0f
                };
                camera->target = {
                    rx - te * 2.0f,
                    gy + 8.0f - te * 2.0f,
                    rz + 6.0f + te * 6.0f
                };
                break;
            }
            case Cam::ShadowDrift: {
                camera->target = {playerPos.x + 30.0f, py + 12.0f - te * 8.0f, playerPos.z + 40.0f};
                camera->position = {playerPos.x + 8.0f + te * 14.0f, py + 22.0f - te * 10.0f, playerPos.z + 8.0f + te * 14.0f};
                break;
            }
            case Cam::Obelisk: {
                const float angle = 1.15f + te * 0.55f;
                const float ox = playerPos.x + std::cos(angle) * 200.0f;
                const float oz = playerPos.z + std::sin(angle) * 200.0f;
                const float peakY = terrainSystem.getHeight(ox, oz) + 29.0f;
                camera->target = {ox, peakY, oz};
                const float bx = playerPos.x + std::cos(angle + 2.71f) * 50.0f;
                const float bz = playerPos.z + std::sin(angle + 2.71f) * 50.0f;
                camera->position = {bx, terrainSystem.getHeight(bx, bz) + 14.0f, bz};
                break;
            }
            case Cam::MysteryLow: {
                camera->target = {playerPos.x + 14.0f, py + 10.0f, playerPos.z + 20.0f};
                camera->position = {playerPos.x - 5.0f, py + 0.9f + te * 0.4f, playerPos.z - 4.0f};
                break;
            }
            case Cam::AltheaRise: {
                camera->target = {playerPos.x, py + 2.4f + te * 2.0f, playerPos.z};
                camera->position = {playerPos.x + 18.0f - te * 8.0f, py + 3.5f, playerPos.z - 22.0f + te * 10.0f};
                break;
            }
            case Cam::Unmaking: {
                const float k = te;
                const float ang = 1.6f + te * 0.9f;
                const float rad = 70.0f - k * 48.0f;
                camera->target = {playerPos.x, py + 2.6f + (1.0f - k) * 6.0f, playerPos.z};
                camera->position = {playerPos.x + std::cos(ang) * rad, py + 32.0f - k * 24.0f,
                                    playerPos.z + std::sin(ang) * rad};
                break;
            }
            case Cam::DistortorFight: {
                // Orbit the Windspeaker; keep the Distortor's loop in the upper
                // third so the fight reads as player-vs-serpent, not sky wallpaper.
                const float ang = 0.55f + te * 0.95f;
                const float rad = 26.0f - te * 7.0f;
                camera->position = {
                    playerPos.x + std::cos(ang) * rad,
                    py + 5.2f + te * 4.5f,
                    playerPos.z + std::sin(ang) * rad
                };
                camera->target = {playerPos.x, py + 6.5f + te * 3.0f, playerPos.z};
                break;
            }
            case Cam::BasinSkim: {
                const float run = te * 95.0f;
                const float gx = playerPos.x - 45.0f + run;
                const float gz = playerPos.z + 24.0f;
                const float gy = terrainSystem.getHeight(gx, gz);
                camera->position = {gx, gy + 3.0f, gz};
                camera->target = {gx + 32.0f, gy + 2.0f, gz - 4.0f};
                break;
            }
            case Cam::FinalWide: {
                camera->target = {playerPos.x, py + 5.0f, playerPos.z};
                camera->position = {playerPos.x + 70.0f - te * 10.0f, py + 36.0f, playerPos.z - 90.0f + te * 12.0f};
                break;
            }
            case Cam::CreditsOrbit:
            default: {
                const float ox = std::cos(phase * 0.28f) * 100.0f;
                const float oz = std::sin(phase * 0.28f) * 100.0f;
                camera->target = {playerPos.x, py + 4.0f, playerPos.z};
                camera->position = {playerPos.x + ox, py + 48.0f, playerPos.z + oz};
                break;
            }
        }

        // Rust-style: character shots default to eyes / hands, not a dolly around the body.
        if (trailerFirstPersonView()) {
            applyTrailerFirstPersonCamera(playerPos, terrainSystem, camera, te);
        }

        camera->fovy = trailerFirstPersonView()
            ? std::max(shotFieldOfView(shotIndex), 72.0f)
            : shotFieldOfView(shotIndex);
    }

    /** Watch-the-trailer overlay. Returns true if RECORD was clicked.
     *  `hideChrome` drops Record / scrub UI so cards land clean in the MP4. */
    bool drawShotCard(const Font& serif, const Font& mono, int sw, int sh,
                      bool hideChrome = false) {
        if (!enabled) return false;
        const ShotCard& c = card();

        const float ui = std::max(0.65f, std::min(sh / 900.0f, 1.5f));
        const float dur = currentShotDuration();
        float a = 1.0f;
        if (!previewMode) {
            if (shotTime < 0.55f) a = shotTime / 0.55f;
            else if (shotTime > dur - 0.85f) a = std::max(0.0f, (dur - shotTime) / 0.85f);
        }

        const ::Color cream {245, 230, 200, 255};
        const ::Color brown {138, 115, 85, 255};
        const Font& nameFont = (serif.texture.id > 0) ? serif : GetFontDefault();
        const Font& metaFont = (mono.texture.id > 0) ? mono : GetFontDefault();

        // Marketing cut (Rust-style): big red feature banner, almost no chrome.
        // Preview/scrub keeps the dense lore cards for directing — except during
        // the Rem Studios cold-open beat, which must read like the Steam cut.
        const bool marketing = !previewMode;
        const bool studioBeat = (shotIndex == 0 && card().cam == Cam::DawnRise
                                 && shotTime < 4.40f);
        drawStudioCredit(nameFont, metaFont, sw, sh, a, ui);
        if (marketing) {
            drawMarketingBanner(nameFont, metaFont, sw, sh, a, ui);
        } else if (!studioBeat) {
            // Always name the place
            {
                const float px = 36.0f * ui;
                const float py = 28.0f * ui;
                DrawRectangleRec({px, py, 34.0f * ui, 2.0f * ui}, Fade(c.dimColor, a));
                DrawTextEx(metaFont, "LOCATION", {px, py + 8.0f * ui}, 9.0f * ui, 2.0f, Fade(c.dimColor, 0.95f * a));
                DrawTextEx(nameFont, c.location, {px, py + 22.0f * ui}, 18.0f * ui, 1.0f, Fade(cream, a));
                if (c.era[0] != '\0') {
                    DrawTextEx(metaFont, c.era, {px, py + 44.0f * ui}, 10.0f * ui, 1.5f, Fade(brown, 0.92f * a));
                }
            }

            {
                const float x = 42.0f * ui;
                float y = static_cast<float>(sh) - 196.0f * ui;
                DrawRectangleRec({x, y, 46.0f * ui, 3.0f * ui}, Fade(c.dimColor, a));
                y += 12.0f * ui;

                const float metaSize = 10.0f * ui;
                DrawTextEx(metaFont, c.shotType, {x, y}, metaSize, metaSize * 0.3f, Fade(cream, 0.7f * a));
                float mx = x + MeasureTextEx(metaFont, c.shotType, metaSize, metaSize * 0.3f).x + 12.0f * ui;
                DrawTextEx(metaFont, c.dimension, {mx, y}, metaSize, metaSize * 0.3f, Fade(c.dimColor, a));
                mx += MeasureTextEx(metaFont, c.dimension, metaSize, metaSize * 0.3f).x + 12.0f * ui;
                if (c.alpha) {
                    const Vector2 am = MeasureTextEx(metaFont, "ALPHA", metaSize * 0.85f, 2.0f);
                    const Rectangle chip {mx, y - 2.0f * ui, am.x + 10.0f * ui, am.y + 5.0f * ui};
                    DrawRectangleRec(chip, Fade(::Color {79, 208, 255, 255}, 0.08f * a));
                    DrawRectangleLinesEx(chip, 1.0f, Fade(::Color {79, 208, 255, 255}, 0.4f * a));
                    DrawTextEx(metaFont, "ALPHA", {chip.x + 5.0f * ui, chip.y + 2.5f * ui},
                               metaSize * 0.85f, 2.0f, Fade(::Color {79, 208, 255, 255}, a));
                }
                y += metaSize + 8.0f * ui;

                const float nameSize = 26.0f * ui;
                DrawTextEx(nameFont, c.name, {x, y}, nameSize, nameSize * 0.06f, Fade(cream, a));
                y += nameSize + 6.0f * ui;

                std::string where = c.location;
                if (c.era[0] != '\0') { where += "  —  "; where += c.era; }
                DrawTextEx(metaFont, where.c_str(), {x, y}, 10.0f * ui, 1.5f, Fade(brown, 0.9f * a));
                y += 10.0f * ui + 9.0f * ui;

                if (c.description[0] != '\0') {
                    y += drawWrappedCard(metaFont, c.description, x, y,
                                         std::min(560.0f * ui, sw * 0.6f), 11.0f * ui, Fade(cream, 0.72f * a));
                }

                if (c.concussion != nullptr && c.concussion[0] != '\0') {
                    y += 6.0f * ui;
                    std::string line = "CONCUSSION — ";
                    line += c.concussion;
                    DrawTextEx(metaFont, line.c_str(), {x, y}, 9.5f * ui, 2.0f, Fade(c.dimColor, 0.9f * a));
                }
            }
            drawProgressionHud(nameFont, metaFont, sw, sh, a, ui, hideChrome);
        }

        // Record button sits top-right. Hidden while capturing.
        // During the studio cold-open, drop directing chrome so it reads like Steam.
        bool recordClicked = false;
        if (!hideChrome) {
            const float bw = 290.0f * ui;
            const float bh = 52.0f * ui;
            const Rectangle rec {static_cast<float>(sw) - 28.0f * ui - bw, 22.0f * ui, bw, bh};
            const Vector2 mouse = GetMousePosition();
            const bool hover = CheckCollisionPointRec(mouse, rec);
            const ::Color recRed {220, 48, 48, 255};
            DrawRectangleRec(rec, hover ? ::Color {48, 14, 16, 230} : ::Color {22, 10, 12, 210});
            DrawRectangleLinesEx(rec, 2.0f, hover ? recRed : Fade(recRed, 0.70f));
            DrawCircle(static_cast<int>(rec.x + 18.0f * ui),
                       static_cast<int>(rec.y + bh * 0.5f),
                       7.0f * ui, recRed);
            DrawTextEx(nameFont, "RECORD",
                       {rec.x + 36.0f * ui, rec.y + 8.0f * ui},
                       16.0f * ui, 1.0f, cream);
            DrawTextEx(metaFont, paused
                           ? "CLICK / ENTER / F9  ·  START FROM PAUSE"
                           : "CLICK / ENTER / F9  ·  MP4  (SPACE pause first OK)",
                       {rec.x + 36.0f * ui, rec.y + 30.0f * ui},
                       9.0f * ui, 1.5f, Fade(brown, hover ? 1.0f : 0.85f));
            if (hover && IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) recordClicked = true;

            if (!studioBeat) {
                DrawTextEx(metaFont, "ESC  TITLE",
                           {static_cast<float>(sw) - 120.0f * ui, 80.0f * ui},
                           10.0f * ui, 2.0f, Fade(c.dimColor, 0.75f * a));
                {
                    char ver[48];
                    std::snprintf(ver, sizeof(ver), "%s  %s",
                                  InertiaTitleScreen::kStageLabel, InertiaTitleScreen::kBuildVersion);
                    const Vector2 vm = MeasureTextEx(metaFont, ver, 10.0f * ui, 2.0f);
                    DrawTextEx(metaFont, ver,
                               {static_cast<float>(sw) - vm.x - 36.0f * ui, 96.0f * ui},
                               10.0f * ui, 2.0f, Fade(::Color {255, 64, 96, 255}, 0.85f * a));
                }
                if (previewMode) drawPreviewHud(metaFont, nameFont, sw, sh);
            }
            DrawTextEx(metaFont, paused ? "SPACE  RESUME" : "SPACE  PAUSE",
                       {36.0f * ui, static_cast<float>(sh) - 36.0f * ui},
                       12.0f * ui, 2.0f,
                       paused ? ::Color {255, 220, 120, 255} : Fade(cream, 0.85f * a));
        }

        // Watch The Trailer — big pause stamp (Preview already has its own HUD).
        if (paused && !previewMode && !hideChrome) {
            DrawRectangle(0, 0, sw, sh, ::Color {0, 0, 0, 90});
            const char* pauseLabel = "PAUSED";
            const float ps = 42.0f * ui;
            const Vector2 pm = MeasureTextEx(nameFont, pauseLabel, ps, 2.0f);
            DrawTextEx(nameFont, pauseLabel,
                       {(sw - pm.x) * 0.5f, sh * 0.42f}, ps, 2.0f,
                       ::Color {255, 220, 120, 255});
            DrawTextEx(metaFont, "RECORD / F9  CAPTURE     SPACE  RESUME     ESC  TITLE",
                       {(sw * 0.5f) - 220.0f * ui, sh * 0.42f + ps + 12.0f * ui},
                       14.0f * ui, 2.0f, ::Color {220, 210, 190, 230});
        }
        return recordClicked;
    }

private:
    /** Rust / Steam trailer language: short system verbs, not lore titles. */
    static const char* marketingFeature(const ShotCard& c) {
        if (c.clean) return nullptr;
        switch (c.cam) {
            case Cam::DawnRise:       return "ENTER THE WORLD";
            case Cam::AngelaCraft:    return "CRAFT YOUR FIRST TOOLS";
            case Cam::ZimCrane:       return "EXPLORE ANCIENT CITIES";
            case Cam::ZimGap:         return "WALK THE HARDENED GROUND";
            case Cam::ForestWalk:     return "ENTER THE CATHEDRAL";
            case Cam::Pyramids:       return "DISCOVER THE BUILDERS";
            case Cam::LabApproach:    return "UNCOVER THE REGISTRY";
            case Cam::SamanthaReveal: return nullptr; // face reveal — no chrome
            case Cam::CoastSkim:      return "CROSS THE TEMPEST SEA";
            case Cam::MemorySlow:
            case Cam::MemoryClose:
            case Cam::MemoryWide:     return "REMEMBER EVERY LIFE";
            case Cam::Simulation:     return "WEAR THE COSTUME";
            case Cam::MarketWalk:     return "TRADE ON MARKET DAY";
            case Cam::NightDescend:   return "FACE WHAT COUNTS";
            case Cam::RiftPass:       return "CROSS THE TEAR";
            case Cam::VenusDescent:   return "LEAVE THE AGREEMENT";
            case Cam::ShadowDrift:    return "THE REVERSAL";
            case Cam::ArtificialSun:  return "BUILD YOUR OWN LIGHT";
            case Cam::DistortorFight: return "SURVIVE";
            case Cam::AltheaRise:     return "SPEAK WITH THE WIND";
            case Cam::Unmaking:       return "UNMAKE THE ILLUSION";
            case Cam::FinalWide:
            case Cam::CreditsOrbit:   return "PROJECT INERTIA";
            default:                 return nullptr;
        }
    }

    /** Blocky Impact-family face — Rust trailers do not use serif lore type. */
    static Font bannerTypeface() {
        static Font f {};
        static bool tried = false;
        if (!tried) {
            tried = true;
            const char* paths[] = {
                "C:/Windows/Fonts/impact.ttf",
                "C:/Windows/Fonts/arialbd.ttf",
                "C:/Windows/Fonts/ariblk.ttf",
                "C:/Windows/Fonts/bahnschrift.ttf",
            };
            for (const char* p : paths) {
                if (!FileExists(p)) continue;
                f = LoadFontEx(p, 128, nullptr, 0);
                if (f.texture.id != 0) {
                    SetTextureFilter(f.texture, TEXTURE_FILTER_BILINEAR);
                    break;
                }
            }
            if (f.texture.id == 0) f = GetFontDefault();
        }
        return f;
    }

    /** Left-edge brush / torn smear under the feature text (Steam trailer look). */
    static void drawBrushSmear(float textX, float textY, float textW, float textH,
                               float ui, float a) {
        const float top = textY - 10.0f * ui;
        const float h = textH + 20.0f * ui;
        const float bodyEnd = textX + textW + 28.0f * ui;
        const ::Color ink {0, 0, 0, 220};
        const ::Color inkSoft {8, 4, 4, 180};

        // Bleed from the left edge of the frame.
        DrawRectangle(0, static_cast<int>(top), static_cast<int>(bodyEnd),
                      static_cast<int>(h), Fade(ink, a));
        DrawRectangle(0, static_cast<int>(top + 4.0f * ui),
                      static_cast<int>(bodyEnd * 0.92f),
                      static_cast<int>(h * 0.72f), Fade(inkSoft, a));

        // Jagged / torn right edge — staggered wedges so it reads as a brush stroke.
        const int wedges = 9;
        for (int i = 0; i < wedges; ++i) {
            const float t0 = static_cast<float>(i) / wedges;
            const float t1 = static_cast<float>(i + 1) / wedges;
            const float y0 = top + h * t0;
            const float y1 = top + h * t1;
            const float mid = (y0 + y1) * 0.5f;
            const float jut = (18.0f + 22.0f * std::fabs(std::sin(i * 1.7f + 0.4f))) * ui;
            const float base = bodyEnd - 8.0f * ui;
            DrawTriangle({base, y0}, {base + jut, mid}, {base, y1}, Fade(ink, a));
            if ((i % 2) == 0) {
                DrawTriangle({base - 6.0f * ui, y0 + 2.0f * ui},
                             {base + jut * 0.55f, mid},
                             {base - 6.0f * ui, y1 - 2.0f * ui},
                             Fade(inkSoft, a * 0.85f));
            }
        }

        // Soft top/bottom grit so the bar does not read as a UI panel.
        DrawRectangle(0, static_cast<int>(top - 3.0f * ui),
                      static_cast<int>(bodyEnd * 0.7f), static_cast<int>(5.0f * ui),
                      Fade(::Color {0, 0, 0, 90}, a));
        DrawRectangle(0, static_cast<int>(top + h - 2.0f * ui),
                      static_cast<int>(bodyEnd * 0.75f), static_cast<int>(6.0f * ui),
                      Fade(::Color {0, 0, 0, 110}, a));
    }

    /** Facepunch / Rust Steam cold-open — floating type over the world, no UI card. */
    void drawStudioCredit(const Font& nameFont, const Font& metaFont,
                          int sw, int sh, float cardA, float ui) const {
        if (shotIndex != 0 || card().cam != Cam::DawnRise) return;

        // Hold early while the camera pushes into the plains, then clear so
        // ENTER THE WORLD can stamp later in the same shot.
        float a = cardA;
        {
            const float appear = 0.40f;
            const float fadeIn = 0.70f;
            const float holdEnd = 3.55f;
            const float fadeOut = 0.85f;
            if (shotTime < appear) a = 0.0f;
            else if (shotTime < appear + fadeIn)
                a = ((shotTime - appear) / fadeIn) * cardA;
            else if (shotTime < holdEnd)
                a = cardA;
            else if (shotTime < holdEnd + fadeOut)
                a = (1.0f - (shotTime - holdEnd) / fadeOut) * cardA;
            else
                a = 0.0f;
        }
        if (a < 0.02f) return;

        // Cinematic letterbox — Steam trailers sell the frame before the name.
        const float bar = 78.0f * ui;
        DrawRectangle(0, 0, sw, static_cast<int>(bar), Fade(::Color {0, 0, 0, 255}, 0.94f * a));
        DrawRectangle(0, sh - static_cast<int>(bar), sw, static_cast<int>(bar + 2.0f),
                      Fade(::Color {0, 0, 0, 255}, 0.94f * a));

        // Soft mid-frame dim so white type survives the dawn sun — not a menu plate.
        DrawRectangle(0, static_cast<int>(bar), sw, sh - static_cast<int>(bar * 2.0f),
                      Fade(::Color {0, 0, 0, 255}, 0.22f * a));

        const Font& type = bannerTypeface();
        const char* studio = "REM STUDIOS";
        const char* presents = "PRESENTS";
        const char* site = "REM-STUDIOS.NET";

        const float titleSize = 58.0f * ui;
        const float titleSpace = titleSize * 0.08f; // Facepunch-wide tracking feel
        const Vector2 tm = MeasureTextEx(type, studio, titleSize, titleSpace);
        const float cx = static_cast<float>(sw) * 0.5f;
        const float cy = static_cast<float>(sh) * 0.46f - titleSize * 0.35f;

        // Hard drop shadow stack — reads over any biome without a rectangle.
        const ::Color ink {0, 0, 0, 255};
        const ::Color white {255, 255, 255, 255};
        DrawTextEx(type, studio, {cx - tm.x * 0.5f + 3.0f * ui, cy + 3.0f * ui},
                   titleSize, titleSpace, Fade(ink, 0.70f * a));
        DrawTextEx(type, studio, {cx - tm.x * 0.5f + 1.5f * ui, cy + 1.5f * ui},
                   titleSize, titleSpace, Fade(ink, 0.45f * a));
        DrawTextEx(type, studio, {cx - tm.x * 0.5f, cy},
                   titleSize, titleSpace, Fade(white, a));

        // Spaced PRESENTS under the mark.
        const float preSize = 13.0f * ui;
        const float preSpace = 6.0f * ui;
        const Vector2 pm = MeasureTextEx(metaFont, presents, preSize, preSpace);
        const float preY = cy + titleSize + 14.0f * ui;
        DrawTextEx(metaFont, presents,
                   {cx - pm.x * 0.5f + 1.0f * ui, preY + 1.0f * ui},
                   preSize, preSpace, Fade(ink, 0.55f * a));
        DrawTextEx(metaFont, presents,
                   {cx - pm.x * 0.5f, preY},
                   preSize, preSpace, Fade(white, 0.88f * a));

        // Site as a quiet third line — Facepunch skips this; Rem keeps the URL soft.
        const float siteSize = 11.0f * ui;
        const float siteSpace = 2.5f * ui;
        const Vector2 sm = MeasureTextEx(metaFont, site, siteSize, siteSpace);
        const float siteY = preY + preSize + 16.0f * ui;
        DrawTextEx(metaFont, site,
                   {cx - sm.x * 0.5f + 1.0f * ui, siteY + 1.0f * ui},
                   siteSize, siteSpace, Fade(ink, 0.50f * a));
        DrawTextEx(metaFont, site,
                   {cx - sm.x * 0.5f, siteY},
                   siteSize, siteSpace, Fade(::Color {210, 210, 210, 255}, 0.70f * a));

        (void)nameFont;
    }

    void drawMarketingBanner(const Font& /*nameFont*/, const Font& /*metaFont*/,
                             int /*sw*/, int sh, float cardA, float ui) const {
        const ShotCard& c = card();
        const char* feature = marketingFeature(c);
        if (feature == nullptr || feature[0] == '\0') return;

        // Pop in after the shot lands, hold, then clear before the cut — Rust pacing.
        // Opening shot: wait for Rem Studios credit to clear first.
        const float dur = currentShotDuration();
        float a = cardA;
        {
            const float appear = (c.cam == Cam::DawnRise) ? 4.45f : 0.85f;
            const float fadeIn = 0.40f;
            const float fadeOut = 0.75f;
            if (shotTime < appear) a = 0.0f;
            else if (shotTime < appear + fadeIn)
                a = ((shotTime - appear) / fadeIn) * cardA;
            else if (shotTime > dur - fadeOut)
                a = std::max(0.0f, (dur - shotTime) / fadeOut) * cardA;
            else
                a = cardA;
        }
        if (a < 0.02f) return;

        const Font& type = bannerTypeface();
        const float size = 48.0f * ui;
        const float spacing = size * 0.015f;
        const Vector2 m = MeasureTextEx(type, feature, size, spacing);
        const float x = 36.0f * ui;
        const float y = static_cast<float>(sh) - 88.0f * ui - m.y * 0.10f;

        drawBrushSmear(x, y, m.x, m.y, ui, a);

        // Deep red Impact stamp — Steam Rust feature language.
        const ::Color rustRed {220, 24, 24, 255};
        DrawTextEx(type, feature, {x + 3.0f * ui, y + 3.0f * ui}, size, spacing,
                   Fade(::Color {10, 0, 0, 255}, 0.60f * a));
        DrawTextEx(type, feature, {x + 1.2f * ui, y + 1.2f * ui}, size, spacing,
                   Fade(::Color {90, 8, 8, 255}, 0.40f * a));
        DrawTextEx(type, feature, {x, y}, size, spacing, Fade(rustRed, a));
    }

    static constexpr int kShotCount = 23;
    static const std::array<ShotCard, kShotCount> kCards;

    const ShotCard& card() const { return kCards[static_cast<std::size_t>(shotIndex)]; }

    float currentShotDuration() const { return card().duration; }

    static float shotFieldOfView(int idx) {
        const int safe = ((idx % kShotCount) + kShotCount) % kShotCount;
        return kCards[static_cast<std::size_t>(safe)].fovy;
    }

    int progressionTier() const {
        // The cut is the ladder: rungs only fill forward as shots pass,
        // so the panel never walks backwards when a card's dimension
        // belongs to an earlier band (village after jungle, etc.).
        const int last = std::max(1, kShotCount - 1);
        return std::min(6, (shotIndex * 6) / last);
    }

    int progressionLevel() const {
        const float u = (static_cast<float>(shotIndex) + shotProgress())
            / static_cast<float>(std::max(1, kShotCount));
        return 1 + static_cast<int>(u * 13.0f);
    }

    void drawProgressionHud(const Font& serif, const Font& mono, int sw, int sh,
                            float a, float ui, bool hideChrome) const {
        (void)ui;
        (void)hideChrome;
        const ShotCard& c = card();
        const float u = (static_cast<float>(shotIndex) + shotProgress())
            / static_cast<float>(std::max(1, kShotCount));
        RpgLevelSystem::PathSheet s {};
        s.level = progressionLevel();
        s.xpNeed = 70 + (s.level - 1) * 40 + (s.level - 1) * (s.level - 1) * 10;
        const float into = u * 13.0f - static_cast<float>(s.level - 1);
        s.xp = static_cast<int>(std::max(0.0f, std::min(1.0f, into)) * static_cast<float>(s.xpNeed));
        s.stat[0] = 2 + static_cast<int>(u * 9.0f);
        s.stat[1] = 2 + static_cast<int>(u * 6.0f);
        s.stat[2] = 2 + static_cast<int>(u * 7.0f);
        s.stat[3] = 1 + static_cast<int>(u * 6.0f);
        s.tier = progressionTier();
        s.dimension = c.dimension;
        s.concussion = c.concussion;
        s.hint = "L  OPENS THIS SHEET IN THE WORLD";
        s.dockLeft = true;
        s.alpha = a;
        if ((c.flags & F_BOSS) != 0) {
            const float t = shotProgress();
            s.stat[0] = 8 + (t > 0.62f ? 1 : 0);
            s.stat[1] = 6;
            s.stat[2] = 7;
            s.stat[3] = 5 + (t > 0.72f ? 1 : 0);
            if (t > 0.55f && t < 0.82f) {
                s.levelUp = (t < 0.64f) ? (t - 0.55f) / 0.09f : (0.82f - t) / 0.18f;
            }
        }
        RpgLevelSystem::drawPathSheet(serif, mono, sw, sh, s, false);
    }

    void drawPreviewHud(const Font& mono, const Font& serif, int sw, int sh) const {
        const float ui = std::max(0.65f, std::min(sh / 900.0f, 1.5f));
        const ::Color cream {245, 230, 200, 255};
        const ::Color dim {180, 160, 120, 255};
        DrawRectangle(0, sh - static_cast<int>(78 * ui), sw, static_cast<int>(78 * ui), ::Color {8, 8, 10, 200});
        const char* mode = paused ? "PREVIEW  ·  PAUSED" : "PREVIEW  ·  PLAYING";
        DrawTextEx(mono, mode, {24.0f * ui, sh - 70.0f * ui}, 11.0f * ui, 2.0f, cream);
        DrawTextEx(mono, "ESC title  F6 freeplay  SPACE pause/resume  [ ] shots  UP/DOWN scrub  V 1st/3rd  P HUD  RECORD writes an MP4",
                   {24.0f * ui, sh - 52.0f * ui}, 10.0f * ui, 1.5f, dim);

        char buf[128];
        if (isPlayerCharacterShot()) {
            std::snprintf(buf, sizeof(buf), "SHOT %02d / %02d   %s   ·   %s",
                          shotIndex + 1, kShotCount, card().name,
                          trailerThirdPerson ? "3RD PERSON" : "1ST PERSON");
        } else {
            std::snprintf(buf, sizeof(buf), "SHOT %02d / %02d   %s",
                          shotIndex + 1, kShotCount, card().name);
        }
        DrawTextEx(serif, buf, {24.0f * ui, sh - 34.0f * ui}, 14.0f * ui, 1.0f, cream);

        const float barX = 24.0f * ui;
        const float barW = sw - 48.0f * ui;
        const float barY = sh - 12.0f * ui;
        DrawRectangleRec({barX, barY, barW, 4.0f * ui}, ::Color {40, 36, 30, 255});
        DrawRectangleRec({barX, barY, barW * shotProgress(), 4.0f * ui}, card().dimColor);

        // Side shot list (current ±4)
        float ly = 90.0f * ui;
        for (int d = -3; d <= 4; ++d) {
            const int i = shotIndex + d;
            if (i < 0 || i >= kShotCount) continue;
            const ShotCard& s = kCards[static_cast<std::size_t>(i)];
            const bool cur = (d == 0);
            char line[96];
            std::snprintf(line, sizeof(line), "%02d  %s%s", i + 1, s.name, s.clean ? "  ·" : "");
            DrawTextEx(mono, line, {sw - 320.0f * ui, ly}, cur ? 12.0f * ui : 10.0f * ui, 1.2f,
                       cur ? cream : Fade(dim, 0.7f));
            ly += cur ? 16.0f * ui : 13.0f * ui;
        }
    }

    static float drawWrappedCard(const Font& font, const char* text, float x, float y,
                                 float maxW, float size, ::Color col) {
        const float lineH = size * 1.4f;
        std::istringstream words {std::string(text)};
        std::string line;
        std::string word;
        float yy = y;
        while (words >> word) {
            const std::string trial = line.empty() ? word : line + " " + word;
            if (!line.empty() && MeasureTextEx(font, trial.c_str(), size, 1.0f).x > maxW) {
                DrawTextEx(font, line.c_str(), {x, yy}, size, 1.0f, col);
                yy += lineH;
                line = word;
            } else {
                line = trial;
            }
        }
        if (!line.empty()) {
            DrawTextEx(font, line.c_str(), {x, yy}, size, 1.0f, col);
            yy += lineH;
        }
        return yy - y;
    }

    bool enabled {false};
    bool previewMode {false};
    bool paused {false};
    bool cutWrapped {false};
    /** False = 1st person on character shots (default). V toggles true = 3rd. */
    bool trailerThirdPerson {false};
    int shotIndex {0};
    float shotTime {0.0f};
    // Spawn XZ of the savanna set, filled in once the world is built.
    bool savannaAnchorSet {false};
    float savannaAnchorX {0.0f};
    float savannaAnchorZ {0.0f};
    // Watering-hole shot: nearest-water cache (applyCamera is const).
    mutable int waterSeekShot {-1};
    mutable bool waterFound {false};
    mutable float waterX {0.0f};
    mutable float waterZ {0.0f};
};

