    GameStateManager gameStateManager {};
    InertiaTitleScreen titleScreen {};
    titleScreen.ensureLoaded();  // fonts + Althea GLB ready for trailer shots
    VisualEnvironmentAssets environmentAssets {};
    ShowcaseDirector showcase {};
    RealityShiftManager realityShift {};
